
import { createClient } from '@supabase/supabase-js';

class MemoryService {
    constructor() {
        this.shortTermMemory = []; // Array of last N interactions
        this.maxShortTermSize = 10;

        const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
        const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY;

        if (supabaseUrl && supabaseKey) {
            this.supabase = createClient(supabaseUrl, supabaseKey);
        } else {
            console.warn("MemoryService: Supabase credentials missing. Long-term memory disabled.");
            this.supabase = null;
        }
    }

    // Add a memory to short-term context
    addShortTerm(content, type = 'observation') {
        const memory = {
            content,
            type,
            timestamp: Date.now(),
            id: Math.random().toString(36).substr(2, 9)
        };

        this.shortTermMemory.push(memory);

        if (this.shortTermMemory.length > this.maxShortTermSize) {
            this.shortTermMemory.shift(); // Remove oldest
        }

        return memory;
    }

    // Get recent context formatted for LLM
    getShortTermContext() {
        return this.shortTermMemory
            .map(m => `[${new Date(m.timestamp).toLocaleTimeString()}] ${m.type.toUpperCase()}: ${m.content}`)
            .join('\n');
    }

    // Save important memory to long-term storage
    async saveLongTerm(content, tags = []) {
        if (!this.supabase) return null;

        try {
            const { data, error } = await this.supabase
                .from('soul_memories')
                .insert([
                    {
                        content,
                        tags,
                        timestamp: new Date().toISOString()
                    }
                ])
                .select();

            if (error) throw error;
            console.log("Memory saved to long-term:", content);
            return data;
        } catch (e) {
            // Fail silently or log warn, don't crash app
            console.warn("Failed to save long-term memory:", e.message);
            return null; // Fallback
        }
    }

    // Retrieve relevant past memories (Simple text search for now)
    // In future: Vector Store embedding search
    async retrieveLongTerm(query, limit = 3) {
        if (!this.supabase) return [];

        try {
            const { data, error } = await this.supabase
                .from('soul_memories')
                .select('content, timestamp')
                .textSearch('content', query, { type: 'websearch', config: 'english' })
                .limit(limit);

            if (error) throw error;
            return data || [];
        } catch (e) {
            console.warn("Memory retrieval failed:", e.message);
            return [];
        }
    }
}

export default new MemoryService();
