import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const CommandQueue = ({ isVisible, onToggle, queue = [] }) => {
  // We use the passed queue directly.
  // We can keep some internal state for visual effects if needed, but for now let's rely on the prop.

  const getStatusIcon = (status) => {
    switch (status) {
      case 'executing':
        return <Icon name="Play" size={14} className="text-primary animate-pulse" />;
      case 'completed':
        return <Icon name="Check" size={14} className="text-success" />;
      case 'pending':
        return <Icon name="Clock" size={14} className="text-warning" />;
      case 'queued':
        return <Icon name="Circle" size={14} className="text-text-tertiary" />;
      default:
        return <Icon name="Circle" size={14} className="text-text-tertiary" />;
    }
  };

  const commands = queue; // Map prop to local variable for easier refactoring if needed


  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'high':
        return 'border-l-accent';
      case 'normal':
        return 'border-l-primary';
      case 'low':
        return 'border-l-text-tertiary';
      default:
        return 'border-l-text-tertiary';
    }
  };

  const formatTimeAgo = (timestamp) => {
    const diff = Date.now() - timestamp.getTime();
    if (diff < 60000) return `${Math.floor(diff / 1000)}s ago`;
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return `${Math.floor(diff / 3600000)}h ago`;
  };

  return (
    <>
      {/* Toggle Button */}
      <button
        onClick={onToggle}
        className={`fixed top-1/2 right-0 transform -translate-y-1/2 z-1100 glass-morphism rounded-l-lg p-3 transition-smooth ${isVisible ? 'translate-x-0' : 'translate-x-2'
          }`}
        title="Command Queue"
      >
        <Icon name="List" size={20} className="text-primary" />
        {commands.length > 0 && (
          <div className="absolute -top-2 -left-2 bg-accent text-white text-xs rounded-full w-6 h-6 flex items-center justify-center animate-pulse">
            {commands.length}
          </div>
        )}
      </button>

      {/* Command Queue Panel */}
      <div className={`fixed top-0 right-0 h-full w-96 glass-morphism border-l border-white/20 transform transition-transform duration-300 z-1200 ${isVisible ? 'translate-x-0' : 'translate-x-full'
        }`}>
        {/* Header */}
        <div className="p-4 border-b border-white/10">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-heading font-semibold text-text-primary">Command Queue</h2>
            <button
              onClick={onToggle}
              className="p-2 rounded-lg text-text-secondary hover:text-text-primary hover:bg-white/5 transition-smooth"
            >
              <Icon name="X" size={18} />
            </button>
          </div>

          {/* Queue Controls - Removed for now as we use real time execution */}
          <div className="space-y-3 opacity-50 pointer-events-none">
            {/* Placeholders if needed or just empty */}
          </div>
        </div>

        {/* Queue Stats */}
        <div className="p-4 border-b border-white/10">
          <div className="grid grid-cols-3 gap-4 text-center">
            <div>
              <div className="text-lg font-bold text-primary">
                {commands.filter(c => c.status === 'executing').length}
              </div>
              <div className="text-xs text-text-secondary">Executing</div>
            </div>
            <div>
              <div className="text-lg font-bold text-warning">
                {commands.filter(c => c.status === 'pending').length}
              </div>
              <div className="text-xs text-text-secondary">Pending</div>
            </div>
            <div>
              <div className="text-lg font-bold text-text-tertiary">
                {commands.filter(c => c.status === 'queued').length}
              </div>
              <div className="text-xs text-text-secondary">Queued</div>
            </div>
          </div>
        </div>

        {/* Command List */}
        <div className="flex-1 overflow-y-auto">
          {commands.length === 0 ? (
            <div className="p-8 text-center">
              <Icon name="Inbox" size={48} className="text-text-tertiary mx-auto mb-4" />
              <p className="text-text-secondary">No commands in queue</p>
              <p className="text-xs text-text-tertiary mt-2">
                Commands will appear here as users interact with Soul Drive
              </p>
            </div>
          ) : (
            <div className="p-2">
              {commands.map((command, index) => (
                <div
                  key={command.id}
                  className={`p-3 mb-2 rounded-lg border-l-4 transition-smooth ${getPriorityColor(command.priority)} ${command.status === 'executing' ? 'bg-primary/10 border-primary/30' : 'bg-surface/30 hover:bg-surface/50'
                    }`}
                >
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex items-center space-x-2">
                      {getStatusIcon(command.status)}
                      <span className="text-sm font-medium text-text-primary">
                        {command.user}
                      </span>
                      {command.user === 'You' && (
                        <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full">
                          You
                        </span>
                      )}
                    </div>
                    <span className="text-xs text-text-tertiary">
                      #{index + 1}
                    </span>
                  </div>

                  <p className="text-sm text-text-secondary font-mono mb-2">
                    {command.command}
                  </p>

                  <div className="flex items-center justify-between text-xs text-text-tertiary">
                    <span>{formatTimeAgo(command.timestamp)}</span>
                    {command.status === 'executing' && (
                      <span className="text-primary">
                        {command.estimatedTime}s remaining
                      </span>
                    )}
                    {command.status !== 'executing' && (
                      <span>~{command.estimatedTime}s</span>
                    )}
                  </div>

                  {command.status === 'executing' && (
                    <div className="w-full bg-surface rounded-full h-1 mt-2">
                      <div
                        className="bg-primary h-1 rounded-full transition-all duration-1000"
                        style={{
                          width: `${100 - (command.estimatedTime / 8) * 100}%`
                        }}
                      />
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-white/10">
          <div className="text-xs text-text-tertiary text-center">
            <Icon name="Users" size={12} className="inline mr-1" />
            Real-time collaborative queue • Updates automatically
          </div>
        </div>
      </div>

      {/* Backdrop */}
      {isVisible && (
        <div
          className="fixed inset-0 bg-background/50 backdrop-blur-sm z-1150"
          onClick={onToggle}
        />
      )}
    </>
  );
};

export default CommandQueue;