import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from 'components/AppIcon';
import MetricsCard from './components/MetricsCard';
import ApiManagement from './components/ApiManagement';
import QueueControls from './components/QueueControls';
import UserAnalytics from './components/UserAnalytics';
import PaymentManagement from './components/PaymentManagement';
import QuickActions from './components/QuickActions';
import SystemMonitoring from './components/SystemMonitoring';

import { collection, getCountFromServer } from 'firebase/firestore';
import { db } from '../../services/firebase';

const AdminControlPanel = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [activeTab, setActiveTab] = useState('api');
  const [systemAlerts, setSystemAlerts] = useState([]);
  const [realMetrics, setRealMetrics] = useState({
    activeUsers: 0,
    queueLength: 0,
    systemPerformance: 100,
    revenue: 0
  });

  const navigate = useNavigate();

  useEffect(() => {
    // Load Real metrics if auth
    if (isAuthenticated) {
      const fetchStats = async () => {
        try {
          const usersSnap = await getCountFromServer(collection(db, "users"));
          const chatsSnap = await getCountFromServer(collection(db, "community_chat"));
          setRealMetrics({
            activeUsers: usersSnap.data().count,
            queueLength: chatsSnap.data().count, // Using chat volume as proxy for activity
            systemPerformance: 100,
            revenue: 0 // Stripe webhook needed for real revenue
          });
        } catch (e) {
          console.error("Stats fetch error:", e);
        }
      };
      fetchStats();
    }
  }, [isAuthenticated]);

  const handleLogin = (e) => {
    e.preventDefault();
    if (password === 'Zawe1234!') {
      setIsAuthenticated(true);
      setError('');
    } else {
      setError('Access Denied: Invalid Credentials');
      setTimeout(() => setError(''), 3000);
    }
  };

  const tabs = [
    { id: 'api', label: 'API Management', icon: 'Key' },
    { id: 'queue', label: 'Queue Controls', icon: 'Settings' },
    { id: 'analytics', label: 'User Analytics', icon: 'BarChart3' },
    { id: 'payments', label: 'Payment Management', icon: 'CreditCard' }
  ];

  const getAlertIcon = (type) => {
    switch (type) {
      case 'error':
        return 'AlertCircle';
      case 'warning':
        return 'AlertTriangle';
      case 'info':
        return 'Info';
      default:
        return 'Bell';
    }
  };

  const getAlertColor = (type) => {
    switch (type) {
      case 'error':
        return 'text-error border-error/20 bg-error/5';
      case 'warning':
        return 'text-warning border-warning/20 bg-warning/5';
      case 'info':
        return 'text-primary border-primary/20 bg-primary/5';
      default:
        return 'text-text-secondary border-white/10 bg-white/5';
    }
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center px-4">
        <div className="w-full max-w-md">
          <div className="glass-morphism rounded-xl p-8 border border-white/20">
            <div className="text-center mb-8">
              <div className="w-16 h-16 bg-gradient-to-br from-accent to-accent-600 rounded-full flex items-center justify-center mx-auto mb-4 neon-glow">
                <Icon name="Shield" size={32} color="white" />
              </div>
              <h1 className="text-2xl font-heading font-bold text-text-primary mb-2">
                Admin Access Required
              </h1>
              <p className="text-text-secondary">
                Enter administrator credentials for system access
              </p>
            </div>

            <form onSubmit={handleLogin} className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-text-primary mb-2">
                  Admin Password
                </label>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-surface/50 border border-white/10 rounded-lg px-4 py-3 text-text-primary placeholder-text-tertiary focus:outline-none focus:border-accent focus:ring-1 focus:ring-accent transition-smooth"
                  placeholder="Enter admin password"
                  required
                />
                {error && (
                  <p className="text-error text-sm mt-2 flex items-center">
                    <Icon name="AlertCircle" size={16} className="mr-1" />
                    {error}
                  </p>
                )}
              </div>

              <div className="flex space-x-4">
                <button
                  type="button"
                  onClick={() => navigate('/main-3d-world-interface')}
                  className="flex-1 px-4 py-3 border border-white/20 text-text-secondary hover:text-text-primary hover:bg-white/5 rounded-lg transition-smooth"
                >
                  Back to World
                </button>
                <button
                  type="submit"
                  className="flex-1 px-4 py-3 bg-accent hover:bg-accent-600 text-white font-medium rounded-lg transition-smooth neon-glow"
                >
                  Access Panel
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between mb-8">
          <div>
            <h1 className="text-3xl font-heading font-bold text-text-primary mb-2">
              Admin Control Panel
            </h1>
            <p className="text-text-secondary">
              Comprehensive system management for Soul Drive
            </p>
          </div>
          <div className="flex items-center space-x-4 mt-4 lg:mt-0">
            <div className="flex items-center space-x-2 text-sm text-text-secondary">
              <div className="w-2 h-2 bg-success rounded-full animate-pulse" />
              <span>System Online</span>
            </div>
            <button
              onClick={() => setIsAuthenticated(false)}
              className="flex items-center space-x-2 px-4 py-2 bg-surface/50 hover:bg-surface/70 text-text-secondary hover:text-text-primary rounded-lg transition-smooth"
            >
              <Icon name="LogOut" size={16} />
              <span>Logout</span>
            </button>
          </div>
        </div>

        {/* System Alerts */}
        {systemAlerts.length > 0 && (
          <div className="mb-8">
            <h2 className="text-lg font-heading font-semibold text-text-primary mb-4">
              System Alerts
            </h2>
            <div className="space-y-3">
              {systemAlerts.map((alert) => (
                <div
                  key={alert.id}
                  className={`p-4 rounded-lg border ${getAlertColor(alert.type)} transition-smooth`}
                >
                  <div className="flex items-start space-x-3">
                    <Icon name={getAlertIcon(alert.type)} size={20} className="flex-shrink-0 mt-0.5" />
                    <div className="flex-1">
                      <p className="font-medium">{alert.message}</p>
                      <p className="text-sm opacity-75 mt-1">
                        {alert.timestamp.toLocaleTimeString()}
                      </p>
                    </div>
                    <button className="text-current opacity-50 hover:opacity-100 transition-smooth">
                      <Icon name="X" size={16} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-3 space-y-8">
            {/* Metrics Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              <MetricsCard
                title="Total Users"
                value={realMetrics?.activeUsers || 0}
                icon="Users"
                color="primary"
                trend="Live"
              />
              <MetricsCard
                title="Chat Volume"
                value={realMetrics?.queueLength || 0}
                icon="MessageSquare"
                color="warning"
                trend="Live"
              />
              <MetricsCard
                title="System Status"
                value={`${realMetrics?.systemPerformance || 100}%`}
                icon="Activity"
                color="success"
                trend="Stable"
              />
              <MetricsCard
                title="Revenue"
                value={`$${(realMetrics?.revenue || 0).toFixed(2)}`}
                icon="DollarSign"
                color="accent"
                trend="--%"
              />
            </div>

            {/* Tabbed Interface */}
            <div className="glass-morphism rounded-xl border border-white/20">
              {/* Tab Navigation */}
              <div className="border-b border-white/10">
                <div className="flex flex-wrap">
                  {tabs.map((tab) => (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`flex items-center space-x-2 px-6 py-4 font-medium transition-smooth ${activeTab === tab.id
                        ? 'text-primary border-b-2 border-primary bg-primary/5' : 'text-text-secondary hover:text-text-primary hover:bg-white/5'
                        }`}
                    >
                      <Icon name={tab.icon} size={18} />
                      <span className="hidden sm:inline">{tab.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Tab Content */}
              <div className="p-6">
                {activeTab === 'api' && <ApiManagement />}
                {activeTab === 'queue' && <QueueControls />}
                {activeTab === 'analytics' && <UserAnalytics />}
                {activeTab === 'payments' && <PaymentManagement />}
              </div>
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            <QuickActions />
            <SystemMonitoring />
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminControlPanel;