import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import Icon from '../AppIcon';
import { useCommandContext } from '../../contexts/CommandContext';
import { generateContextualCommands, generateRandomCommands } from '../../utils/proceduralGeneration';

const CommandInterface = () => {
  const { executeCommand, hasExecutor } = useCommandContext();
  const [command, setCommand] = useState('');
  const [commandQueue, setCommandQueue] = useState([]);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const inputRef = useRef(null);
  const location = useLocation();

  const isMainWorld = location.pathname === '/main-3d-world-interface';

  const commandSuggestions = [
    'move forward',
    'turn left',
    'turn right',
    'look around',
    'interact with object',
    'say hello',
    'dance',
    'sit down',
    'wave hand',
    'explore area',
    'make coffee',
    'stand up',
    'look at window',
    'relax',
    'stretch'
  ];

  // Add procedural suggestions
  const [proceduralSuggestions, setProceduralSuggestions] = useState([]);

  useEffect(() => {
    // Generate contextual and random commands periodically
    const updateSuggestions = () => {
      const randomCommands = generateRandomCommands();
      const contextualCommands = generateContextualCommands(
        { timeOfDay: 'night', weather: 'clear' },
        { position: { x: 0, y: 0, z: 0 }, activity: 'idle' }
      );
      
      // Combine all suggestions
      const allSuggestions = [
        ...commandSuggestions,
        ...contextualCommands,
        ...randomCommands.slice(0, 5)
      ];
      
      setProceduralSuggestions(allSuggestions);
    };

    updateSuggestions();
    // Update suggestions every 30 seconds
    const interval = setInterval(updateSuggestions, 30000);
    
    return () => clearInterval(interval);
  }, []);

  const mockQueue = [
    { id: 1, command: 'move forward', status: 'executing', user: 'Player1' },
    { id: 2, command: 'look around', status: 'pending', user: 'Player2' },
    { id: 3, command: 'wave hand', status: 'pending', user: 'You' }
  ];

  useEffect(() => {
    setCommandQueue(mockQueue);
  }, []);

  useEffect(() => {
    if (command.length > 0) {
      const allSuggestions = proceduralSuggestions.length > 0 ? proceduralSuggestions : commandSuggestions;
      const filtered = allSuggestions.filter(suggestion =>
        suggestion.toLowerCase().includes(command.toLowerCase())
      );
      setSuggestions(filtered.slice(0, 8)); // Show more suggestions
      setShowSuggestions(filtered.length > 0);
    } else {
      setShowSuggestions(false);
    }
  }, [command, proceduralSuggestions]);

  const handleCommandSubmit = (e) => {
    e.preventDefault();
    if (command.trim() && hasExecutor) {
      const newCommand = {
        id: Date.now(),
        command: command.trim(),
        status: 'pending',
        user: 'You'
      };
      setCommandQueue(prev => [...prev, newCommand]);
      
      // Execute the command in the 3D world
      executeCommand(command.trim());
      
      setCommand('');
      setShowSuggestions(false);
      
      // Simulate command processing in UI
      setTimeout(() => {
        setCommandQueue(prev => 
          prev.map(cmd => 
            cmd.id === newCommand.id 
              ? { ...cmd, status: 'executing' }
              : cmd
          )
        );
      }, 500);

      setTimeout(() => {
        setCommandQueue(prev => prev.filter(cmd => cmd.id !== newCommand.id));
      }, 3000);
    }
  };

  const handleSuggestionClick = (suggestion) => {
    setCommand(suggestion);
    setShowSuggestions(false);
    inputRef.current?.focus();
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'executing':
        return <Icon name="Play" size={14} className="text-primary animate-pulse" />;
      case 'pending':
        return <Icon name="Clock" size={14} className="text-warning" />;
      case 'completed':
        return <Icon name="Check" size={14} className="text-success" />;
      default:
        return <Icon name="Circle" size={14} className="text-text-tertiary" />;
    }
  };

  if (!isMainWorld) {
    return null;
  }

  const isCommandSystemReady = isMainWorld && hasExecutor;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-1100">
      {/* Command Queue (when expanded) */}
      {isExpanded && commandQueue.length > 0 && (
        <div className="absolute bottom-20 right-6 w-80 glass-morphism rounded-t-xl border-b-0 animate-slide-up">
          <div className="p-4 border-b border-white/10">
            <div className="flex items-center justify-between">
              <h3 className="font-heading font-semibold text-text-primary">Command Queue</h3>
              <span className="text-xs text-text-secondary">{commandQueue.length} active</span>
            </div>
          </div>
          <div className="max-h-60 overflow-y-auto">
            {commandQueue.map((item) => (
              <div key={item.id} className="p-3 border-b border-white/5 last:border-b-0">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2">
                    {getStatusIcon(item.status)}
                    <span className="text-sm text-text-primary font-mono">{item.command}</span>
                  </div>
                  <span className="text-xs text-text-tertiary">{item.user}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Command Input */}
      <div className="glass-morphism border-t border-white/10">
        <div className="px-6 py-4">
          <form onSubmit={handleCommandSubmit} className="relative">
            <div className="flex items-center space-x-4">
              <div className="flex-1 relative">
                <input
                  ref={inputRef}
                  type="text"
                  value={command}
                  onChange={(e) => setCommand(e.target.value)}
                  onFocus={() => setIsTyping(true)}
                  onBlur={() => setTimeout(() => setIsTyping(false), 200)}
                  placeholder="Enter command for Soul Drive..."
                  className="w-full bg-surface/50 border border-white/10 rounded-lg px-4 py-3 text-text-primary placeholder-text-tertiary focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-smooth font-mono"
                />
                
                {/* Suggestions Dropdown */}
                {showSuggestions && (
                  <div className="absolute bottom-full left-0 right-0 mb-2 glass-morphism rounded-lg border border-white/10 animate-slide-up">
                    {suggestions.map((suggestion, index) => (
                      <button
                        key={index}
                        type="button"
                        onClick={() => handleSuggestionClick(suggestion)}
                        className="w-full text-left px-4 py-2 text-text-secondary hover:text-text-primary hover:bg-white/5 transition-smooth first:rounded-t-lg last:rounded-b-lg font-mono text-sm"
                      >
                        {suggestion}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <button
                type="submit"
                disabled={!command.trim() || !hasExecutor}
                className="bg-primary hover:bg-primary-600 disabled:bg-surface disabled:text-text-tertiary text-white p-3 rounded-lg transition-smooth flex items-center justify-center neon-glow disabled:shadow-none"
              >
                <Icon name="Send" size={18} />
              </button>

              <button
                type="button"
                onClick={() => setIsExpanded(!isExpanded)}
                className={`p-3 rounded-lg transition-smooth flex items-center justify-center ${
                  isExpanded 
                    ? 'bg-primary/20 text-primary border border-primary/30' :'bg-surface/50 text-text-secondary hover:text-text-primary hover:bg-white/5'
                }`}
              >
                <Icon name="List" size={18} />
                {commandQueue.length > 0 && (
                  <span className="absolute -top-1 -right-1 bg-accent text-white text-xs rounded-full w-5 h-5 flex items-center justify-center">
                    {commandQueue.length}
                  </span>
                )}
              </button>
            </div>

            {/* Typing Indicator */}
            {isTyping && (
              <div className="absolute -top-8 left-0 text-xs text-text-tertiary">
                <Icon name="Type" size={12} className="inline mr-1" />
                Typing command...
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
};

export default CommandInterface;