import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const ApiManagement = () => {
  const [apiKey, setApiKey] = useState('');
  const [isKeyVisible, setIsKeyVisible] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState('disconnected');
  const [isTestingConnection, setIsTestingConnection] = useState(false);

  const mockApiKey = 'AIzaSyBxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';

  const handleSaveApiKey = () => {
    if (apiKey.trim()) {
      console.log('Saving API key:', apiKey);
      // Mock save success
      setConnectionStatus('connected');
    }
  };

  const handleTestConnection = async () => {
    setIsTestingConnection(true);
    // Mock API test
    setTimeout(() => {
      setConnectionStatus('connected');
      setIsTestingConnection(false);
    }, 2000);
  };

  const getStatusColor = () => {
    switch (connectionStatus) {
      case 'connected':
        return 'text-success';
      case 'error':
        return 'text-error';
      default:
        return 'text-warning';
    }
  };

  const getStatusIcon = () => {
    switch (connectionStatus) {
      case 'connected':
        return 'CheckCircle';
      case 'error':
        return 'XCircle';
      default:
        return 'AlertCircle';
    }
  };

  const getStatusText = () => {
    switch (connectionStatus) {
      case 'connected':
        return 'Connected';
      case 'error':
        return 'Connection Failed';
      default:
        return 'Not Connected';
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-heading font-semibold text-text-primary mb-2">
          Gemini API Configuration
        </h3>
        <p className="text-text-secondary text-sm">
          Configure your Gemini API key for AI-driven Soul behavior and speech generation.
        </p>
      </div>

      {/* Connection Status */}
      <div className="flex items-center justify-between p-4 bg-surface/30 rounded-lg border border-white/10">
        <div className="flex items-center space-x-3">
          <Icon name={getStatusIcon()} size={20} className={getStatusColor()} />
          <div>
            <p className="font-medium text-text-primary">API Status</p>
            <p className={`text-sm ${getStatusColor()}`}>{getStatusText()}</p>
          </div>
        </div>
        <button
          onClick={handleTestConnection}
          disabled={isTestingConnection || !apiKey}
          className="flex items-center space-x-2 px-4 py-2 bg-primary hover:bg-primary-600 disabled:bg-surface disabled:text-text-tertiary text-white rounded-lg transition-smooth"
        >
          {isTestingConnection ? (
            <>
              <Icon name="Loader2" size={16} className="animate-spin" />
              <span>Testing...</span>
            </>
          ) : (
            <>
              <Icon name="Zap" size={16} />
              <span>Test Connection</span>
            </>
          )}
        </button>
      </div>

      {/* API Key Input */}
      <div className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-text-primary mb-2">
            Gemini API Key
          </label>
          <div className="relative">
            <input
              type={isKeyVisible ? 'text' : 'password'}
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
              placeholder="Enter your Gemini API key"
              className="w-full bg-surface/50 border border-white/10 rounded-lg px-4 py-3 pr-12 text-text-primary placeholder-text-tertiary focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-smooth font-mono"
            />
            <button
              type="button"
              onClick={() => setIsKeyVisible(!isKeyVisible)}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-text-secondary hover:text-text-primary transition-smooth"
            >
              <Icon name={isKeyVisible ? 'EyeOff' : 'Eye'} size={18} />
            </button>
          </div>
          <p className="text-xs text-text-tertiary mt-2">
            Your API key is encrypted and stored securely. Never share your API key publicly.
          </p>
        </div>

        <div className="flex space-x-4">
          <button
            onClick={handleSaveApiKey}
            disabled={!apiKey.trim()}
            className="flex items-center space-x-2 px-6 py-3 bg-success hover:bg-success-600 disabled:bg-surface disabled:text-text-tertiary text-white font-medium rounded-lg transition-smooth"
          >
            <Icon name="Save" size={16} />
            <span>Save Configuration</span>
          </button>
          <button
            onClick={() => setApiKey(mockApiKey)}
            className="flex items-center space-x-2 px-6 py-3 border border-white/20 text-text-secondary hover:text-text-primary hover:bg-white/5 rounded-lg transition-smooth"
          >
            <Icon name="Key" size={16} />
            <span>Use Demo Key</span>
          </button>
        </div>
      </div>

      {/* API Usage Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="p-4 bg-surface/20 rounded-lg border border-white/10">
          <div className="flex items-center space-x-2 mb-2">
            <Icon name="BarChart3" size={16} className="text-primary" />
            <span className="text-sm font-medium text-text-primary">Requests Today</span>
          </div>
          <p className="text-2xl font-bold text-text-primary">1,247</p>
          <p className="text-xs text-text-secondary">+15% from yesterday</p>
        </div>
        
        <div className="p-4 bg-surface/20 rounded-lg border border-white/10">
          <div className="flex items-center space-x-2 mb-2">
            <Icon name="Clock" size={16} className="text-warning" />
            <span className="text-sm font-medium text-text-primary">Avg Response</span>
          </div>
          <p className="text-2xl font-bold text-text-primary">1.2s</p>
          <p className="text-xs text-text-secondary">Within normal range</p>
        </div>
        
        <div className="p-4 bg-surface/20 rounded-lg border border-white/10">
          <div className="flex items-center space-x-2 mb-2">
            <Icon name="AlertTriangle" size={16} className="text-error" />
            <span className="text-sm font-medium text-text-primary">Error Rate</span>
          </div>
          <p className="text-2xl font-bold text-text-primary">0.3%</p>
          <p className="text-xs text-text-secondary">Below 1% threshold</p>
        </div>
      </div>
    </div>
  );
};

export default ApiManagement;