import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const QueueControls = () => {
  const [queueSpeed, setQueueSpeed] = useState(75);
  const [effectIntensity, setEffectIntensity] = useState(60);
  const [autoProcessing, setAutoProcessing] = useState(true);
  const [priorityMode, setPriorityMode] = useState(false);

  const mockQueueData = [
    { id: 1, command: 'move forward', user: 'Player1', priority: 'normal', estimatedTime: '2s' },
    { id: 2, command: 'look around', user: 'Player2', priority: 'high', estimatedTime: '1s' },
    { id: 3, command: 'wave hand', user: 'Player3', priority: 'normal', estimatedTime: '3s' },
    { id: 4, command: 'sit down', user: 'Player4', priority: 'low', estimatedTime: '4s' }
  ];

  const handleSpeedChange = (value) => {
    setQueueSpeed(value);
    console.log('Queue speed updated:', value);
  };

  const handleIntensityChange = (value) => {
    setEffectIntensity(value);
    console.log('Effect intensity updated:', value);
  };

  const clearQueue = () => {
    console.log('Clearing command queue');
    // Mock queue clear
  };

  const pauseQueue = () => {
    console.log('Pausing queue processing');
    // Mock queue pause
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'high':
        return 'text-error bg-error/10 border-error/20';
      case 'normal':
        return 'text-primary bg-primary/10 border-primary/20';
      case 'low':
        return 'text-text-secondary bg-surface/20 border-white/10';
      default:
        return 'text-text-secondary bg-surface/20 border-white/10';
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-heading font-semibold text-text-primary mb-2">
          Queue Processing Controls
        </h3>
        <p className="text-text-secondary text-sm">
          Adjust command processing speed and visual effect intensity with real-time preview.
        </p>
      </div>

      {/* Control Sliders */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-text-primary mb-3">
              Queue Processing Speed
            </label>
            <div className="space-y-3">
              <input
                type="range"
                min="10"
                max="100"
                value={queueSpeed}
                onChange={(e) => handleSpeedChange(parseInt(e.target.value))}
                className="w-full h-2 bg-surface rounded-lg appearance-none cursor-pointer slider"
              />
              <div className="flex justify-between text-xs text-text-secondary">
                <span>Slow</span>
                <span className="font-medium text-primary">{queueSpeed}%</span>
                <span>Fast</span>
              </div>
            </div>
          </div>

          <div className="p-3 bg-surface/20 rounded-lg border border-white/10">
            <div className="flex items-center space-x-2 text-sm">
              <Icon name="Info" size={16} className="text-primary" />
              <span className="text-text-secondary">
                Current processing: {(queueSpeed / 10).toFixed(1)} commands/second
              </span>
            </div>
          </div>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-text-primary mb-3">
              Visual Effect Intensity
            </label>
            <div className="space-y-3">
              <input
                type="range"
                min="0"
                max="100"
                value={effectIntensity}
                onChange={(e) => handleIntensityChange(parseInt(e.target.value))}
                className="w-full h-2 bg-surface rounded-lg appearance-none cursor-pointer slider"
              />
              <div className="flex justify-between text-xs text-text-secondary">
                <span>Subtle</span>
                <span className="font-medium text-primary">{effectIntensity}%</span>
                <span>Intense</span>
              </div>
            </div>
          </div>

          <div className="p-3 bg-surface/20 rounded-lg border border-white/10">
            <div className="flex items-center space-x-2 text-sm">
              <Icon name="Sparkles" size={16} className="text-primary" />
              <span className="text-text-secondary">
                Effect level: {effectIntensity > 75 ? 'High' : effectIntensity > 50 ? 'Medium' : 'Low'}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Toggle Controls */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="flex items-center justify-between p-4 bg-surface/20 rounded-lg border border-white/10">
          <div className="flex items-center space-x-3">
            <Icon name="Play" size={20} className="text-success" />
            <div>
              <p className="font-medium text-text-primary">Auto Processing</p>
              <p className="text-sm text-text-secondary">Automatically process queued commands</p>
            </div>
          </div>
          <button
            onClick={() => setAutoProcessing(!autoProcessing)}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              autoProcessing ? 'bg-success' : 'bg-surface'
            }`}
          >
            <span
              className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                autoProcessing ? 'translate-x-6' : 'translate-x-1'
              }`}
            />
          </button>
        </div>

        <div className="flex items-center justify-between p-4 bg-surface/20 rounded-lg border border-white/10">
          <div className="flex items-center space-x-3">
            <Icon name="Zap" size={20} className="text-warning" />
            <div>
              <p className="font-medium text-text-primary">Priority Mode</p>
              <p className="text-sm text-text-secondary">Process high-priority commands first</p>
            </div>
          </div>
          <button
            onClick={() => setPriorityMode(!priorityMode)}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              priorityMode ? 'bg-warning' : 'bg-surface'
            }`}
          >
            <span
              className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                priorityMode ? 'translate-x-6' : 'translate-x-1'
              }`}
            />
          </button>
        </div>
      </div>

      {/* Queue Actions */}
      <div className="flex flex-wrap gap-4">
        <button
          onClick={clearQueue}
          className="flex items-center space-x-2 px-4 py-2 bg-error hover:bg-error-600 text-white font-medium rounded-lg transition-smooth"
        >
          <Icon name="Trash2" size={16} />
          <span>Clear Queue</span>
        </button>
        <button
          onClick={pauseQueue}
          className="flex items-center space-x-2 px-4 py-2 bg-warning hover:bg-warning-600 text-white font-medium rounded-lg transition-smooth"
        >
          <Icon name="Pause" size={16} />
          <span>Pause Processing</span>
        </button>
        <button className="flex items-center space-x-2 px-4 py-2 border border-white/20 text-text-secondary hover:text-text-primary hover:bg-white/5 rounded-lg transition-smooth">
          <Icon name="RotateCcw" size={16} />
          <span>Reset Settings</span>
        </button>
      </div>

      {/* Current Queue Preview */}
      <div>
        <h4 className="text-md font-heading font-semibold text-text-primary mb-4">
          Current Queue ({mockQueueData.length} commands)
        </h4>
        <div className="space-y-2">
          {mockQueueData.map((item, index) => (
            <div key={item.id} className="flex items-center justify-between p-3 bg-surface/20 rounded-lg border border-white/10">
              <div className="flex items-center space-x-3">
                <span className="text-sm font-mono text-text-tertiary">#{index + 1}</span>
                <span className="font-mono text-text-primary">{item.command}</span>
                <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getPriorityColor(item.priority)}`}>
                  {item.priority}
                </span>
              </div>
              <div className="flex items-center space-x-3 text-sm text-text-secondary">
                <span>{item.user}</span>
                <span>~{item.estimatedTime}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default QueueControls;