import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from 'components/AppIcon';

const PaymentSuccess = () => {
    const navigate = useNavigate();
    const [countdown, setCountdown] = useState(4);

    useEffect(() => {
        // Countdown
        const timer = setInterval(() => {
            setCountdown(prev => {
                if (prev <= 1) {
                    clearInterval(timer);
                    navigate('/'); // Back to world
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => clearInterval(timer);
    }, [navigate]);

    return (
        <div className="min-h-screen bg-black flex items-center justify-center relative overflow-hidden text-center p-6">

            {/* Background Burst */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,#00ffff_0%,transparent_70%)] opacity-20 animate-pulse"></div>

            {/* Content */}
            <div className="relative z-10 glass-morphism p-10 rounded-2xl border border-primary box-shadow-[0_0_50px_rgba(0,255,255,0.5)] transform animate-[scale-in_0.5s_ease-out]">

                {/* Icon */}
                <div className="w-24 h-24 bg-gradient-to-br from-primary to-accent rounded-full mx-auto mb-6 flex items-center justify-center shadow-[0_0_30px_#00ffff]">
                    <Icon name="Check" size={48} className="text-white" />
                </div>

                <h1 className="text-4xl md:text-5xl font-heading font-bold text-white mb-2 tracking-wide drop-shadow-[0_0_10px_rgba(255,255,255,0.8)]">
                    ACCESS GRANTED
                </h1>

                <p className="text-xl text-primary-200 mb-8 font-light">
                    The Soul has been upgraded.
                </p>

                {/* Progress Bar */}
                <div className="w-full bg-white/10 h-2 rounded-full mb-4 overflow-hidden">
                    <div className="bg-primary h-full animate-[progress_4s_linear_forwards]" style={{ width: '100%' }}></div>
                </div>

                <div className="text-sm text-text-tertiary">
                    Returning to simulation in <span className="text-white font-bold">{countdown}</span>s...
                </div>
            </div>

            {/* Floating Particles (Simple CSS) */}
            {[...Array(20)].map((_, i) => (
                <div
                    key={i}
                    className="absolute bg-primary rounded-full opacity-50 animate-float"
                    style={{
                        width: Math.random() * 10 + 2 + 'px',
                        height: Math.random() * 10 + 2 + 'px',
                        left: Math.random() * 100 + '%',
                        top: Math.random() * 100 + '%',
                        animationDuration: Math.random() * 3 + 2 + 's',
                        animationDelay: Math.random() * 2 + 's'
                    }}
                />
            ))}

            <style>{`
                @keyframes scale-in {
                    0% { transform: scale(0.8); opacity: 0; }
                    100% { transform: scale(1); opacity: 1; }
                }
                @keyframes progress {
                    0% { width: 0%; }
                    100% { width: 100%; }
                }
                @keyframes float {
                    0% { transform: translateY(0px); opacity: 0; }
                    50% { opacity: 0.8; }
                    100% { transform: translateY(-100px); opacity: 0; }
                }
            `}</style>
        </div>
    );
};

export default PaymentSuccess;
