import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const LoadingAnimation = () => {
  const [loadingStep, setLoadingStep] = useState(0);
  const [progress, setProgress] = useState(0);

  const loadingSteps = [
    { text: "Initializing Soul Drive...", icon: "Zap" },
    { text: "Loading 3D environment...", icon: "Globe" },
    { text: "Connecting to Soul AI...", icon: "Bot" },
    { text: "Synchronizing with other users...", icon: "Users" },
    { text: "Preparing your experience...", icon: "Sparkles" }
  ];

  useEffect(() => {
    const stepInterval = setInterval(() => {
      setLoadingStep(prev => {
        if (prev < loadingSteps.length - 1) {
          return prev + 1;
        }
        return prev;
      });
    }, 600);

    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev < 100) {
          return prev + 2;
        }
        return prev;
      });
    }, 60);

    return () => {
      clearInterval(stepInterval);
      clearInterval(progressInterval);
    };
  }, []);

  return (
    <div className="min-h-screen bg-background flex items-center justify-center px-4">
      <div className="text-center max-w-md w-full space-y-8">
        {/* Logo */}
        <div className="flex items-center justify-center space-x-3 mb-8">
          <div className="w-16 h-16 bg-gradient-to-br from-primary to-primary-600 rounded-xl flex items-center justify-center neon-glow animate-pulse">
            <Icon name="Zap" size={32} color="white" />
          </div>
          <div>
            <h1 className="font-heading font-bold text-2xl text-text-primary">Soul Drive</h1>
            <p className="text-text-secondary text-sm">Loading Experience</p>
          </div>
        </div>

        {/* Loading Animation */}
        <div className="space-y-6">
          {/* Animated Icon */}
          <div className="flex justify-center">
            <div className="w-20 h-20 bg-gradient-to-br from-primary/20 to-accent/20 rounded-full flex items-center justify-center animate-spin">
              <Icon 
                name={loadingSteps[loadingStep]?.icon || "Loader"} 
                size={32} 
                className="text-primary animate-pulse" 
              />
            </div>
          </div>

          {/* Loading Text */}
          <div className="space-y-2">
            <h2 className="font-heading font-semibold text-xl text-text-primary">
              {loadingSteps[loadingStep]?.text || "Loading..."}
            </h2>
            <p className="text-text-secondary">
              Please wait while we prepare your immersive experience
            </p>
          </div>

          {/* Progress Bar */}
          <div className="space-y-2">
            <div className="w-full bg-surface rounded-full h-2">
              <div 
                className="h-2 bg-gradient-to-r from-primary to-primary-400 rounded-full transition-all duration-300 neon-glow"
                style={{ width: `${progress}%` }}
              />
            </div>
            <div className="flex justify-between text-sm text-text-tertiary">
              <span>Initializing...</span>
              <span>{progress}%</span>
            </div>
          </div>

          {/* Loading Steps */}
          <div className="space-y-2">
            {loadingSteps.map((step, index) => (
              <div 
                key={index}
                className={`flex items-center space-x-3 p-2 rounded-lg transition-smooth ${
                  index <= loadingStep 
                    ? 'text-text-primary bg-white/5' :'text-text-tertiary'
                }`}
              >
                <div className={`w-6 h-6 rounded-full flex items-center justify-center ${
                  index < loadingStep 
                    ? 'bg-success text-white' 
                    : index === loadingStep 
                      ? 'bg-primary text-white animate-pulse' :'bg-surface'
                }`}>
                  {index < loadingStep ? (
                    <Icon name="Check" size={12} />
                  ) : index === loadingStep ? (
                    <Icon name="Loader" size={12} className="animate-spin" />
                  ) : (
                    <Icon name="Circle" size={12} />
                  )}
                </div>
                <span className="text-sm">{step.text}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Floating Particles */}
        <div className="absolute inset-0 pointer-events-none">
          {[...Array(15)].map((_, i) => (
            <div
              key={i}
              className="absolute w-1 h-1 bg-primary rounded-full animate-pulse"
              style={{
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                animationDelay: `${Math.random() * 3}s`,
                animationDuration: `${2 + Math.random() * 4}s`
              }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default LoadingAnimation;