// Firebase configuration and initialization for Soul Drive
import { initializeApp } from "firebase/app";
import { getAnalytics } from "firebase/analytics";
import { getFirestore, doc, setDoc, getDoc, collection, addDoc, query, orderBy, limit, getDocs, onSnapshot, serverTimestamp } from "firebase/firestore";
import { getAuth, signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut, onAuthStateChanged, updateProfile } from "firebase/auth";

// Firebase configuration provided by user
const firebaseConfig = {
  apiKey: "AIzaSyCLYPojbgXwAhROeZfPc2GHxZ9mMeC6lN0",
  authDomain: "soul-drive.firebaseapp.com",
  projectId: "soul-drive",
  storageBucket: "soul-drive.firebasestorage.app",
  messagingSenderId: "479835248263",
  appId: "1:479835248263:web:1de23fbd1dafdca6280a22",
  measurementId: "G-LT496GZM4Y"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const analytics = getAnalytics(app);
const db = getFirestore(app);
const auth = getAuth(app);

export { app, analytics, db, auth };

// Firebase service functions to replace localStorage
class FirebaseService {
  constructor() {
    this.sessionId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  // World state operations
  async saveWorldState(worldState) {
    try {
      const worldStateData = {
        ...worldState,
        sessionId: this.sessionId,
        timestamp: Date.now(),
        lastUpdated: new Date().toISOString()
      };

      await setDoc(doc(db, "worldStates", "current"), worldStateData);
      console.log("World state saved to Firebase");
      return true;
    } catch (error) {
      console.error("Error saving world state to Firebase:", error);
      // Fallback to localStorage
      localStorage.setItem('soulDrive_worldState', JSON.stringify(worldState));
      return false;
    }
  }

  async loadWorldState() {
    try {
      const docRef = doc(db, "worldStates", "current");
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        const data = docSnap.data();
        console.log("World state loaded from Firebase");
        return data;
      } else {
        console.log("No world state found in Firebase");
        return null;
      }
    } catch (error) {
      console.error("Error loading world state from Firebase:", error);
      // Fallback to localStorage
      const saved = localStorage.getItem('soulDrive_worldState');
      return saved ? JSON.parse(saved) : null;
    }
  }

  // Character state operations
  async saveCharacterState(characterState) {
    try {
      const characterData = {
        ...characterState,
        sessionId: this.sessionId,
        timestamp: Date.now(),
        lastUpdated: new Date().toISOString()
      };

      await setDoc(doc(db, "characterStates", "current"), characterData);
      console.log("Character state saved to Firebase");
      return true;
    } catch (error) {
      console.error("Error saving character state to Firebase:", error);
      // Fallback to localStorage
      localStorage.setItem('soulDrive_characterState', JSON.stringify(characterState));
      return false;
    }
  }

  async loadCharacterState() {
    try {
      const docRef = doc(db, "characterStates", "current");
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        const data = docSnap.data();
        console.log("Character state loaded from Firebase");
        return data;
      } else {
        console.log("No character state found in Firebase");
        return null;
      }
    } catch (error) {
      console.error("Error loading character state from Firebase:", error);
      // Fallback to localStorage
      const saved = localStorage.getItem('soulDrive_characterState');
      return saved ? JSON.parse(saved) : null;
    }
  }

  // Command history operations
  async saveCommandToHistory(command, result) {
    try {
      const commandData = {
        command,
        result,
        sessionId: this.sessionId,
        timestamp: Date.now(),
        createdAt: new Date().toISOString()
      };

      await addDoc(collection(db, "commandHistory"), commandData);
      console.log("Command saved to Firebase history");
      return true;
    } catch (error) {
      console.error("Error saving command to Firebase:", error);
      // Fallback to localStorage
      const history = this.getCommandHistoryLocal();
      history.unshift({ command, result, timestamp: Date.now() });
      if (history.length > 100) history.pop();
      localStorage.setItem('soulDrive_commandHistory', JSON.stringify(history));
      return false;
    }
  }

  async getCommandHistory(limitCount = 50) {
    try {
      const q = query(
        collection(db, "commandHistory"),
        orderBy("timestamp", "desc"),
        limit(limitCount)
      );

      const querySnapshot = await getDocs(q);
      const commands = [];
      querySnapshot.forEach((doc) => {
        commands.push({ id: doc.id, ...doc.data() });
      });

      console.log(`Loaded ${commands.length} commands from Firebase history`);
      return commands;
    } catch (error) {
      console.error("Error loading command history from Firebase:", error);
      // Fallback to localStorage
      return this.getCommandHistoryLocal();
    }
  }

  // Command queue operations (new feature)
  async saveCommandQueue(commandQueue) {
    try {
      const queueData = {
        commands: commandQueue,
        sessionId: this.sessionId,
        timestamp: Date.now(),
        lastUpdated: new Date().toISOString()
      };

      await setDoc(doc(db, "commandQueues", "current"), queueData);
      console.log("Command queue saved to Firebase");
      return true;
    } catch (error) {
      console.error("Error saving command queue to Firebase:", error);
      // Fallback to localStorage
      localStorage.setItem('soulDrive_commandQueue', JSON.stringify(commandQueue));
      return false;
    }
  }

  async loadCommandQueue() {
    try {
      const docRef = doc(db, "commandQueues", "current");
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        const data = docSnap.data();
        console.log("Command queue loaded from Firebase");
        return data.commands || [];
      } else {
        console.log("No command queue found in Firebase");
        return [];
      }
    } catch (error) {
      console.error("Error loading command queue from Firebase:", error);
      // Fallback to localStorage
      const saved = localStorage.getItem('soulDrive_commandQueue');
      return saved ? JSON.parse(saved) : [];
    }
  }

  // Custom objects operations (for 3D objects created in the world)
  async saveCustomObject(objectData) {
    try {
      const customObjectData = {
        ...objectData,
        sessionId: this.sessionId,
        timestamp: Date.now(),
        createdAt: new Date().toISOString()
      };

      const docRef = await addDoc(collection(db, "customObjects"), customObjectData);
      console.log("Custom object saved to Firebase with ID:", docRef.id);
      return docRef.id;
    } catch (error) {
      console.error("Error saving custom object to Firebase:", error);
      // Fallback to localStorage
      const objects = this.getCustomObjectsLocal();
      const id = `local_${Date.now()}`;
      objects.push({ ...objectData, id });
      localStorage.setItem('soulDrive_customObjects', JSON.stringify(objects));
      return id;
    }
  }

  async getCustomObjects() {
    try {
      const q = query(collection(db, "customObjects"), orderBy("timestamp", "desc"));
      const querySnapshot = await getDocs(q);
      const objects = [];
      querySnapshot.forEach((doc) => {
        objects.push({ id: doc.id, ...doc.data() });
      });

      console.log(`Loaded ${objects.length} custom objects from Firebase`);
      return objects;
    } catch (error) {
      console.error("Error loading custom objects from Firebase:", error);
      // Fallback to localStorage
      return this.getCustomObjectsLocal();
    }
  }

  // Local storage fallback methods
  getCommandHistoryLocal() {
    const saved = localStorage.getItem('soulDrive_commandHistory');
    return saved ? JSON.parse(saved) : [];
  }

  getCustomObjectsLocal() {
    const saved = localStorage.getItem('soulDrive_customObjects');
    return saved ? JSON.parse(saved) : [];
  }

  // Session and cleanup operations
  getSessionId() {
    return this.sessionId;
  }

  async cleanupOldData(daysOld = 7) {
    try {
      const cutoffTime = Date.now() - (daysOld * 24 * 60 * 60 * 1000);

      // This would require more complex Firebase queries with where clauses
      // For now, we'll just log that cleanup is available
      console.log(`Cleanup would remove data older than ${daysOld} days (timestamp < ${cutoffTime})`);

      return true;
    } catch (error) {
      console.error("Error during Firebase cleanup:", error);
      return false;
    }
  }

  // Auth Operations
  async signUp(email, password, displayName) {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      await updateProfile(userCredential.user, { displayName });
      // Create User Doc
      await setDoc(doc(db, "users", userCredential.user.uid), {
        uid: userCredential.user.uid,
        email,
        displayName,
        tier: 'free', // 'pro' for paid
        createdAt: serverTimestamp()
      });
      return userCredential.user;
    } catch (e) {
      throw e;
    }
  }

  async signIn(email, password) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      return userCredential.user;
    } catch (e) {
      throw e;
    }
  }

  async logOut() {
    return signOut(auth);
  }

  // Real-time Chat Operations
  sendMessage(text, user) {
    if (!user) return;
    addDoc(collection(db, "community_chat"), {
      text,
      uid: user.uid,
      displayName: user.displayName || "Anonymous",
      goldName: user.goldName || false, // Check for Visual Reward
      timestamp: serverTimestamp()
    });
  }

  subscribeToChat(callback) {
    const q = query(collection(db, "community_chat"), orderBy("timestamp", "asc"), limit(50));
    return onSnapshot(q, (snapshot) => {
      const messages = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      callback(messages);
    });
  }
}

// Create and export singleton instance
const firebaseService = new FirebaseService();
export default firebaseService;

// Export individual functions for backward compatibility
export const saveWorldState = (worldState) => firebaseService.saveWorldState(worldState);
export const loadWorldState = () => firebaseService.loadWorldState();
export const saveCharacterState = (characterState) => firebaseService.saveCharacterState(characterState);
export const loadCharacterState = () => firebaseService.loadCharacterState();
export const saveCommandToHistory = (command, result) => firebaseService.saveCommandToHistory(command, result);
export const getCommandHistory = (limit) => firebaseService.getCommandHistory(limit);
export const saveCommandQueue = (commandQueue) => firebaseService.saveCommandQueue(commandQueue);
export const loadCommandQueue = () => firebaseService.loadCommandQueue();
export const saveCustomObject = (objectData) => firebaseService.saveCustomObject(objectData);
export const getCustomObjects = () => firebaseService.getCustomObjects();
export const firebaseAuth = firebaseService; // Export service for direct auth usage