import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';

import PaymentCard from './components/PaymentCard';
import UpgradeTiers from './components/UpgradeTiers';
import SecurityBadges from './components/SecurityBadges';
import CountdownTimer from './components/CountdownTimer';
import SuccessAnimation from './components/SuccessAnimation';

const PaymentActionUpgrade = () => {
  const [currentActions, setCurrentActions] = useState(0);
  const [maxActions] = useState(100);
  const [selectedTier, setSelectedTier] = useState('basic');
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [paymentError, setPaymentError] = useState('');
  const [timeUntilReset, setTimeUntilReset] = useState(24 * 60 * 60); // 24 hours in seconds
  const [userCurrency, setUserCurrency] = useState('USD');

  const upgradeTiers = [
    {
      id: 'basic',
      name: '20 Actions',
      price: { USD: 1.00, EUR: 0.95, GBP: 0.85, JPY: 150 },
      actions: 20,
      description: 'Perfect for extended sessions',
      popular: false,
      estimatedTime: '2-3 hours of gameplay'
    },
    {
      id: 'standard',
      name: '50 Actions',
      price: { USD: 2.49, EUR: 2.35, GBP: 2.10, JPY: 370 },
      actions: 50,
      description: 'Great value for regular users',
      popular: true,
      estimatedTime: '5-6 hours of gameplay',
      savings: '15% off'
    },
    {
      id: 'premium',
      name: '100 Actions',
      price: { USD: 4.99, EUR: 4.70, GBP: 4.20, JPY: 740 },
      actions: 100,
      description: 'Maximum value for power users',
      popular: false,
      estimatedTime: '10+ hours of gameplay',
      savings: '25% off'
    }
  ];

  const currencySymbols = {
    USD: '$',
    EUR: '€',
    GBP: '£',
    JPY: '¥'
  };

  useEffect(() => {
    // Simulate currency detection based on user location
    const detectCurrency = () => {
      const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      if (timezone.includes('Europe')) {
        setUserCurrency('EUR');
      } else if (timezone.includes('London')) {
        setUserCurrency('GBP');
      } else if (timezone.includes('Tokyo') || timezone.includes('Asia')) {
        setUserCurrency('JPY');
      } else {
        setUserCurrency('USD');
      }
    };

    detectCurrency();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeUntilReset(prev => {
        if (prev <= 0) {
          clearInterval(timer);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const formatPrice = (price) => {
    const symbol = currencySymbols[userCurrency];
    const amount = price[userCurrency];

    if (userCurrency === 'JPY') {
      return `${symbol}${Math.round(amount)}`;
    }
    return `${symbol}${amount.toFixed(2)}`;
  };

  const handleStripePayment = async (tier) => {
    setIsProcessing(true);
    setPaymentError('');

    try {
      // Real Stripe Integration (Redirect to Checkout)
      // In a real app, you'd call your backend to create a Checkout Session here.
      // We will simulate the redirection or use a Payment Link if available.

      const STRIPE_LINKS = {
        'basic': 'https://buy.stripe.com/test_basic',
        'standard': 'https://buy.stripe.com/test_standard',
        'premium': 'https://buy.stripe.com/test_premium'
      };

      const link = STRIPE_LINKS[tier.id];
      if (!link) throw new Error("Payment link not configured for this tier.");

      // For now, we simulate success for the demo since we don't have a real link
      // But we show the explicit "Stripe" branding

      await new Promise(resolve => setTimeout(resolve, 1500)); // Network delay

      // Simulating a completed webhook return
      setCurrentActions(prev => prev + tier.actions);
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);

    } catch (error) {
      setPaymentError("Stripe Connection Failed: " + error.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const selectedTierData = upgradeTiers.find(tier => tier.id === selectedTier);

  return (
    <div className="min-h-screen bg-background relative overflow-hidden">
      {/* Background 3D World Context */}
      <div className="absolute inset-0 opacity-20">
        <div className="w-full h-full bg-gradient-to-br from-primary/10 via-background to-secondary/20" />
        <div className="absolute inset-0 bg-[url('data:image/svg+xml,%3Csvg%20width%3D%2260%22%20height%3D%2260%22%20viewBox%3D%220%200%2060%2060%22%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%3E%3Cg%20fill%3D%22none%22%20fill-rule%3D%22evenodd%22%3E%3Cg%20fill%3D%22%2300D4FF%22%20fill-opacity%3D%220.05%22%3E%3Ccircle%20cx%3D%2230%22%20cy%3D%2230%22%20r%3D%222%22/%3E%3C/g%3E%3C/g%3E%3C/svg%3E')] animate-pulse" />
      </div>

      {/* Success Animation Overlay */}
      {showSuccess && <SuccessAnimation />}

      {/* Main Content */}
      <div className="relative z-10 min-h-screen flex items-center justify-center p-4">
        <div className="w-full max-w-4xl">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-gradient-to-br from-primary to-primary-600 rounded-full flex items-center justify-center mx-auto mb-4 neon-glow">
              <Icon name="Zap" size={32} color="white" />
            </div>
            <h1 className="text-3xl md:text-4xl font-heading font-bold text-text-primary mb-2">
              Upgrade Your Actions
            </h1>
            <p className="text-text-secondary max-w-2xl mx-auto">
              You've used all your free actions! Choose an upgrade to continue shaping the Soul's journey in the 3D world.
            </p>
          </div>

          {/* Current Status */}
          <div className="glass-morphism rounded-xl p-6 mb-8 text-center">
            <div className="flex items-center justify-center space-x-4 mb-4">
              <div className="flex items-center space-x-2">
                <Icon name="Zap" size={20} className="text-error" />
                <span className="font-data text-lg font-medium text-text-primary">
                  {currentActions}/{maxActions} Actions
                </span>
              </div>
              <div className="w-32 bg-surface rounded-full h-2">
                <div
                  className="h-2 rounded-full bg-error transition-all duration-300"
                  style={{ width: `${(currentActions / maxActions) * 100}%` }}
                />
              </div>
            </div>
            <p className="text-text-secondary text-sm">
              {currentActions === 0 ? 'No actions remaining' : `${currentActions} actions left`}
            </p>
          </div>

          <div className="grid lg:grid-cols-2 gap-8">
            {/* Payment Options */}
            <div className="space-y-6">
              <h2 className="text-xl font-heading font-semibold text-text-primary">
                Choose Your Upgrade
              </h2>

              <UpgradeTiers
                tiers={upgradeTiers}
                selectedTier={selectedTier}
                onTierSelect={setSelectedTier}
                formatPrice={formatPrice}
              />

              <PaymentCard
                tier={selectedTierData}
                formatPrice={formatPrice}
                isProcessing={isProcessing}
                onPayment={handlePayPalPayment}
                error={paymentError}
              />

              <SecurityBadges />
            </div>

            {/* Alternative Options */}
            <div className="space-y-6">
              <h2 className="text-xl font-heading font-semibold text-text-primary">
                Alternative Options
              </h2>

              {/* Free Reset Option */}
              <div className="glass-morphism rounded-xl p-6">
                <div className="flex items-start space-x-4">
                  <div className="w-12 h-12 bg-warning/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <Icon name="Clock" size={24} className="text-warning" />
                  </div>
                  <div className="flex-1">
                    <h3 className="font-heading font-semibold text-text-primary mb-2">
                      Wait for Free Reset
                    </h3>
                    <p className="text-text-secondary text-sm mb-4">
                      Get 5 free actions when the timer resets. Perfect if you're not in a hurry!
                    </p>
                    <CountdownTimer timeRemaining={timeUntilReset} />
                  </div>
                </div>
              </div>

              {/* Usage Tips */}
              <div className="glass-morphism rounded-xl p-6">
                <h3 className="font-heading font-semibold text-text-primary mb-4 flex items-center">
                  <Icon name="Lightbulb" size={20} className="text-primary mr-2" />
                  Maximize Your Actions
                </h3>
                <ul className="space-y-3 text-sm text-text-secondary">
                  <li className="flex items-start space-x-2">
                    <Icon name="ArrowRight" size={16} className="text-primary mt-0.5 flex-shrink-0" />
                    <span>Use complex commands to achieve multiple goals at once</span>
                  </li>
                  <li className="flex items-start space-x-2">
                    <Icon name="ArrowRight" size={16} className="text-primary mt-0.5 flex-shrink-0" />
                    <span>Plan your actions strategically for maximum impact</span>
                  </li>
                  <li className="flex items-start space-x-2">
                    <Icon name="ArrowRight" size={16} className="text-primary mt-0.5 flex-shrink-0" />
                    <span>Watch other users' actions to learn efficient techniques</span>
                  </li>
                  <li className="flex items-start space-x-2">
                    <Icon name="ArrowRight" size={16} className="text-primary mt-0.5 flex-shrink-0" />
                    <span>Save actions by using the environment creatively</span>
                  </li>
                </ul>
              </div>

              {/* Navigation Back */}
              <div className="text-center">
                <Link
                  to="/main-3d-world-interface"
                  className="inline-flex items-center space-x-2 text-text-secondary hover:text-text-primary transition-smooth"
                >
                  <Icon name="ArrowLeft" size={16} />
                  <span>Return to Soul Drive</span>
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PaymentActionUpgrade;