import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const AudioControls = ({
  isEnabled,
  ambientVolume,
  musicVolume,
  onToggle,
  onVolumeChange
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [currentTrack, setCurrentTrack] = useState('Urban Pulse');
  const [isPlaying, setIsPlaying] = useState(true);

  const audioTracks = [
    { name: 'Urban Pulse', genre: 'Lo-fi', duration: '3:42' },
    { name: 'Neon Dreams', genre: 'Synthwave', duration: '4:15' },
    { name: 'City Rain', genre: 'Ambient', duration: '5:23' },
    { name: 'Digital Horizon', genre: 'Glitch-hop', duration: '3:58' }
  ];

  const ambientSounds = [
    { name: 'Traffic', icon: 'Car', active: true },
    { name: 'Rain', icon: 'CloudRain', active: false },
    { name: 'Wind', icon: 'Wind', active: true },
    { name: 'City Hum', icon: 'Radio', active: true }
  ];

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
  };

  const handleTrackChange = (trackName) => {
    setCurrentTrack(trackName);
    setIsPlaying(true);
  };

  const handleVolumeChange = (type, value) => {
    onVolumeChange(type, value / 100);
  };

  return (
    <div className="relative">
      {/* Main Audio Button */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className={`glass-morphism rounded-lg p-3 flex items-center space-x-2 transition-smooth ${isEnabled ? 'neon-glow' : 'opacity-50'
          }`}
        title="Audio Controls"
      >
        <Icon
          name={isEnabled ? (isPlaying ? 'Volume2' : 'VolumeX') : 'VolumeX'}
          size={20}
          className={isEnabled ? 'text-primary' : 'text-text-tertiary'}
        />
        <span className="hidden sm:block text-sm font-medium text-text-primary">
          Audio
        </span>
      </button>

      {/* Expanded Audio Panel */}
      {isExpanded && (
        <div className="absolute bottom-full left-0 mb-2 w-80 glass-morphism rounded-lg border border-white/20 animate-slide-up z-1200">
          {/* Header */}
          <div className="p-4 border-b border-white/10">
            <div className="flex items-center justify-between">
              <h3 className="font-heading font-semibold text-text-primary">Audio Controls</h3>
              <button
                onClick={onToggle}
                className={`p-2 rounded-lg transition-smooth ${isEnabled
                    ? 'bg-primary/20 text-primary' : 'bg-surface/50 text-text-tertiary hover:text-text-primary'
                  }`}
              >
                <Icon name={isEnabled ? 'Volume2' : 'VolumeX'} size={16} />
              </button>
            </div>
          </div>

          {isEnabled && (
            <>
              {/* Music Player */}
              {/* Global Volume Controls */}
              <div className="p-4 border-b border-white/10">
                <div className="flex items-center space-x-2 mb-4">
                  <Icon name="Volume2" size={16} className="text-primary" />
                  <span className="text-sm font-medium text-text-primary">Master Volume</span>
                </div>

                {/* Ambient/Synth Volume */}
                <div className="mb-4">
                  <div className="flex justify-between text-xs text-text-secondary mb-1">
                    <span>Ambience / Synth</span>
                    <span>{Math.round(ambientVolume * 100)}%</span>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={ambientVolume * 100}
                    onChange={(e) => handleVolumeChange('ambient', e.target.value)}
                    className="w-full h-1 bg-surface rounded-lg appearance-none cursor-pointer"
                  />
                </div>

                {/* Music Volume (Placeholder for future radio) */}
                <div>
                  <div className="flex justify-between text-xs text-text-secondary mb-1">
                    <span>Music (Radio Offline)</span>
                    <span>{Math.round(musicVolume * 100)}%</span>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={musicVolume * 100}
                    onChange={(e) => handleVolumeChange('music', e.target.value)}
                    className="w-full h-1 bg-surface rounded-lg appearance-none cursor-pointer opacity-50"
                    disabled
                  />
                </div>
              </div>

              {/* Ambient Sounds */}
              {/* Ambient Sounds List Removed (Visual Only) */}
            </>
          )}

          {!isEnabled && (
            <div className="p-4 text-center">
              <Icon name="VolumeX" size={32} className="text-text-tertiary mx-auto mb-2" />
              <p className="text-sm text-text-secondary">Audio is disabled</p>
              <button
                onClick={onToggle}
                className="mt-2 text-xs text-primary hover:text-primary-400 underline"
              >
                Enable Audio
              </button>
            </div>
          )}
        </div>
      )}

      {/* Backdrop */}
      {isExpanded && (
        <div
          className="fixed inset-0 z-1100"
          onClick={() => setIsExpanded(false)}
        />
      )}
    </div>
  );
};

export default AudioControls;