// Helper to get a random product, optionally by tag
export const getRandomProduct = (tag = null) => {
    let pool = affiliateProducts;
    if (tag) {
        pool = affiliateProducts.filter(p => p.tags.includes(tag));
    }
    if (pool.length === 0) pool = affiliateProducts;

    return pool[Math.floor(Math.random() * pool.length)];
};
