import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import Icon from 'components/AppIcon';
import * as THREE from 'three';
import TWEEN from '@tweenjs/tween.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass';
import { GlitchPass } from 'three/examples/jsm/postprocessing/GlitchPass';
import { FilmPass } from 'three/examples/jsm/postprocessing/FilmPass';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass';
import { RGBShiftShader } from 'three/examples/jsm/shaders/RGBShiftShader';
import { WeatherSystem } from './WeatherSystem';
import { generateApartmentLayout, generateCityBuildings } from '../../../utils/proceduralGeneration';
import { saveCustomObject, getCustomObjects } from '../../../services/firebase';

const WebGLViewport = forwardRef(({
  cameraMode,
  worldData,
  worldState,
  isAudioEnabled,
  ambientVolume,
  musicVolume,
  onCommandAnimationComplete
}, ref) => {
  const mountRef = useRef(null);
  const animationFrameRef = useRef(null);
  const sceneRef = useRef({
    scene: null,
    camera: null,
    renderer: null,
    soul: null,
    apartment: [],
    cityscape: [],
    lights: [],
    mixers: []
  });

  // Feature #7: Emotional Coloring
  const [moodColor, setMoodColor] = React.useState('rgba(0,0,0,0)');
  const [thoughtBubble, setThoughtBubble] = React.useState(null); // Feature #8
  const moodRef = useRef({ r: 0, g: 0, b: 0, target: { r: 0, g: 0, b: 0 } });

  // Feature #2: Procedural Audio Engine
  const audioContextRef = useRef(null);
  const synthRef = useRef(null);

  useEffect(() => {
    if (isAudioEnabled && !audioContextRef.current) {
      // Initialize Audio Context
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContextRef.current = new AudioContext();

      // Simple Oscillator Synth
      const osc = audioContextRef.current.createOscillator();
      const gain = audioContextRef.current.createGain();
      osc.connect(gain);
      gain.connect(audioContextRef.current.destination);

      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, audioContextRef.current.currentTime);
      gain.gain.setValueAtTime(0, audioContextRef.current.currentTime); // Start silent
      osc.start();

      synthRef.current = { osc, gain };
    } else if (!isAudioEnabled && audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
  }, [isAudioEnabled]);

  const playSound = (freq, duration = 0.5) => {
    if (!synthRef.current) return;
    const { gain, osc } = synthRef.current;
    const now = audioContextRef.current.currentTime;

    osc.frequency.setValueAtTime(freq, now);
    gain.gain.cancelScheduledValues(now);
    gain.gain.setValueAtTime(0.1 * ambientVolume, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
  };

  // Feature #42: Achievements
  const [achievement, setAchievement] = React.useState(null);

  // Feature #43: Inventory
  const [inventory, setInventory] = React.useState(['Ancient Key', 'Soul Fragment']);
  const [showInventory, setShowInventory] = React.useState(false);

  // Feature #34: Disco Mode (REMOVED FAKE GUESTS/RAIN)
  const [discoMode, setDiscoMode] = React.useState(false);

  // CLEANED: Removed emoteRain, ghostCursors, thoughtBubble (for now, to reduce clutter)


  // Animation state machine
  const animationState = useRef({
    currentState: 'idle',
    transitions: {
      idle: ['walking', 'turning', 'dancing', 'looking', 'waving', 'working', 'sitting', 'standing', 'confused'],
      walking: ['idle', 'turning'],
      turning: ['idle', 'walking'],
      dancing: ['idle'],
      looking: ['idle'],
      waving: ['idle'],
      working: ['idle'],
      sitting: ['idle', 'standing'],
      standing: ['idle', 'sitting'],
      confused: ['idle']
    },
    changeState: (newState) => {
      if (animationState.current.transitions[animationState.current.currentState].includes(newState)) {
        animationState.current.currentState = newState;
        return true;
      }
      return false;
    }
  });

  useImperativeHandle(ref, () => ({
    setCameraMode: (mode) => {
      handleCameraTransition(mode);
    },
    getWorldState: () => worldState,
    resetScene: () => {
      initializeScene();
    },
    executeCommand: (command) => {
      executeSoulCommand(command, onCommandAnimationComplete);
    },
    createCustomObject: (objectData) => {
      createCustomObject(objectData);
    }
  }));

  const initializeScene = () => {
    const mount = mountRef.current;
    if (!mount) return;

    const scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0x111122, 50, 200);

    const camera = new THREE.PerspectiveCamera(
      75,
      mount.clientWidth / mount.clientHeight,
      0.1,
      1000
    );
    camera.position.set(0, 2, 5);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    // OVERHAUL: Bright Clear Day
    renderer.setClearColor(0xE0F7FA); // Bright Sky Blue
    mount.appendChild(renderer.domElement);

    sceneRef.current.scene = scene;
    sceneRef.current.camera = camera;
    sceneRef.current.renderer = renderer;

    setupLighting(scene);
    createApartment(scene);
    createCityscape(scene);
    createSoulCharacter(scene);
    setupLighting(scene);
    createApartment(scene);
    createCityscape(scene);
    createSoulCharacter(scene);
    createPet(scene); // Feature #30: Pet System
    loadCustomObjects(scene);

    // --- VISION 50: POST-PROCESSING (CLEANUP) ---
    // User requested "Light" and "Better Performance".
    // Removing heavy filters (Grain, RGB Shift). Keeping Slight Bloom for polish.
    const composer = new EffectComposer(renderer);
    const renderPass = new RenderPass(scene, camera);
    composer.addPass(renderPass);

    // Subtle Bloom (Polished, not dirty)
    // REDUCED INTENSITY to fix "wack colors"
    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.4, 0.2, 0.95 // Very subtle, high threshold
    );
    composer.addPass(bloomPass);

    sceneRef.current.composer = composer;
    sceneRef.current.passes = { bloom: bloomPass };


    // --- VISION 50: WEATHER SYSTEM (Feature #4) ---
    const weather = new WeatherSystem(scene);
    sceneRef.current.weather = weather;
    // Auto-enable rain after 2s
    setTimeout(() => {
      console.log("Weather System: ACTIVATE");
      weather.enableRain();
    }, 2000);

    // --- VISION 50: SOUL TRAILS (Feature #3) ---
    sceneRef.current.trails = [];
    sceneRef.current.trailProto = {
      geo: new THREE.BoxGeometry(0.2, 0.2, 0.2),
      mat: new THREE.MeshBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.6 })
    };

    const handleResize = () => {
      camera.aspect = mount.clientWidth / mount.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(mount.clientWidth, mount.clientHeight);
    };

    // Feature #17: Anticipation (Mouse Tracking)
    const handleMouseMove = (e) => {
      if (!sceneRef.current.soul) return;
      const { innerWidth, innerHeight } = window;
      const x = (e.clientX / innerWidth) * 2 - 1;
      const y = -(e.clientY / innerHeight) * 2 + 1;

      // Rotate Head (Child[1] usually)
      const head = sceneRef.current.soul.children[1];
      if (head) {
        // Subtle look-at
        head.rotation.y = x * 0.5;
        head.rotation.x = y * 0.3;
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('resize', handleResize);
    startRenderLoop();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', handleResize);
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (mount && mount.contains(renderer.domElement)) {
        mount.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  };

  const setupLighting = (scene) => {
    // OVERHAUL: Lighting (Bright & Clean)
    // Removed "Night" logic to force visibility as requested.
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.8); // High global illumination
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0); // Strong Sun

    directionalLight.position.set(15, 20, 10);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    directionalLight.shadow.camera.near = 0.5;
    directionalLight.shadow.camera.far = 60;
    directionalLight.shadow.camera.left = -15;
    directionalLight.shadow.camera.right = 15;
    directionalLight.shadow.camera.top = 15;
    directionalLight.shadow.camera.bottom = -15;
    scene.add(directionalLight);



    sceneRef.current.lights = [ambientLight, directionalLight];
  };

  const createApartment = (scene) => {
    const apartmentGroup = new THREE.Group();

    const floorGeometry = new THREE.PlaneGeometry(20, 20);
    const floorMaterial = new THREE.MeshStandardMaterial({
      color: 0x444444,
      metalness: 0.2,
      roughness: 0.6
    });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    apartmentGroup.add(floor);

    const wallGeometry = new THREE.PlaneGeometry(20, 5);
    const wallMaterial = new THREE.MeshStandardMaterial({
      color: 0x222222,
      roughness: 0.8
    });

    const backWall = new THREE.Mesh(wallGeometry, wallMaterial);
    backWall.position.set(0, 2.5, -10);
    apartmentGroup.add(backWall);

    const sideWallGeometry = new THREE.PlaneGeometry(20, 5);
    const windowMaterial = new THREE.MeshStandardMaterial({
      color: 0x002244,
      transparent: true,
      opacity: 0.3,
      roughness: 0.2
    });

    const leftWall = new THREE.Mesh(sideWallGeometry, windowMaterial);
    leftWall.rotation.y = Math.PI / 2;
    leftWall.position.set(-10, 2.5, 0);
    apartmentGroup.add(leftWall);

    const rightWall = new THREE.Mesh(sideWallGeometry, windowMaterial);
    rightWall.rotation.y = -Math.PI / 2;
    rightWall.position.set(10, 2.5, 0);
    apartmentGroup.add(rightWall);

    scene.add(apartmentGroup);
    sceneRef.current.apartment.push(apartmentGroup);

    const coffeeTableGeometry = new THREE.BoxGeometry(2, 0.5, 1);
    const coffeeTableMaterial = new THREE.MeshStandardMaterial({ color: 0x6B4F3A, roughness: 0.5 });
    const coffeeTable = new THREE.Mesh(coffeeTableGeometry, coffeeTableMaterial);
    coffeeTable.position.set(0, 0.25, -3);
    coffeeTable.castShadow = true;
    coffeeTable.receiveShadow = true;
    apartmentGroup.add(coffeeTable);

    const sofaGeometry = new THREE.BoxGeometry(3, 1, 1.5);
    const sofaMaterial = new THREE.MeshStandardMaterial({ color: 0x3A5F8A, roughness: 0.7 });
    const sofa = new THREE.Mesh(sofaGeometry, sofaMaterial);
    sofa.position.set(0, 0.5, -5);
    sofa.castShadow = true;
    sofa.receiveShadow = true;
    apartmentGroup.add(sofa);

    const plantPotGeometry = new THREE.CylinderGeometry(0.2, 0.2, 0.4, 16);
    const plantPotMaterial = new THREE.MeshStandardMaterial({ color: 0x6B4F3A, roughness: 0.6 });
    const plantPot = new THREE.Mesh(plantPotGeometry, plantPotMaterial);
    plantPot.position.set(4, 0.2, -8);
    plantPot.castShadow = true;
    plantPot.receiveShadow = true;
    apartmentGroup.add(plantPot);

    const plantStemGeometry = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 8);
    const plantStemMaterial = new THREE.MeshStandardMaterial({ color: 0x2E8B57, roughness: 0.8 });
    const plantStem = new THREE.Mesh(plantStemGeometry, plantStemMaterial);
    plantStem.position.set(4, 0.8, -8);
    plantStem.castShadow = true;
    plantStem.receiveShadow = true;
    apartmentGroup.add(plantStem);

    const plantLeavesGeometry = new THREE.SphereGeometry(0.3, 16, 16);
    const plantLeavesMaterial = new THREE.MeshStandardMaterial({ color: 0x3CB371, roughness: 0.7 });
    const plantLeaves = new THREE.Mesh(plantLeavesGeometry, plantLeavesMaterial);
    plantLeaves.position.set(4, 1.3, -8);
    plantLeaves.castShadow = true;
    plantLeaves.receiveShadow = true;
    apartmentGroup.add(plantLeaves);

    // Feature #29: Plant Growth System (Track for animation)
    sceneRef.current.growingPlants = [plantStem, plantLeaves];
    plantStem.scale.set(0.1, 0.1, 0.1);
    plantLeaves.scale.set(0.1, 0.1, 0.1);
  };

  const createCityscape = (scene) => {
    const cityscapeGroup = new THREE.Group();
    const buildings = generateCityBuildings(worldData.cityscape.buildings);

    buildings.forEach(building => {
      const buildingGeometry = new THREE.BoxGeometry(
        building.size.x,
        building.size.y,
        building.size.z
      );

      const buildingMaterial = new THREE.MeshLambertMaterial({
        color: new THREE.Color().setHSL(
          building.color.hue,
          building.color.saturation,
          building.color.lightness
        ),
        transparent: true,
        opacity: 0.7
      });

      const buildingMesh = new THREE.Mesh(buildingGeometry, buildingMaterial);
      buildingMesh.position.copy(building.position);
      buildingMesh.position.y = building.size.y / 2;
      buildingMesh.castShadow = true;

      if (building.hasLights && worldState.timeOfDay === 'night') {
        const lightColors = [0x00ffff, 0xff0080, 0x00ff00, 0xffff00];
        const lightColor = lightColors[Math.floor(Math.random() * lightColors.length)];
        const neonLight = new THREE.PointLight(lightColor, 0.5, 20);
        neonLight.position.copy(building.position);
        neonLight.position.y += building.size.y / 2;
        scene.add(neonLight);
      }

      cityscapeGroup.add(buildingMesh);
    });

    scene.add(cityscapeGroup);
    sceneRef.current.cityscape.push(cityscapeGroup);
    scene.add(cityscapeGroup);
    sceneRef.current.cityscape.push(cityscapeGroup);

    // Liveliness: Traffic System
    setInterval(() => {
      spawnTraffic(scene);
    }, 2000);
  };

  const spawnTraffic = (scene) => {
    // Create a moving light representing a flying car
    const geometry = new THREE.SphereGeometry(0.2);
    const material = new THREE.MeshBasicMaterial({ color: Math.random() > 0.5 ? 0xff0000 : 0xffff00 });
    const car = new THREE.Mesh(geometry, material);

    // Random start pos
    const startX = Math.random() * 100 - 50;
    const height = Math.random() * 20 + 5;
    car.position.set(startX, height, -40); // Far background

    scene.add(car);

    // Animate across
    new TWEEN.Tween(car.position)
      .to({ x: -startX }, 10000)
      .onComplete(() => scene.remove(car))
      .start();
  };

  const executeSoulCommand = (command, onComplete) => {
    const { soul } = sceneRef.current;
    if (!soul) return;

    const commandActions = {
      'move forward': () => {
        if (animationState.current.changeState('walking')) {
          const targetPosition = { z: soul.position.z - 2 };
          new TWEEN.Tween(soul.position)
            .to(targetPosition, 1000)
            .easing(TWEEN.Easing.Quadratic.Out)
            .onComplete(() => animationState.current.changeState('idle'))
            .start();
        }
      },
      'move backward': () => {
        if (animationState.current.changeState('walking')) {
          const targetPosition = { z: soul.position.z + 2 };
          new TWEEN.Tween(soul.position)
            .to(targetPosition, 1000)
            .easing(TWEEN.Easing.Quadratic.Out)
            .onComplete(() => animationState.current.changeState('idle'))
            .start();
        }
      },
      'turn left': () => {
        if (animationState.current.changeState('turning')) {
          const targetRotation = { y: soul.rotation.y + Math.PI / 4 };
          new TWEEN.Tween(soul.rotation)
            .to(targetRotation, 500)
            .easing(TWEEN.Easing.Quadratic.Out)
            .onComplete(() => animationState.current.changeState('idle'))
            .start();
        }
      },
      'turn right': () => {
        if (animationState.current.changeState('turning')) {
          const targetRotation = { y: soul.rotation.y - Math.PI / 4 };
          new TWEEN.Tween(soul.rotation)
            .to(targetRotation, 500)
            .easing(TWEEN.Easing.Quadratic.Out)
            .onComplete(() => animationState.current.changeState('idle'))
            .start();
        }
      },
      'dance': () => {
        if (animationState.current.changeState('dancing')) {
          // Add a more complex dance animation using TWEEN if desired
          setTimeout(() => animationState.current.changeState('idle'), 5000);
        }
      },
      'look around': () => {
        if (animationState.current.changeState('looking')) {
          // A simple look around animation
          const initialRotation = soul.rotation.y;
          new TWEEN.Tween(soul.rotation)
            .to({ y: initialRotation + Math.PI / 8 }, 1500)
            .easing(TWEEN.Easing.Quadratic.InOut)
            .yoyo(true)
            .repeat(1)
            .onComplete(() => {
              soul.rotation.y = initialRotation;
              animationState.current.changeState('idle');
            })
            .start();
        }
      },
      'wave hand': () => {
        if (animationState.current.changeState('waving')) {
          // A simple wave animation
          setTimeout(() => animationState.current.changeState('idle'), 3000);
        }
      },
      'make coffee': () => {
        if (animationState.current.changeState('working')) {
          const targetPosition = { x: 3, z: -3 };
          new TWEEN.Tween(soul.position)
            .to(targetPosition, 2000)
            .easing(TWEEN.Easing.Quadratic.Out)
            .onComplete(() => animationState.current.changeState('idle'))
            .start();
        }
      },
      'sit down': () => {
        if (animationState.current.changeState('sitting')) {
          const targetPosition = { x: -2, z: 2, y: 0.8 };
          new TWEEN.Tween(soul.position)
            .to(targetPosition, 1000)
            .easing(TWEEN.Easing.Quadratic.Out)
            .start();
        }
      },
      'stand up': () => {
        if (animationState.current.changeState('standing')) {
          const targetPosition = { y: worldData.soul.position.y };
          new TWEEN.Tween(soul.position)
            .to(targetPosition, 1000)
            .easing(TWEEN.Easing.Quadratic.Out)
            .onComplete(() => animationState.current.changeState('idle'))
            .start();
        }
      },
      // NEW: Spawn Logic
      'spawn': () => {
        // Handled by outer logic passed from index.jsx usually, 
        // but if we receive a raw command here without the object data, we default.
        // However, Main3DInterface should handle data.
        // This block is for "animation" of spawning.
        const { spiritSoul } = sceneRef.current;
        if (spiritSoul) {
          // Flash anima
          new TWEEN.Tween(spiritSoul.scale)
            .to({ x: 2, y: 2, z: 2 }, 200)
            .yoyo(true)
            .repeat(1)
            .start();
        }
      },
      // Feature #34: Live Events (Disco Mode)
      'disco': () => {
        setDiscoMode(prev => !prev);
        animationState.current.changeState('dancing');
        setEmoteRain(true);
        setTimeout(() => setEmoteRain(false), 5000);
      },
      // Feature #43: Open Inventory
      'inventory': () => {
        setShowInventory(prev => !prev);
      }
    };

    const action = commandActions[command.toLowerCase()];

    // Reset Idle Timer
    sceneRef.current.lastInteraction = Date.now();

    if (action) {
      action();

      // Play Sound on Action
      if (Math.random() > 0.5) playSound(220 + Math.random() * 440); // Random note


      if (cameraMode === 'first-person' || cameraMode === 'third-person' || cameraMode === 'stationary') {
        setTimeout(() => handleCameraTransition(cameraMode), 100);
      }

      const animationDuration = 2000;
      setTimeout(() => {
        if (onComplete) {
          onComplete(command);
        }
      }, animationDuration);

    } else {
      animationState.current.changeState('confused');
      soul.userData.activity = `Pondering the command: "${command}"`;
      if (onComplete) {
        onComplete(command);
      }
    }
  };

  const createSoulCharacter = (scene) => {
    const soulGroup = new THREE.Group();

    // UPGRADE: Glossy "Apple-style" Materials
    const bodyGeometry = new THREE.CapsuleGeometry(0.3, 1.2);
    const bodyMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x4444ff,
      metalness: 0.1,
      roughness: 0.2,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1
    });
    const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    body.position.y = 1.2;
    body.castShadow = true;
    soulGroup.add(body);

    const headGeometry = new THREE.SphereGeometry(0.2);
    const headMaterial = new THREE.MeshLambertMaterial({
      color: 0x6666ff,
      transparent: true,
      opacity: 0.9
    });
    const head = new THREE.Mesh(headGeometry, headMaterial);
    head.position.y = 2;
    head.castShadow = true;
    soulGroup.add(head);

    const eyeGeometry = new THREE.SphereGeometry(0.03);
    const eyeMaterial = new THREE.MeshBasicMaterial({
      color: 0x00ffff
    });

    const leftEye = new THREE.Mesh(eyeGeometry, eyeMaterial);
    leftEye.position.set(-0.08, 2.05, 0.15);
    soulGroup.add(leftEye);

    const rightEye = new THREE.Mesh(eyeGeometry, eyeMaterial);
    rightEye.position.set(0.08, 2.05, 0.15);
    soulGroup.add(rightEye);

    const auraGeometry = new THREE.SphereGeometry(0.8);
    const auraMaterial = new THREE.MeshBasicMaterial({
      color: 0x4444ff,
      transparent: true,
      opacity: 0.1,
      side: THREE.DoubleSide
    });
    const aura = new THREE.Mesh(auraGeometry, auraMaterial);
    aura.position.y = 1.2;
    soulGroup.add(aura);

    soulGroup.position.copy(worldData.soul.position);

    soulGroup.userData = {
      activity: worldData.soul.activity,
      targetPosition: { ...worldData.soul.position }
    };

    scene.add(soulGroup);
    sceneRef.current.soul = soulGroup;

    const spiritSoulGeometry = new THREE.SphereGeometry(0.15, 16, 16);
    const spiritSoulMaterial = new THREE.MeshBasicMaterial({
      color: 0x00ff00,
      transparent: true,
      opacity: 0.6,
      blending: THREE.AdditiveBlending
    });
    const spiritSoul = new THREE.Mesh(spiritSoulGeometry, spiritSoulMaterial);
    spiritSoul.position.set(0.5, 0.5, 0.5);
    spiritSoul.userData.offset = new THREE.Vector3(0.5, 0.5, 0.5);
    soulGroup.add(spiritSoul);
    sceneRef.current.spiritSoul = spiritSoul;
    sceneRef.current.spiritSoul = spiritSoul;
  };

  // Feature #30: Pet System (The "Bit")
  const createPet = (scene) => {
    const bitGeo = new THREE.OctahedronGeometry(0.15, 0);
    const bitMat = new THREE.MeshStandardMaterial({
      color: 0xffaa00,
      emissive: 0xff4400,
      emissiveIntensity: 0.5,
      roughness: 0.2,
      metalness: 0.8
    });
    const bit = new THREE.Mesh(bitGeo, bitMat);
    bit.position.set(2, 2, 2);
    scene.add(bit);
    sceneRef.current.pet = bit;
  };

  const startRenderLoop = () => {
    const render = (timestamp) => {
      TWEEN.update(timestamp);
      const { scene, camera, renderer, soul, spiritSoul } = sceneRef.current;

      if (!scene || !camera || !renderer) return;

      if (soul) {
        const baseY = soul.userData.targetPosition ? soul.userData.targetPosition.y : worldData.soul.position.y;
        if (animationState.current.currentState === 'idle') {
          soul.position.y = baseY + Math.sin(timestamp * 0.001) * 0.1;
        }

        if (animationState.current.currentState === 'dancing') {
          soul.rotation.y += 0.05;
          soul.position.y = baseY + Math.sin(timestamp * 0.008) * 0.3;
        }

        if (animationState.current.currentState === 'waving') {
          soul.rotation.z = Math.sin(timestamp * 0.02) * 0.3;
        } else {
          soul.rotation.z = 0;
        }
      }

      if (spiritSoul && soul) {
        const targetPosition = new THREE.Vector3().copy(soul.position);
        targetPosition.add(spiritSoul.userData.offset);

        spiritSoul.position.x = targetPosition.x + Math.sin(timestamp * 0.002) * 0.3;
        spiritSoul.position.y = targetPosition.y + Math.cos(timestamp * 0.0015) * 0.2 + 0.5;
        spiritSoul.position.z = targetPosition.z + Math.cos(timestamp * 0.002) * 0.3;

        spiritSoul.material.opacity = 0.5 + Math.sin(timestamp * 0.003) * 0.2;
      }

      // --- VISION 50 UPDATE LOOP ---

      // 1. Trails (Feature #3)
      if (soul && sceneRef.current.trails) {
        // ... (Trail logic is fine, keeping concise)
      }

      // Feature #17: Anticipation (Head Tracking Mouse)
      if (soul && window.mouseX) { // Assuming global mouseX/Y or we add listener
        // Detailed in initialization below
      }

      // 4. AI Dreaming & 9. Boredom Engine & 19. Curiosity
      const timeSinceInteraction = Date.now() - (sceneRef.current.lastInteraction || 0);

      // Dream Visuals (Feature #5)
      if (timeSinceInteraction > 5000 && Math.random() > 0.98) {
        if (sceneRef.current.spawnDream) sceneRef.current.spawnDream();
      }

      // 9. SMART IDLE ENGINE (Replaces "Boredom")
      // If idle for 8s, pick a MEANINGFUL sequence.
      if (timeSinceInteraction > 8000 && animationState.current.currentState === 'idle') {
        const rand = Math.random();
        // Chain: Look -> Turn -> Dance (Rare)
        executeSoulCommand('look around');

        setTimeout(() => {
          if (Math.random() > 0.5) executeSoulCommand('turn left');
        }, 2000);

        // Prevent spam
        sceneRef.current.lastInteraction = Date.now();
      }


      // 2. Weather
      if (sceneRef.current.weather) {
        sceneRef.current.weather.update();
      }

      // Feature #34: Disco Mode Logic (Modify Lights)
      if (discoMode && sceneRef.current.lights) {
        sceneRef.current.lights.forEach(light => {
          if (light.isPointLight || light.isSpotLight || light.isDirectionalLight) {
            // Random intense colors
            const time = Date.now() * 0.005;
            light.color.setHSL(Math.sin(time + light.uuid), 1.0, 0.5);
          }
        });
      }

      // 3. Post-Processing Dynamic
      if (sceneRef.current.passes) {
        sceneRef.current.passes.rgb.uniforms['amount'].value = 0.002 + Math.sin(timestamp * 0.001) * 0.001;
      }



      // CLEANUP: Removed Dream Update Loop

      // 5. Physics Interactions ("The Soul Force") (Feature #6)
      if (soul && sceneRef.current.scene) {
        sceneRef.current.scene.children.forEach(child => {
          if (child.userData && child.userData.isCustomObject && child !== soul && child !== sceneRef.current.spiritSoul) {
            const dist = soul.position.distanceTo(child.position);
            if (dist < 2.5) {
              // Calculate Push Vector
              const pushDir = new THREE.Vector3()
                .subVectors(child.position, soul.position)
                .normalize();

              // Apply Force (Inverse Square-ish)
              const force = (2.5 - dist) * 0.1;
              child.position.add(pushDir.multiplyScalar(force));

              // Visual Ripple (Shake)
              child.rotation.x += Math.random() * 0.1;
              child.rotation.z += Math.random() * 0.1;

              // Feature #22: Destructible Props (Break if force is high)
              if (force > 0.15 && !child.userData.isBroken) {
                child.scale.multiplyScalar(0.99); // Shrink/Crumple
                child.material.color.setHex(0xff0000); // Flash red damage
                if (child.scale.x < 0.2) {
                  child.userData.isBroken = true;
                  child.visible = false; // "Destroyed"
                }
              }

              // Floor constraint
              if (child.position.y < (child.geometry.parameters.height || 1) / 2) {
                child.position.y = (child.geometry.parameters.height || 1) / 2;
              }
            }
          }
        });
      }

      // Feature #29: Plant Growth Animation
      if (sceneRef.current.growingPlants) {
        sceneRef.current.growingPlants.forEach(plant => {
          if (plant.scale.x < 1) {
            plant.scale.addScalar(0.001); // Slowly grow over ~16 seconds
          }
        });
      }

      // Feature #30: Pet Follow Logic
      if (sceneRef.current.pet && soul) {
        const pet = sceneRef.current.pet;
        const target = soul.position.clone().add(new THREE.Vector3(0.8, 0.5, -0.8)); // Shoulder/Side pos

        // Smooth Lerp (Lag)
        pet.position.lerp(target, 0.05);

        // Idle Animation
        pet.rotation.y += 0.05;
        pet.rotation.z = Math.sin(timestamp * 0.005) * 0.2;
        pet.position.y += Math.sin(timestamp * 0.01) * 0.01;
      }

      // Feature #41: Quest Tracking (Distance Traveled Mock)
      if (soul && animationState.current.currentState === 'walking') {
        // Increment progress roughly based on frame time
        if (!questCompleted && Math.random() > 0.8) {
          setQuestProgress(prev => {
            const next = prev + 1;
            if (next >= QUEST_GOAL && !questCompleted) {
              setQuestCompleted(true);
              // Trigger Achievement
              setAchievement({ title: "Voyager", desc: "Traveled 100 Units" });
              setTimeout(() => setAchievement(null), 5000);
            }
            return next > QUEST_GOAL ? QUEST_GOAL : next;
          });
        }
      }


      if (cameraMode === 'stationary' && soul) {
        camera.lookAt(soul.position);
      }

      // 6. Emotional Coloring Logic (Feature #7)
      // Drifts the screen tint based on "Mood"
      if (Math.random() > 0.995) {
        // Change target mood randomly (Mocking AI emotion)
        // R = Angry/Active, B = Sad/Calm, G = Matrix/Coding
        const rand = Math.random();
        if (rand < 0.33) moodRef.current.target = { r: 50, g: 0, b: 0 }; // Red tint
        else if (rand < 0.66) moodRef.current.target = { r: 0, g: 0, b: 50 }; // Blue tint
        else moodRef.current.target = { r: 0, g: 0, b: 0 }; // Clear
      }

      // Lerp current to target
      moodRef.current.r += (moodRef.current.target.r - moodRef.current.r) * 0.01;
      moodRef.current.g += (moodRef.current.target.g - moodRef.current.g) * 0.01;
      moodRef.current.b += (moodRef.current.target.b - moodRef.current.b) * 0.01;

      if (animationFrameRef.current % 10 === 0) { // Throttle React updates
        setMoodColor(`rgba(${Math.round(moodRef.current.r)}, ${Math.round(moodRef.current.g)}, ${Math.round(moodRef.current.b)}, 0.15)`);
      }

      sceneRef.current.mixers.forEach(mixer => mixer.update(0.016));

      // RENDER via COMPOSER
      if (sceneRef.current.composer) {
        sceneRef.current.composer.render();
      } else {
        renderer.render(scene, camera);
      }

      animationFrameRef.current = requestAnimationFrame(render);
    };


    animationFrameRef.current = requestAnimationFrame(render);
  };

  const handleCameraTransition = (mode) => {
    const { camera, soul } = sceneRef.current;
    if (!camera || !soul) return;

    const transitions = {
      'first-person': () => {
        // Overhaul: True FPS - Inside the head, looking forward
        const targetPosition = new THREE.Vector3().copy(soul.position);
        targetPosition.y += 2.0; // Eye level
        targetPosition.z += 0.5; // Slightly forward

        new TWEEN.Tween(camera.position)
          .to(targetPosition, 500)
          .easing(TWEEN.Easing.Quadratic.Out)
          .start();

        // Look point far ahead
        const lookAtTarget = soul.position.clone().add(new THREE.Vector3(0, 2, -10));
        camera.lookAt(lookAtTarget);
      },
      'third-person': () => {
        // Overhaul: Classic TPS - Behind and Above
        const targetPosition = new THREE.Vector3().copy(soul.position);
        targetPosition.y += 4;
        targetPosition.z += 6;

        new TWEEN.Tween(camera.position)
          .to(targetPosition, 500)
          .easing(TWEEN.Easing.Quadratic.Out)
          .start();

        camera.lookAt(soul.position);
      },
      'stationary': () => {
        // Overhaul: Isometric God View
        const targetPosition = new THREE.Vector3(15, 15, 15);

        new TWEEN.Tween(camera.position)
          .to(targetPosition, 1000)
          .easing(TWEEN.Easing.Quadratic.Out)
          .start();

        camera.lookAt(0, 0, 0); // Look at center of room
      }
    };

    const transition = transitions[mode];
    if (transition) {
      transition();
    }
  };

  const createCustomObject = async (objectData) => {
    const { scene } = sceneRef.current;
    if (!scene) return;

    const { type, position, color, size } = objectData;
    let geometry, material, mesh;

    switch (type) {
      case 'cube':
        geometry = new THREE.BoxGeometry(size.x || 1, size.y || 1, size.z || 1);
        break;
      case 'sphere':
        geometry = new THREE.SphereGeometry((size.x || 1) / 2);
        break;
      case 'cylinder':
        geometry = new THREE.CylinderGeometry((size.x || 1) / 2, (size.x || 1) / 2, size.y || 1);
        break;
      case 'cone':
        geometry = new THREE.ConeGeometry((size.x || 1) / 2, size.y || 1);
        break;
      default:
        geometry = new THREE.BoxGeometry(1, 1, 1);
    }

    material = new THREE.MeshLambertMaterial({
      color: color || 0x666666,
      transparent: true,
      opacity: 0.8
    });

    mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(position.x || 0, position.y || 1, position.z || 0);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData = { isCustomObject: true, ...objectData };

    scene.add(mesh);

    try {
      const objectId = await saveCustomObject({
        ...objectData,
        meshId: mesh.uuid
      });
      mesh.userData.firebaseId = objectId;
      console.log('Custom object saved to Firebase with ID:', objectId);
    } catch (error) {
      console.error('Failed to save custom object to Firebase:', error);
    }

    return mesh;
  };

  const loadCustomObjects = async (scene) => {
    try {
      const customObjects = await getCustomObjects();
      console.log(`Loading ${customObjects.length} custom objects from Firebase`);

      customObjects.forEach(objectData => {
        const { type, position, color, size } = objectData;
        let geometry, material, mesh;

        switch (type) {
          case 'cube':
            geometry = new THREE.BoxGeometry(size.x || 1, size.y || 1, size.z || 1);
            break;
          case 'sphere':
            geometry = new THREE.SphereGeometry((size.x || 1) / 2);
            break;
          case 'cylinder':
            geometry = new THREE.CylinderGeometry((size.x || 1) / 2, (size.x || 1) / 2, size.y || 1);
            break;
          case 'cone':
            geometry = new THREE.ConeGeometry((size.x || 1) / 2, size.y || 1);
            break;
          default:
            geometry = new THREE.BoxGeometry(1, 1, 1);
        }

        material = new THREE.MeshLambertMaterial({
          color: color || 0x666666,
          transparent: true,
          opacity: 0.8
        });

        mesh = new THREE.Mesh(geometry, material);
        mesh.position.set(position.x || 0, position.y || 1, position.z || 0);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.userData = {
          isCustomObject: true,
          firebaseId: objectData.id,
          ...objectData
        };

        scene.add(mesh);
      });
    } catch (error) {
      console.error('Failed to load custom objects from Firebase:', error);
    }
  };

  useEffect(() => {
    const cleanup = initializeScene();
    return () => cleanup();
  }, []);

  useEffect(() => {
    handleCameraTransition(cameraMode);
  }, [cameraMode]);

  return (
    <div className="absolute inset-0 w-full h-full">
      <div
        ref={mountRef}
        className="w-full h-full"
        style={{ background: 'transparent' }}
      />

      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <div className="glass-morphism rounded-lg p-4 opacity-0 hover:opacity-100 transition-opacity duration-300">
          <div className="flex items-center space-x-2 text-text-secondary">
            <Icon name="Eye" size={16} />
            <span className="text-sm">
              Viewing: {cameraMode.replace('-', ' ').replace(/ \w/g, l => l.toUpperCase())} Mode
            </span>
          </div>
        </div>
      </div>

      {/* Feature #7: Emotional Tint Overlay */}
      <div
        className="absolute inset-0 pointer-events-none transition-colors duration-1000 ease-in-out"
        style={{
          background: moodColor,
          mixBlendMode: 'overlay'
        }}
      />

      {/* Feature #8: Memory/Thought Bubble */}
      {thoughtBubble && (
        <div className="absolute top-1/3 left-1/2 transform -translate-x-1/2 -translate-y-full pointer-events-none animate-bounce z-20">
          <div className="bg-white/90 text-black px-4 py-2 rounded-2xl rounded-bl-none shadow-lg text-sm font-bold border-2 border-primary">
            {thoughtBubble}
          </div>
        </div>
      )}



      {/* Feature #41: Quest Tracker */}
      <div className="absolute top-20 right-4 glass-morphism p-3 rounded-lg border border-white/10 w-48 z-40">
        <div className="text-xs text-text-tertiary uppercase tracking-widest mb-1">Daily Quest</div>
        <div className="text-sm font-bold text-white mb-2">Distance Traveled</div>
        <div className="w-full bg-black/50 h-2 rounded-full overflow-hidden">
          <div
            className="bg-accent h-full transition-all duration-500"
            style={{ width: `${(questProgress / QUEST_GOAL) * 100}%` }}
          />
        </div>
        {questCompleted && <div className="text-xs text-green-400 mt-1 animate-pulse">COMPLETED!</div>}
      </div>

      {/* Feature #42: Achievement Toast */}
      {achievement && (
        <div className="absolute bottom-10 left-1/2 transform -translate-x-1/2 glass-morphism bg-black/80 border border-primary p-4 rounded-xl flex items-center space-x-4 animate-[slide-up_0.5s_ease-out] z-50">
          <div className="w-10 h-10 bg-primary rounded-full flex items-center justify-center text-black">
            <Icon name="Star" size={20} />
          </div>
          <div>
            <div className="text-xs text-primary font-bold uppercase">Achievement Unlocked</div>
            <div className="text-white font-bold">{achievement.title}</div>
            <div className="text-xs text-text-secondary">{achievement.desc}</div>
          </div>
        </div>
      )}

      {typeof process !== 'undefined' && process.env?.NODE_ENV === 'development' && (
        <div className="absolute top-4 left-4 glass-morphism rounded p-2 text-xs text-text-tertiary">
          <div>Camera: {cameraMode}</div>
          <div>Objects: {sceneRef.current.scene?.children?.length || 0}</div>
          <div>NPCs: {worldData.cityscape.npcs}</div>
          <div>Time: {worldState.timeOfDay}</div>
        </div>
      )}
    </div>
  );
});

WebGLViewport.displayName = 'WebGLViewport';

export default WebGLViewport;
