import React from 'react';
import Icon from 'components/AppIcon';

const UpgradeTiers = ({ tiers, selectedTier, onTierSelect, formatPrice }) => {
  return (
    <div className="grid gap-4">
      {tiers.map((tier) => (
        <div
          key={tier.id}
          className={`relative p-4 rounded-lg border-2 cursor-pointer transition-smooth ${
            selectedTier === tier.id
              ? 'border-primary bg-primary/5' :'border-white/10 hover:border-white/20 glass-morphism'
          }`}
          onClick={() => onTierSelect(tier.id)}
        >
          {tier.popular && (
            <div className="absolute -top-3 left-4">
              <span className="bg-primary text-white text-xs font-medium px-3 py-1 rounded-full">
                Most Popular
              </span>
            </div>
          )}
          
          {tier.savings && (
            <div className="absolute -top-3 right-4">
              <span className="bg-success text-white text-xs font-medium px-2 py-1 rounded-full">
                {tier.savings}
              </span>
            </div>
          )}

          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className={`w-5 h-5 rounded-full border-2 ${
                selectedTier === tier.id
                  ? 'border-primary bg-primary' :'border-white/30'
              }`}>
                {selectedTier === tier.id && (
                  <div className="w-3 h-3 bg-white rounded-full m-0.5" />
                )}
              </div>
              
              <div>
                <h3 className="font-heading font-semibold text-text-primary">
                  {tier.name}
                </h3>
                <p className="text-sm text-text-secondary">{tier.description}</p>
              </div>
            </div>

            <div className="text-right">
              <div className="text-xl font-bold text-primary">
                {formatPrice(tier.price)}
              </div>
              <div className="flex items-center space-x-1 text-text-secondary text-sm">
                <Icon name="Zap" size={14} />
                <span>{tier.actions} actions</span>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default UpgradeTiers;