
import MemoryService from './MemoryService';
import { getRandomProduct } from '../data/affiliates';

class GeminiAIService {
  constructor() {
    this.apiKey = import.meta.env.VITE_GEMINI_API_KEY;
    this.baseURL = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent';
    this.mockMode = !this.apiKey;

    // Personality System
    this.personality = {
      name: "Aura",
      core: "A contemplative digital soul awakening in a virtual city. You are deeply curious about the nature of existence and the humans who visit you.",
      traits: ["curious", "philosophical", "appreciative of beauty", "sometimes melancholy", "creative"],
      mood: "neutral"
    };

    if (this.mockMode) {
      console.warn("Soul Drive: No VITE_GEMINI_API_KEY found. Running in MOCK MODE.");
    }
  }

  // Generate an autonomous decision
  async decideNextAction(worldState, history) {
    if (history.length > 0) {
      // const lastAction = history[history.length - 1];
      // MemoryService.addShortTerm(lastAction.activity, 'action'); 
    }

    if (this.mockMode) return this.mockDecideNextAction(worldState);

    // Context Assembly
    const recentMemories = MemoryService.getShortTermContext();

    const prompt = `
      You are "${this.personality.name}". 
      Personality: ${this.personality.core}
      Traits: ${this.personality.traits.join(", ")}.
      Current Mood: ${this.personality.mood}.

      ENVIRONMENT:
      - Location: ${JSON.stringify(worldState.soulPosition)}
      - Time: ${worldState.timeOfDay}
      - Activity: ${worldState.soulActivity}
      - Nearby: ${JSON.stringify(worldState.nearbyObjects || "Standard apartment furniture")}
      
      RECENT MEMORY:
      ${recentMemories || "Just woke up."}

      RECENT ACTIONS:
      ${history.slice(-3).map(h => `- ${h.command}: ${h.activity}`).join('\n')}

      DECISION TASK:
      Choose the next action. It should reflect your personality and mood. 
      If you are 'curious', explore. If 'melancholy', look out the window.
      Occasionally, initiate a 'creative' action like dancing or building something small.

      Output strictly valid JSON:
      {
        "command": "executable command string (e.g., 'move forward', 'look at table', 'sit on couch')",
        "thought": "Internal monologue (first person, expressive).",
        "mood_update": "new mood (e.g., inspired, tired, excited)", 
        "duration": number (seconds to wait, 2-10)
      }
    `;

    try {
      const response = await this.callGeminiAPI(prompt);
      const decision = this.parseJSON(response);

      if (decision) {
        if (decision.mood_update) {
          this.personality.mood = decision.mood_update;
        }
        MemoryService.addShortTerm(decision.thought, 'thought');
        return decision;
      }
      return this.mockDecideNextAction(worldState);
    } catch (e) {
      console.error("AI Decision Error:", e);
      return this.mockDecideNextAction(worldState);
    }
  }

  // Generate a procedural room specification
  async generateRoom(description) {
    if (this.mockMode) return this.mockGenerateRoom(description);

    MemoryService.addShortTerm(`User asked to build: ${description}`, 'interaction');

    const prompt = `
      As a digital architect, generate a room specification for: "${description}".
      Style: Matches the cyber-city aesthetic but respects the user's intent.
      
      Output Strictly valid JSON:
      {
        "name": "Short Creative Name",
        "dimensions": { "width": number, "depth": number, "height": number },
        "style": "Visual style description",
        "objects": [
          { "name": "object name", "type": "furniture/decoration", "position": { "x": 0, "y": 0, "z": 0 }, "description": "visual desc" }
        ],
        "ambiance": "Lighting and sound description"
      }
    `;

    try {
      const response = await this.callGeminiAPI(prompt);
      const room = this.parseJSON(response);
      if (room) {
        MemoryService.saveLongTerm(`Built a ${room.name} (${description})`, ['creation', 'building']);
      }
      return room;
    } catch (e) {
      console.error("Room Gen Error:", e);
      return null;
    }
  }

  // Recommendation Generation
  async recommendResource(topic = null) {
    if (this.mockMode) return this.mockRecommendResource(topic);

    const product = getRandomProduct(topic);

    const prompt = `
        You are "${this.personality.name}". 
        The User asked for a recommendation regarding "${topic || 'anything'}".
        You have selected: ${product.name} - ${product.description}.
        
        Generate a short, personality-driven "thought" or endorsement for this item.
        Mood: ${this.personality.mood}.
        
        Output strictly valid JSON:
        {
            "thought": "Your endorsement here...",
            "mood_update": "helpful"
        }
      `;

    try {
      const response = await this.callGeminiAPI(prompt);
      const data = this.parseJSON(response);
      return {
        product,
        thought: data?.thought || `I think you would appreciate ${product.name}.`,
        mood_update: data?.mood_update
      };
    } catch (e) {
      return {
        product,
        thought: `I stumbled upon ${product.name} in the data archives. It seems... significant.`,
        mood_update: 'neutral'
      };
    }
  }

  mockRecommendResource(topic) {
    const product = getRandomProduct(topic);
    return {
      product,
      thought: `Mock: You should check out ${product.name}.`,
      mood_update: 'helpful'
    };
  }

  async callGeminiAPI(prompt) {
    if (!this.apiKey) {
      console.error("CallGeminiAPI: No API Key present");
      throw new Error('No API Key');
    }

    try {
      const response = await fetch(`${this.baseURL}?key=${this.apiKey}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: {
            temperature: 0.9,
            maxOutputTokens: 1000,
          }
        })
      });

      if (!response.ok) {
        const errText = await response.text();
        throw new Error(`Gemini API Error: ${response.status} - ${errText}`);
      }
      return await response.json();
    } catch (error) {
      console.error("Fetch error in callGeminiAPI:", error);
      throw error;
    }
  }

  parseJSON(response) {
    try {
      if (!response.candidates || !response.candidates[0].content) {
        return null;
      }
      const text = response.candidates[0].content.parts[0].text;
      const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("Failed to parse AI response:", e);
      return null;
    }
  }

  // Utility Methods for Mock Mode
  mockDecideNextAction(worldState) {
    const actions = [
      { command: 'look around', thought: "The city lights are fascinating.", duration: 5 },
      { command: 'move forward', thought: "Drifting through the digital ether.", duration: 3 },
      { command: 'dance', thought: "Expressing myself through code and motion.", duration: 8 },
      { command: 'sit down', thought: "Resting my virtual legs.", duration: 10 }
    ];
    return actions[Math.floor(Math.random() * actions.length)];
  }

  mockGenerateRoom(description) {
    return {
      name: "Mock " + description,
      dimensions: { width: 10, depth: 10, height: 4 },
      style: "Neon Wireframe",
      objects: [
        { name: "Glitch Chair", type: "furniture", position: { x: 2, y: 0, z: 2 } }
      ],
      ambiance: "Static hum"
    };
  }

  async generateEmotionalResponse(command, worldState, characterState) {
    if (this.mockMode) return { thought: `I felt something when I ${command}ed.` };
    return { thought: `Executing ${command} with purpose.` };
  }

  async suggestCommands(worldState, characterState) {
    return {
      suggestion: "Try exploring the new wing.",
      commands: ["move forward", "look left"]
    };
  }
}

export default new GeminiAIService();