import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const ActionCounter = () => {
  const [actionCount, setActionCount] = useState(47);
  const [maxActions] = useState(100);
  const [isLowActions, setIsLowActions] = useState(false);
  const [showUpgradePrompt, setShowUpgradePrompt] = useState(false);
  const location = useLocation();

  const isMainWorld = location.pathname === '/main-3d-world-interface';
  const progressPercentage = (actionCount / maxActions) * 100;

  useEffect(() => {
    setIsLowActions(actionCount <= 10);
    if (actionCount <= 5) {
      setShowUpgradePrompt(true);
    }
  }, [actionCount]);

  const handleUpgradeClick = () => {
    window.location.href = '/payment-action-upgrade';
  };

  const handleActionUse = () => {
    if (actionCount > 0) {
      setActionCount(prev => prev - 1);
    }
  };

  const getStatusColor = () => {
    if (actionCount <= 5) return 'text-error';
    if (actionCount <= 10) return 'text-warning';
    return 'text-success';
  };

  const getProgressColor = () => {
    if (actionCount <= 5) return 'bg-error';
    if (actionCount <= 10) return 'bg-warning';
    return 'bg-success';
  };

  if (isMainWorld) {
    return (
      <div className="fixed bottom-6 right-6 z-1100">
        <div className="glass-morphism rounded-xl p-4 min-w-[200px] animate-fade-in">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center space-x-2">
              <Icon name="Zap" size={18} className={getStatusColor()} />
              <span className="font-heading font-semibold text-text-primary">Actions</span>
            </div>
            <span className={`font-data font-medium ${getStatusColor()}`}>
              {actionCount}/{maxActions}
            </span>
          </div>

          <div className="w-full bg-surface rounded-full h-2 mb-3">
            <div 
              className={`h-2 rounded-full transition-all duration-300 ${getProgressColor()}`}
              style={{ width: `${progressPercentage}%` }}
            />
          </div>

          {isLowActions && (
            <div className="space-y-2">
              <div className="text-xs text-text-secondary">
                {actionCount <= 5 ? 'Critical: Actions almost depleted!' : 'Warning: Low actions remaining'}
              </div>
              <button
                onClick={handleUpgradeClick}
                className="w-full bg-primary hover:bg-primary-600 text-white font-medium py-2 px-3 rounded-lg transition-smooth flex items-center justify-center space-x-2 neon-glow"
              >
                <Icon name="Plus" size={16} />
                <span>Get More Actions</span>
              </button>
            </div>
          )}

          {showUpgradePrompt && (
            <div className="mt-3 p-3 bg-accent/10 border border-accent/20 rounded-lg">
              <div className="text-xs text-accent font-medium mb-2">
                Upgrade to Premium for unlimited actions!
              </div>
              <button
                onClick={handleUpgradeClick}
                className="text-xs text-accent hover:text-accent-400 underline transition-smooth"
              >
                Learn more →
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center space-x-4 px-4 py-2 glass-morphism rounded-lg">
      <div className="flex items-center space-x-2">
        <Icon name="Zap" size={16} className={getStatusColor()} />
        <span className="font-data text-sm font-medium text-text-primary">
          {actionCount}/{maxActions}
        </span>
      </div>

      <div className="w-20 bg-surface rounded-full h-1.5">
        <div 
          className={`h-1.5 rounded-full transition-all duration-300 ${getProgressColor()}`}
          style={{ width: `${progressPercentage}%` }}
        />
      </div>

      {isLowActions && (
        <button
          onClick={handleUpgradeClick}
          className="bg-primary hover:bg-primary-600 text-white text-xs font-medium py-1 px-3 rounded-md transition-smooth flex items-center space-x-1"
        >
          <Icon name="Plus" size={12} />
          <span>Upgrade</span>
        </button>
      )}
    </div>
  );
};

export default ActionCounter;