import React from 'react';
import Icon from 'components/AppIcon';

const MetricsCard = ({ title, value, icon, color = 'primary', trend }) => {
  const colorClasses = {
    primary: 'text-primary bg-primary/10 border-primary/20',
    success: 'text-success bg-success/10 border-success/20',
    warning: 'text-warning bg-warning/10 border-warning/20',
    accent: 'text-accent bg-accent/10 border-accent/20',
    error: 'text-error bg-error/10 border-error/20'
  };

  const getTrendColor = (trend) => {
    if (trend?.startsWith('+')) return 'text-success';
    if (trend?.startsWith('-')) return 'text-error';
    return 'text-text-secondary';
  };

  return (
    <div className="glass-morphism rounded-lg p-6 border border-white/10 hover:border-white/20 transition-smooth">
      <div className="flex items-center justify-between mb-4">
        <div className={`p-3 rounded-lg ${colorClasses[color]}`}>
          <Icon name={icon} size={24} />
        </div>
        {trend && (
          <span className={`text-sm font-medium ${getTrendColor(trend)}`}>
            {trend}
          </span>
        )}
      </div>
      
      <div>
        <h3 className="text-2xl font-heading font-bold text-text-primary mb-1">
          {value}
        </h3>
        <p className="text-text-secondary text-sm">
          {title}
        </p>
      </div>
    </div>
  );
};

export default MetricsCard;