import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const CameraPerspectiveToggle = ({ currentMode, onModeChange }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const cameraOptions = [
    {
      mode: 'first-person',
      label: 'First Person',
      icon: 'User',
      description: 'See through Soul\'s eyes',
      shortcut: '1'
    },
    {
      mode: 'third-person',
      label: 'Third Person',
      icon: 'Users',
      description: 'Follow Soul from behind',
      shortcut: '2'
    },
    {
      mode: 'stationary',
      label: 'Stationary',
      icon: 'Camera',
      description: 'Fixed environmental view',
      shortcut: '3'
    }
  ];

  const currentOption = cameraOptions.find(option => option.mode === currentMode);

  const handleModeSelect = (mode) => {
    onModeChange(mode);
    setIsExpanded(false);
  };

  const handleKeyPress = (e) => {
    const keyMap = {
      '1': 'first-person',
      '2': 'third-person',
      '3': 'stationary'
    };
    
    if (keyMap[e.key]) {
      handleModeSelect(keyMap[e.key]);
    }
  };

  React.useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, []);

  return (
    <div className="relative">
      {/* Main Toggle Button */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="glass-morphism rounded-lg p-3 flex items-center space-x-2 hover:bg-white/10 transition-smooth neon-glow"
        title={`Current: ${currentOption?.label} (Press ${currentOption?.shortcut})`}
      >
        <Icon name={currentOption?.icon || 'Camera'} size={20} className="text-primary" />
        <span className="hidden sm:block text-sm font-medium text-text-primary">
          {currentOption?.label}
        </span>
        <Icon 
          name={isExpanded ? 'ChevronUp' : 'ChevronDown'} 
          size={16} 
          className="text-text-secondary" 
        />
      </button>

      {/* Expanded Options */}
      {isExpanded && (
        <div className="absolute top-full right-0 mt-2 w-64 glass-morphism rounded-lg border border-white/20 animate-slide-down z-1200">
          <div className="p-2">
            <div className="text-xs text-text-secondary mb-2 px-2">
              Camera Perspective
            </div>
            {cameraOptions.map((option) => (
              <button
                key={option.mode}
                onClick={() => handleModeSelect(option.mode)}
                className={`w-full flex items-center space-x-3 p-3 rounded-lg transition-smooth text-left ${
                  currentMode === option.mode
                    ? 'bg-primary/20 text-primary border border-primary/30' :'text-text-secondary hover:text-text-primary hover:bg-white/5'
                }`}
              >
                <Icon name={option.icon} size={18} />
                <div className="flex-1">
                  <div className="font-medium">{option.label}</div>
                  <div className="text-xs opacity-75">{option.description}</div>
                </div>
                <div className="text-xs bg-surface/50 px-2 py-1 rounded">
                  {option.shortcut}
                </div>
              </button>
            ))}
          </div>
          
          <div className="border-t border-white/10 p-3">
            <div className="text-xs text-text-tertiary">
              <Icon name="Keyboard" size={12} className="inline mr-1" />
              Use number keys 1-3 for quick switching
            </div>
          </div>
        </div>
      )}

      {/* Backdrop */}
      {isExpanded && (
        <div 
          className="fixed inset-0 z-1100"
          onClick={() => setIsExpanded(false)}
        />
      )}
    </div>
  );
};

export default CameraPerspectiveToggle;