import React, { useEffect, useState } from 'react';
import Icon from 'components/AppIcon';

const SuccessAnimation = () => {
  const [particles, setParticles] = useState([]);

  useEffect(() => {
    // Generate random particles for celebration effect
    const newParticles = Array.from({ length: 20 }, (_, i) => ({
      id: i,
      x: Math.random() * 100,
      y: Math.random() * 100,
      delay: Math.random() * 2,
      duration: 2 + Math.random() * 2
    }));
    setParticles(newParticles);
  }, []);

  return (
    <div className="fixed inset-0 z-1300 pointer-events-none">
      {/* Success Message */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="glass-morphism rounded-xl p-8 text-center animate-scale-in">
          <div className="w-16 h-16 bg-success rounded-full flex items-center justify-center mx-auto mb-4 neon-glow">
            <Icon name="Check" size={32} color="white" />
          </div>
          <h2 className="text-2xl font-heading font-bold text-text-primary mb-2">
            Payment Successful!
          </h2>
          <p className="text-text-secondary">
            Your actions have been added to your account
          </p>
        </div>
      </div>

      {/* Particle Effects */}
      {particles.map((particle) => (
        <div
          key={particle.id}
          className="absolute w-2 h-2 bg-primary rounded-full animate-bounce"
          style={{
            left: `${particle.x}%`,
            top: `${particle.y}%`,
            animationDelay: `${particle.delay}s`,
            animationDuration: `${particle.duration}s`
          }}
        />
      ))}

      {/* Confetti Effect */}
      <div className="absolute inset-0 overflow-hidden">
        {Array.from({ length: 50 }).map((_, i) => (
          <div
            key={i}
            className="absolute w-1 h-4 bg-gradient-to-b from-primary to-accent animate-pulse"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              transform: `rotate(${Math.random() * 360}deg)`,
              animationDelay: `${Math.random() * 3}s`
            }}
          />
        ))}
      </div>
    </div>
  );
};

export default SuccessAnimation;