// Procedural generation utilities for Soul Drive

export const generateRandomCommands = () => {
  const actions = ['move', 'look', 'dance', 'wave', 'sit', 'stand', 'turn', 'explore'];
  const targets = ['forward', 'backward', 'around', 'at window', 'down', 'up', 'left', 'right'];
  const modifiers = ['slowly', 'quickly', 'gracefully', 'energetically', 'carefully'];
  
  const commands = [];
  for (let i = 0; i < 10; i++) {
    const action = actions[Math.floor(Math.random() * actions.length)];
    const target = targets[Math.floor(Math.random() * targets.length)];
    const modifier = Math.random() > 0.5 ? modifiers[Math.floor(Math.random() * modifiers.length)] : '';
    
    let command = `${action} ${target}`;
    if (modifier && action !== 'sit' && action !== 'stand') {
      command += ` ${modifier}`;
    }
    
    commands.push(command.trim());
  }
  
  return commands;
};

export const generateApartmentLayout = () => {
  const furniture = [
    { type: 'sofa', position: { x: -3, y: 0.4, z: 3 }, size: { x: 2, y: 0.8, z: 1 } },
    { type: 'coffee_table', position: { x: -2, y: 0.5, z: 2 }, size: { x: 1.5, y: 0.1, z: 0.8 } },
    { type: 'tv_stand', position: { x: -3, y: 0.6, z: -5 }, size: { x: 2, y: 1.2, z: 0.5 } },
    { type: 'bookshelf', position: { x: 5, y: 1, z: -3 }, size: { x: 0.3, y: 2, z: 2 } },
    { type: 'plant', position: { x: 4, y: 0.8, z: 4 }, size: { x: 0.5, y: 1.6, z: 0.5 } },
    { type: 'lamp', position: { x: -4, y: 1.5, z: 2.5 }, size: { x: 0.3, y: 0.3, z: 0.3 } }
  ];
  
  // Randomly position some furniture
  return furniture.map(item => ({
    ...item,
    position: {
      ...item.position,
      x: item.position.x + (Math.random() - 0.5) * 2,
      z: item.position.z + (Math.random() - 0.5) * 2
    }
  }));
};

export const generateCityBuildings = (count = 100) => {
  const buildings = [];
  const buildingTypes = ['office', 'residential', 'commercial', 'industrial'];
  
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const radius = 50 + Math.random() * 150;
    
    buildings.push({
      id: i,
      type: buildingTypes[Math.floor(Math.random() * buildingTypes.length)],
      position: {
        x: Math.cos(angle) * radius + (Math.random() - 0.5) * 20,
        y: 0,
        z: Math.sin(angle) * radius + (Math.random() - 0.5) * 20
      },
      size: {
        x: 2 + Math.random() * 4,
        y: 10 + Math.random() * 40,
        z: 2 + Math.random() * 4
      },
      color: {
        hue: Math.random() * 0.1 + 0.55, // Blue-ish hues
        saturation: 0.2 + Math.random() * 0.3,
        lightness: 0.1 + Math.random() * 0.4
      },
      hasLights: Math.random() > 0.3
    });
  }
  
  return buildings;
};

export const generateNPCs = (count = 20) => {
  const npcs = [];
  const activities = ['walking', 'standing', 'looking', 'waiting'];
  
  for (let i = 0; i < count; i++) {
    npcs.push({
      id: i,
      position: {
        x: (Math.random() - 0.5) * 80,
        y: 0,
        z: (Math.random() - 0.5) * 80
      },
      activity: activities[Math.floor(Math.random() * activities.length)],
      speed: 0.5 + Math.random() * 1.5,
      direction: Math.random() * Math.PI * 2,
      target: null
    });
  }
  
  return npcs;
};

export const generateWeatherEffects = () => {
  const weatherTypes = ['clear', 'cloudy', 'rain', 'fog', 'storm'];
  const currentWeather = weatherTypes[Math.floor(Math.random() * weatherTypes.length)];
  
  return {
    type: currentWeather,
    intensity: Math.random(),
    windSpeed: Math.random() * 5,
    visibility: currentWeather === 'fog' ? 0.3 + Math.random() * 0.4 : 0.8 + Math.random() * 0.2,
    effects: {
      particles: currentWeather === 'rain' || currentWeather === 'storm',
      lightning: currentWeather === 'storm' && Math.random() > 0.7,
      ambientSound: currentWeather
    }
  };
};

