export const generateContextualCommands = (worldState, soulState) => {
  const { timeOfDay, weather } = worldState;
  const { position, activity } = soulState;
  
  const contextCommands = [];
  
  // Time-based suggestions
  if (timeOfDay === 'morning') {
    contextCommands.push('make coffee', 'stretch', 'look at sunrise');
  } else if (timeOfDay === 'evening') {
    contextCommands.push('relax', 'look at city lights', 'sit down');
  } else if (timeOfDay === 'night') {
    contextCommands.push('look at stars', 'turn on lights', 'prepare for sleep');
  }
  
  // Weather-based suggestions
  if (weather === 'rain') {
    contextCommands.push('listen to rain', 'watch raindrops', 'stay inside');
  } else if (weather === 'clear') {
    contextCommands.push('enjoy the view', 'open window', 'wave at window');
  }
  
  // Position-based suggestions
  if (position.x > 2) { // Near kitchen
    contextCommands.push('make coffee', 'prepare food', 'clean up');
  } else if (position.x < -2) { // Near living area
    contextCommands.push('sit on sofa', 'watch tv', 'read book');
  }
  
  // Activity-based suggestions
  if (activity.includes('sitting')) {
    contextCommands.push('stand up', 'stretch', 'walk around');
  } else if (activity.includes('standing')) {
    contextCommands.push('sit down', 'move forward', 'dance');
  }
  
  return contextCommands.slice(0, 5); // Return top 5 contextual commands
};