import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';

import LiveChat from './components/LiveChat';
import JourneyArchive from './components/JourneyArchive';
import Leaderboards from './components/Leaderboards';

const CommunitySocialFeatures = () => {
  const [activeTab, setActiveTab] = useState('chat');
  const [notifications, setNotifications] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState(47);

  const tabs = [
    { id: 'chat', label: 'Live Chat', icon: 'MessageCircle', count: 12 },
    { id: 'archive', label: 'Journey Archive', icon: 'Archive', count: null },
    { id: 'leaderboards', label: 'Leaderboards', icon: 'Trophy', count: null }
  ];

  const mockNotifications = [
    {
      id: 1,
      type: 'mention',
      user: 'CyberNinja',
      message: 'mentioned you in a command',
      timestamp: new Date(Date.now() - 300000),
      read: false
    },
    {
      id: 2,
      type: 'reaction',
      user: 'NeonDreamer',
      message: 'reacted to your journey moment',
      timestamp: new Date(Date.now() - 600000),
      read: false
    },
    {
      id: 3,
      type: 'world_event',
      message: 'Soul completed a major quest sequence',
      timestamp: new Date(Date.now() - 900000),
      read: true
    }
  ];

  useEffect(() => {
    setNotifications(mockNotifications);
    
    // Simulate real-time user count updates
    const interval = setInterval(() => {
      setOnlineUsers(prev => prev + Math.floor(Math.random() * 3) - 1);
    }, 30000);

    return () => clearInterval(interval);
  }, []);

  const renderTabContent = () => {
    switch (activeTab) {
      case 'chat':
        return <LiveChat />;
      case 'archive':
        return <JourneyArchive />;
      case 'leaderboards':
        return <Leaderboards />;
      default:
        return <LiveChat />;
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'mention':
        return 'AtSign';
      case 'reaction':
        return 'Heart';
      case 'world_event':
        return 'Globe';
      default:
        return 'Bell';
    }
  };

  const formatTimeAgo = (timestamp) => {
    const now = new Date();
    const diff = now - timestamp;
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    
    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes}m ago`;
    if (hours < 24) return `${hours}h ago`;
    return timestamp.toLocaleDateString();
  };

  return (
    <div className="min-h-screen bg-background">
      {/* Header Section */}
      <div className="glass-morphism border-b border-white/10 sticky top-16 z-50">
        <div className="px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between space-y-4 sm:space-y-0">
            <div>
              <h1 className="text-2xl sm:text-3xl font-heading font-bold text-text-primary">
                Community Hub
              </h1>
              <p className="text-text-secondary mt-1">
                Connect, share, and explore together in Soul Drive
              </p>
            </div>
            
            <div className="flex items-center space-x-4">
              {/* Online Users Counter */}
              <div className="flex items-center space-x-2 glass-morphism px-4 py-2 rounded-lg">
                <div className="w-2 h-2 bg-success rounded-full animate-pulse" />
                <span className="text-sm font-medium text-text-primary">{onlineUsers} online</span>
              </div>

              {/* Notifications */}
              <div className="relative">
                <button className="p-2 glass-morphism rounded-lg text-text-secondary hover:text-text-primary transition-smooth">
                  <Icon name="Bell" size={20} />
                  {notifications.filter(n => !n.read).length > 0 && (
                    <span className="absolute -top-1 -right-1 bg-accent text-white text-xs rounded-full w-5 h-5 flex items-center justify-center">
                      {notifications.filter(n => !n.read).length}
                    </span>
                  )}
                </button>
              </div>

              {/* Quick Actions */}
              <Link
                to="/main-3d-world-interface"
                className="bg-primary hover:bg-primary-600 text-white px-4 py-2 rounded-lg transition-smooth flex items-center space-x-2 neon-glow"
              >
                <Icon name="Play" size={16} />
                <span className="hidden sm:inline">Enter World</span>
              </Link>
            </div>
          </div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="px-4 sm:px-6 lg:px-8 py-4">
        <div className="flex space-x-1 glass-morphism p-1 rounded-lg w-fit">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-2 px-4 py-2 rounded-md transition-smooth ${
                activeTab === tab.id
                  ? 'bg-primary text-white neon-glow' :'text-text-secondary hover:text-text-primary hover:bg-white/5'
              }`}
            >
              <Icon name={tab.icon} size={18} />
              <span className="font-medium">{tab.label}</span>
              {tab.count && (
                <span className={`text-xs px-2 py-0.5 rounded-full ${
                  activeTab === tab.id ? 'bg-white/20' : 'bg-primary/20 text-primary'
                }`}>
                  {tab.count}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="px-4 sm:px-6 lg:px-8 pb-8">
        {renderTabContent()}
      </div>

      {/* Floating Notifications Panel (Mobile) */}
      {notifications.filter(n => !n.read).length > 0 && (
        <div className="fixed bottom-20 right-4 z-50 md:hidden">
          <div className="glass-morphism rounded-lg p-4 max-w-xs animate-slide-up">
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-medium text-text-primary">Recent Activity</h3>
              <button className="text-text-tertiary hover:text-text-primary">
                <Icon name="X" size={16} />
              </button>
            </div>
            <div className="space-y-2">
              {notifications.filter(n => !n.read).slice(0, 2).map((notification) => (
                <div key={notification.id} className="flex items-start space-x-2">
                  <Icon name={getNotificationIcon(notification.type)} size={14} className="text-primary mt-0.5" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-text-secondary">
                      {notification.user && (
                        <span className="font-medium text-text-primary">{notification.user} </span>
                      )}
                      {notification.message}
                    </p>
                    <p className="text-xs text-text-tertiary">{formatTimeAgo(notification.timestamp)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CommunitySocialFeatures;