import React from 'react';
import Icon from 'components/AppIcon';

const CountdownTimer = ({ timeRemaining }) => {
  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return { hours, minutes, seconds: secs };
  };

  const { hours, minutes, seconds } = formatTime(timeRemaining);

  return (
    <div className="bg-surface/50 rounded-lg p-4">
      <div className="flex items-center justify-center space-x-4 mb-3">
        <div className="text-center">
          <div className="text-2xl font-data font-bold text-warning">
            {hours.toString().padStart(2, '0')}
          </div>
          <div className="text-xs text-text-tertiary">Hours</div>
        </div>
        <div className="text-warning">:</div>
        <div className="text-center">
          <div className="text-2xl font-data font-bold text-warning">
            {minutes.toString().padStart(2, '0')}
          </div>
          <div className="text-xs text-text-tertiary">Minutes</div>
        </div>
        <div className="text-warning">:</div>
        <div className="text-center">
          <div className="text-2xl font-data font-bold text-warning">
            {seconds.toString().padStart(2, '0')}
          </div>
          <div className="text-xs text-text-tertiary">Seconds</div>
        </div>
      </div>
      
      <div className="text-center">
        <div className="flex items-center justify-center space-x-2 text-sm text-text-secondary">
          <Icon name="Gift" size={16} className="text-warning" />
          <span>5 free actions when timer reaches zero</span>
        </div>
      </div>
    </div>
  );
};

export default CountdownTimer;