import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const TutorialModal = ({ isOpen, onClose }) => {
  const [currentStep, setCurrentStep] = useState(0);

  const tutorialSteps = [
    {
      title: "Welcome to Soul Drive",
      content: `Soul Drive is a collaborative 3D storytelling experience where you and other users control an AI character called "the Soul" through chat commands.

The Soul lives in a persistent urban environment that everyone can see and interact with in real-time.`,
      icon: "Zap",
      color: "text-primary"
    },
    {
      title: "Command System",
      content: `Use simple text commands to control the Soul:
• "move forward" - Navigate the world
• "turn left/right"- Change direction •"say [message]"- Make the Soul speak •"dance" - Perform animations
• "look around" - Observe surroundings

Commands are processed in order through a global queue system.`,
      icon: "MessageSquare",
      color: "text-success"
    },
    {
      title: "Camera Views",
      content: `Experience the world from multiple perspectives:

• First Person: See through the Soul's eyes
• Third Person: Follow the Soul from behind
• Environment: Fixed camera views of locations

Switch between views to get the best experience of the story unfolding.`,
      icon: "Camera",
      color: "text-warning"
    },
    {
      title: "Collaborative Building",
      content: `Work together to shape the world:
• Place buildings and structures
• Create roads and pathways
• Add decorative objects
• Modify the urban landscape

Your changes are visible to all users in real-time, creating a shared creative experience.`,
      icon: "Cube",
      color: "text-accent"
    },
    {
      title: "Action System",
      content: `Each IP address gets 5 free actions per day. Actions are used for:
• Sending commands to the Soul
• Placing objects in the world
• Modifying the environment

Upgrade for just $1 to get 20 additional actions, or subscribe for unlimited access.`,
      icon: "Zap",
      color: "text-error"
    }
  ];

  const nextStep = () => {
    if (currentStep < tutorialSteps.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const currentTutorial = tutorialSteps[currentStep];

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-1200 flex items-center justify-center p-4 animate-fade-in">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-background/80 backdrop-blur-md" onClick={onClose} />
      
      {/* Modal */}
      <div className="relative w-full max-w-2xl glass-morphism rounded-xl border border-white/20 animate-scale-in">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-white/10">
          <div className="flex items-center space-x-3">
            <div className={`w-10 h-10 bg-gradient-to-br from-current to-current opacity-20 rounded-lg flex items-center justify-center ${currentTutorial.color}`}>
              <Icon name={currentTutorial.icon} size={20} className={currentTutorial.color} />
            </div>
            <h2 className="text-xl font-heading font-semibold text-text-primary">
              {currentTutorial.title}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg text-text-secondary hover:text-text-primary hover:bg-white/5 transition-smooth"
          >
            <Icon name="X" size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6">
          <div className="prose prose-lg max-w-none text-text-secondary mb-8">
            <p className="whitespace-pre-line leading-relaxed">{currentTutorial.content}</p>
          </div>

          {/* Progress Indicators */}
          <div className="flex justify-center space-x-2 mb-6">
            {tutorialSteps.map((_, index) => (
              <div
                key={index}
                className={`w-2 h-2 rounded-full transition-smooth ${
                  index === currentStep ? 'bg-primary' : 'bg-white/20'
                }`}
              />
            ))}
          </div>

          {/* Navigation */}
          <div className="flex justify-between">
            <button
              onClick={prevStep}
              disabled={currentStep === 0}
              className="px-6 py-3 border border-white/20 text-text-secondary hover:text-text-primary hover:bg-white/5 rounded-lg transition-smooth disabled:opacity-50 disabled:cursor-not-allowed flex items-center space-x-2"
            >
              <Icon name="ChevronLeft" size={16} />
              <span>Previous</span>
            </button>

            <div className="flex space-x-4">
              <button
                onClick={onClose}
                className="px-6 py-3 text-text-secondary hover:text-text-primary transition-smooth"
              >
                Skip Tutorial
              </button>
              
              {currentStep === tutorialSteps.length - 1 ? (
                <button
                  onClick={onClose}
                  className="px-6 py-3 bg-primary hover:bg-primary-600 text-white font-medium rounded-lg transition-smooth neon-glow flex items-center space-x-2"
                >
                  <span>Get Started</span>
                  <Icon name="ArrowRight" size={16} />
                </button>
              ) : (
                <button
                  onClick={nextStep}
                  className="px-6 py-3 bg-primary hover:bg-primary-600 text-white font-medium rounded-lg transition-smooth neon-glow flex items-center space-x-2"
                >
                  <span>Next</span>
                  <Icon name="ChevronRight" size={16} />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TutorialModal;