import React, { useState, useEffect } from 'react';
import { firebaseAuth, auth } from '../services/firebase';
import { onAuthStateChanged } from 'firebase/auth';
import Icon from './AppIcon';

const AuthOverlay = () => {
    const [user, setUser] = useState(null);
    const [isOpen, setIsOpen] = useState(false);
    const [mode, setMode] = useState('login'); // login | signup
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [displayName, setDisplayName] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (u) => setUser(u));
        return () => unsubscribe();
    }, []);

    const handleAuth = async (e) => {
        e.preventDefault();
        setError('');
        try {
            if (mode === 'signup') {
                await firebaseAuth.signUp(email, password, displayName);
            } else {
                await firebaseAuth.signIn(email, password);
            }
            setIsOpen(false);
        } catch (err) {
            setError(err.message);
        }
    };

    if (user) {
        return (
            <div className="fixed top-4 right-4 z-1200 flex items-center gap-2">
                <div className="glass-morphism px-3 py-1 rounded-full flex items-center gap-2 text-xs">
                    <span className="w-2 h-2 bg-success rounded-full"></span>
                    {user.displayName}
                </div>
                <button
                    onClick={() => firebaseAuth.logOut()}
                    className="bg-surface/50 p-1 rounded-full hover:bg-error/20 hover:text-error transition-colors"
                >
                    <Icon name="LogOut" size={14} />
                </button>
            </div>
        );
    }

    return (
        <div className="fixed top-4 right-4 z-1200">
            {!isOpen && (
                <button
                    onClick={() => setIsOpen(true)}
                    className="glass-morphism px-4 py-2 rounded-full text-sm hover:bg-primary/20 transition-colors"
                >
                    Login / Join
                </button>
            )}

            {isOpen && (
                <div className="absolute top-12 right-0 w-72 glass-morphism rounded-xl p-4 animate-fade-in border border-white/10 shadow-xl bg-background/90 text-left">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="font-bold">{mode === 'login' ? 'Access Terminal' : 'New Identity'}</h3>
                        <button onClick={() => setIsOpen(false)}><Icon name="X" size={16} /></button>
                    </div>

                    <form onSubmit={handleAuth} className="space-y-3">
                        {mode === 'signup' && (
                            <input
                                type="text"
                                placeholder="display_name"
                                className="w-full bg-black/30 border border-white/10 rounded px-3 py-2 text-sm focus:border-primary outline-none"
                                value={displayName}
                                onChange={e => setDisplayName(e.target.value)}
                                required
                            />
                        )}
                        <input
                            type="email"
                            placeholder="email@net.com"
                            className="w-full bg-black/30 border border-white/10 rounded px-3 py-2 text-sm focus:border-primary outline-none"
                            value={email}
                            onChange={e => setEmail(e.target.value)}
                            required
                        />
                        <input
                            type="password"
                            placeholder="password"
                            className="w-full bg-black/30 border border-white/10 rounded px-3 py-2 text-sm focus:border-primary outline-none"
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            required
                        />

                        {error && <p className="text-error text-xs">{error}</p>}

                        <button type="submit" className="w-full bg-primary hover:bg-primary-600 text-white rounded py-2 text-sm font-bold transition-colors">
                            {mode === 'login' ? 'Authenticate' : 'Initialize'}
                        </button>
                    </form>

                    <div className="mt-4 text-center text-xs text-text-secondary">
                        {mode === 'login' ? "No ID?" : "Has ID?"}
                        <button
                            onClick={() => setMode(mode === 'login' ? 'signup' : 'login')}
                            className="text-primary hover:underline ml-1"
                        >
                            {mode === 'login' ? "Create one" : "Login"}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AuthOverlay;
