import React, { useState, useEffect, useRef } from 'react';
import { firebaseAuth, auth, db } from '../services/firebase';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, onSnapshot, updateDoc } from 'firebase/firestore';
import Icon from './AppIcon';

const CommunityChat = () => {
    const [messages, setMessages] = useState([]);
    const [inputText, setInputText] = useState('');
    const [user, setUser] = useState(null);
    const [isOpen, setIsOpen] = useState(false);
    const bottomRef = useRef(null);

    useEffect(() => {
        let unsubscribeProfile = () => { };

        const unsubscribeAuth = onAuthStateChanged(auth, u => {
            if (u) {
                // Sync Profile (Tier, Gold Name)
                unsubscribeProfile = onSnapshot(doc(db, 'users', u.uid), (doc) => {
                    if (doc.exists()) {
                        setUser({ ...u, ...doc.data() });
                    } else {
                        setUser(u);
                    }
                });
            } else {
                setUser(null);
                unsubscribeProfile();
            }
        });

        const unsubscribeChat = firebaseAuth.subscribeToChat((msgs) => {
            setMessages(msgs);
            setTimeout(() => bottomRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
        });

        return () => {
            unsubscribeAuth();
            unsubscribeProfile();
            if (typeof unsubscribeChat === 'function') unsubscribeChat();
        };
    }, []);

    const toggleSubscribe = async () => {
        if (!user) return;
        const newState = !user.isSubscribedToNewsletter;
        // Optimistic update
        setUser(prev => ({ ...prev, isSubscribedToNewsletter: newState }));
        await updateDoc(doc(db, 'users', user.uid), { isSubscribedToNewsletter: newState });
    };

    const sendMessage = (e) => {
        e.preventDefault();
        if (!inputText.trim() || !user) return;
        firebaseAuth.sendMessage(inputText, user);
        setInputText('');
    };

    return (
        <div className={`fixed bottom-24 right-4 z-1100 transition-all duration-300 ${isOpen ? 'w-80 h-96' : 'w-auto h-auto'}`}>
            {!isOpen && (
                <button
                    onClick={() => setIsOpen(true)}
                    className="glass-morphism p-3 rounded-full hover:bg-primary/20 transition-all flex items-center gap-2"
                >
                    <Icon name="MessageSquare" size={20} />
                    <span className="text-xs font-bold bg-error text-white rounded-full px-1.5 absolute -top-1 -right-1">LIVE</span>
                </button>
            )}

            {isOpen && (
                <div className="glass-morphism rounded-xl w-full h-full flex flex-col border border-white/10 shadow-2xl bg-background/90 text-left overflow-hidden">
                    {/* Header */}
                    <div className="p-3 border-b border-white/10 flex justify-between items-center bg-black/20">
                        <div className="flex items-center gap-2">
                            <Icon name="Globe" size={14} className="text-primary" />
                            <span className="font-bold text-sm">Global Link</span>
                            {user && (
                                <button
                                    onClick={toggleSubscribe}
                                    title={user.isSubscribedToNewsletter ? "Subscribed to Updates" : "Subscribe to Updates"}
                                    className={`w-2 h-2 rounded-full animate-pulse ${user.isSubscribedToNewsletter ? 'bg-success' : 'bg-text-tertiary'}`}
                                />
                            )}
                        </div>
                        <button onClick={() => setIsOpen(false)}><Icon name="Minimize2" size={14} /></button>
                    </div>

                    {/* Messages */}
                    <div className="flex-1 overflow-y-auto p-3 space-y-2">
                        {messages.length === 0 && (
                            <div className="text-center text-xs text-text-tertiary mt-10">Channel is quiet...</div>
                        )}
                        {messages.map(msg => (
                            <div key={msg.id} className="text-xs">
                                <span className={`font-bold ${msg.goldName ? 'text-[#FFD700] drop-shadow-[0_0_2px_#FFD700]' : 'text-primary'}`}>
                                    {msg.displayName}
                                    {msg.goldName && <Icon name="Star" size={10} className="inline ml-0.5 mb-0.5" />}:
                                </span>
                                <span className={`ml-1 break-words ${msg.goldName ? 'text-[#FFFACD]' : 'text-text-secondary'}`}>{msg.text}</span>
                            </div>
                        ))}
                        <div ref={bottomRef} />
                    </div>

                    {/* Input */}
                    <div className="p-3 border-t border-white/10 bg-black/20">
                        {user ? (
                            <form onSubmit={sendMessage} className="flex gap-2">
                                <input
                                    className="flex-1 bg-black/40 border-none rounded px-2 py-1 text-xs outline-none focus:ring-1 ring-primary"
                                    placeholder="Broadcast message..."
                                    value={inputText}
                                    onChange={e => setInputText(e.target.value)}
                                />
                                <button type="submit" disabled={!inputText.trim()} className="text-primary disabled:opacity-50">
                                    <Icon name="Send" size={14} />
                                </button>
                            </form>
                        ) : (
                            <div className="text-center text-xs text-text-tertiary">
                                Login to transmit data.
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default CommunityChat;
