import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const CommandInput = ({ onCommand }) => {
    const [input, setInput] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!input.trim()) return;

        onCommand(input.trim());
        setInput('');
    };

    return (
        <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 z-1100 w-full max-w-lg">
            <form onSubmit={handleSubmit} className="relative group">
                <div className="absolute inset-0 bg-gradient-to-r from-primary/30 to-accent/30 rounded-full blur-md opacity-20 group-hover:opacity-40 transition-opacity" />
                <div className="relative flex items-center bg-surface/80 backdrop-blur-md border border-white/10 rounded-full pr-2 pl-6 py-2 shadow-2xl focus-within:border-primary/50 transition-all">
                    <Icon name="Terminal" size={18} className="text-primary mr-3" />
                    <input
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        placeholder="Command the Soul (e.g., 'build a cozy library', 'dance')"
                        className="flex-1 bg-transparent border-none outline-none text-text-primary placeholder-text-tertiary text-sm"
                    />
                    <button
                        type="submit"
                        className="p-2 bg-primary/20 hover:bg-primary/40 text-primary rounded-full transition-colors ml-2"
                    >
                        <Icon name="Send" size={16} />
                    </button>
                </div>
            </form>
        </div>
    );
};

export default CommandInput;
