import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const SystemMonitoring = () => {
  const [systemHealth, setSystemHealth] = useState({
    database: 'healthy',
    api: 'healthy',
    queue: 'healthy',
    payments: 'healthy'
  });

  const [realTimeStats, setRealTimeStats] = useState({
    commandsProcessed: 1247,
    activeConnections: 247,
    memoryUsage: 68.5,
    cpuUsage: 42.3
  });

  useEffect(() => {
    // Mock real-time updates
    const interval = setInterval(() => {
      setRealTimeStats(prev => ({
        commandsProcessed: prev.commandsProcessed + Math.floor(Math.random() * 3),
        activeConnections: prev.activeConnections + Math.floor(Math.random() * 5) - 2,
        memoryUsage: Math.max(50, Math.min(90, prev.memoryUsage + (Math.random() - 0.5) * 2)),
        cpuUsage: Math.max(20, Math.min(80, prev.cpuUsage + (Math.random() - 0.5) * 5))
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  const getHealthColor = (status) => {
    switch (status) {
      case 'healthy':
        return 'text-success bg-success/10 border-success/20';
      case 'warning':
        return 'text-warning bg-warning/10 border-warning/20';
      case 'error':
        return 'text-error bg-error/10 border-error/20';
      default:
        return 'text-text-secondary bg-surface/20 border-white/10';
    }
  };

  const getHealthIcon = (status) => {
    switch (status) {
      case 'healthy':
        return 'CheckCircle';
      case 'warning':
        return 'AlertTriangle';
      case 'error':
        return 'XCircle';
      default:
        return 'Circle';
    }
  };

  const getUsageColor = (percentage) => {
    if (percentage > 80) return 'text-error';
    if (percentage > 60) return 'text-warning';
    return 'text-success';
  };

  const getUsageBarColor = (percentage) => {
    if (percentage > 80) return 'bg-error';
    if (percentage > 60) return 'bg-warning';
    return 'bg-success';
  };

  const healthItems = [
    { key: 'database', label: 'Database', icon: 'Database' },
    { key: 'api', label: 'Gemini API', icon: 'Zap' },
    { key: 'queue', label: 'Command Queue', icon: 'List' },
    { key: 'payments', label: 'PayPal', icon: 'CreditCard' }
  ];

  return (
    <div className="glass-morphism rounded-xl p-6 border border-white/20">
      <h3 className="text-lg font-heading font-semibold text-text-primary mb-6">
        System Monitoring
      </h3>

      <div className="space-y-6">
        {/* System Health */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">System Health</h4>
          <div className="space-y-2">
            {healthItems.map((item) => (
              <div key={item.key} className="flex items-center justify-between p-3 bg-surface/20 rounded-lg border border-white/10">
                <div className="flex items-center space-x-2">
                  <Icon name={item.icon} size={16} className="text-text-secondary" />
                  <span className="text-sm text-text-primary">{item.label}</span>
                </div>
                <div className="flex items-center space-x-2">
                  <Icon name={getHealthIcon(systemHealth[item.key])} size={14} className={getHealthColor(systemHealth[item.key]).split(' ')[0]} />
                  <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getHealthColor(systemHealth[item.key])}`}>
                    {systemHealth[item.key]}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Real-time Statistics */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">Real-time Statistics</h4>
          <div className="space-y-3">
            <div className="p-3 bg-surface/20 rounded-lg border border-white/10">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-text-primary">Commands Processed</span>
                <span className="text-sm font-bold text-primary">{realTimeStats.commandsProcessed.toLocaleString()}</span>
              </div>
              <div className="flex items-center space-x-2 text-xs text-text-secondary">
                <Icon name="TrendingUp" size={12} />
                <span>+{Math.floor(Math.random() * 10) + 5} in last minute</span>
              </div>
            </div>

            <div className="p-3 bg-surface/20 rounded-lg border border-white/10">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-text-primary">Active Connections</span>
                <span className="text-sm font-bold text-success">{realTimeStats.activeConnections}</span>
              </div>
              <div className="flex items-center space-x-2 text-xs text-text-secondary">
                <div className="w-2 h-2 bg-success rounded-full animate-pulse" />
                <span>Live connections</span>
              </div>
            </div>

            <div className="p-3 bg-surface/20 rounded-lg border border-white/10">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-text-primary">Memory Usage</span>
                <span className={`text-sm font-bold ${getUsageColor(realTimeStats.memoryUsage)}`}>
                  {realTimeStats.memoryUsage.toFixed(1)}%
                </span>
              </div>
              <div className="w-full bg-surface rounded-full h-1.5">
                <div 
                  className={`h-1.5 rounded-full transition-all duration-300 ${getUsageBarColor(realTimeStats.memoryUsage)}`}
                  style={{ width: `${realTimeStats.memoryUsage}%` }}
                />
              </div>
            </div>

            <div className="p-3 bg-surface/20 rounded-lg border border-white/10">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-text-primary">CPU Usage</span>
                <span className={`text-sm font-bold ${getUsageColor(realTimeStats.cpuUsage)}`}>
                  {realTimeStats.cpuUsage.toFixed(1)}%
                </span>
              </div>
              <div className="w-full bg-surface rounded-full h-1.5">
                <div 
                  className={`h-1.5 rounded-full transition-all duration-300 ${getUsageBarColor(realTimeStats.cpuUsage)}`}
                  style={{ width: `${realTimeStats.cpuUsage}%` }}
                />
              </div>
            </div>
          </div>
        </div>

        {/* System Actions */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">System Actions</h4>
          <div className="space-y-2">
            <button className="w-full flex items-center justify-center space-x-2 px-3 py-2 bg-primary/20 hover:bg-primary/30 text-primary border border-primary/30 rounded-lg transition-smooth">
              <Icon name="RefreshCw" size={14} />
              <span className="text-sm">Refresh Stats</span>
            </button>
            <button className="w-full flex items-center justify-center space-x-2 px-3 py-2 bg-surface/50 hover:bg-surface/70 text-text-secondary hover:text-text-primary border border-white/10 rounded-lg transition-smooth">
              <Icon name="Download" size={14} />
              <span className="text-sm">Export Logs</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SystemMonitoring;