import React, { useState, useEffect, useRef } from 'react';

import Icon from 'components/AppIcon';
import Image from 'components/AppImage';

const LiveChat = () => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [activeUsers, setActiveUsers] = useState([]);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [mentionSuggestions, setMentionSuggestions] = useState([]);
  const [showMentions, setShowMentions] = useState(false);
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  const mockMessages = [
    {
      id: 1,
      user: 'CyberNinja',
      avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop&crop=face',
      message: 'Just executed a sick parkour sequence! 🔥',
      timestamp: new Date(Date.now() - 300000),
      type: 'message',
      reactions: [{ emoji: '🔥', count: 3, users: ['NeonDreamer', 'UrbanExplorer', 'You'] }]
    },
    {
      id: 2,
      user: 'NeonDreamer',
      avatar: 'https://images.unsplash.com/photo-1494790108755-2616b612b786?w=100&h=100&fit=crop&crop=face',
      message: '/command make Soul dance to lo-fi beats',
      timestamp: new Date(Date.now() - 240000),
      type: 'command',
      status: 'executed'
    },
    {
      id: 3,
      user: 'UrbanExplorer',
      avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop&crop=face',
      message: 'The new holographic effects are incredible! How did you guys implement the particle system?',
      timestamp: new Date(Date.now() - 180000),
      type: 'message'
    },
    {
      id: 4,
      user: 'System',
      avatar: null,
      message: 'Soul completed the coffee brewing sequence. +5 experience points!',
      timestamp: new Date(Date.now() - 120000),
      type: 'system'
    },
    {
      id: 5,
      user: 'GlitchArtist',
      avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop&crop=face',
      message: '@CyberNinja that was amazing! Can you share the command sequence?',
      timestamp: new Date(Date.now() - 60000),
      type: 'message',
      mentions: ['CyberNinja']
    }
  ];

  const mockActiveUsers = [
    { id: 1, username: 'CyberNinja', avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop&crop=face', status: 'commanding' },
    { id: 2, username: 'NeonDreamer', avatar: 'https://images.unsplash.com/photo-1494790108755-2616b612b786?w=100&h=100&fit=crop&crop=face', status: 'watching' },
    { id: 3, username: 'UrbanExplorer', avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop&crop=face', status: 'building' },
    { id: 4, username: 'GlitchArtist', avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop&crop=face', status: 'online' },
    { id: 5, username: 'SoulSeeker', avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop&crop=face', status: 'online' }
  ];

  const emojis = ['😀', '😂', '🔥', '💯', '🚀', '⚡', '🌟', '💎', '🎯', '🎨', '🎵', '🎮'];

  useEffect(() => {
    setMessages(mockMessages);
    setActiveUsers(mockActiveUsers);
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    // Check for mentions in message
    const words = message.split(' ');
    const lastWord = words[words.length - 1];
    
    if (lastWord.startsWith('@') && lastWord.length > 1) {
      const query = lastWord.slice(1).toLowerCase();
      const suggestions = mockActiveUsers.filter(user => 
        user.username.toLowerCase().includes(query)
      );
      setMentionSuggestions(suggestions);
      setShowMentions(suggestions.length > 0);
    } else {
      setShowMentions(false);
    }
  }, [message]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (message.trim()) {
      const newMessage = {
        id: Date.now(),
        user: 'You',
        avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop&crop=face',
        message: message.trim(),
        timestamp: new Date(),
        type: message.startsWith('/') ? 'command' : 'message',
        status: message.startsWith('/') ? 'pending' : undefined
      };
      
      setMessages(prev => [...prev, newMessage]);
      setMessage('');
      setShowEmojiPicker(false);
    }
  };

  const handleEmojiClick = (emoji) => {
    setMessage(prev => prev + emoji);
    setShowEmojiPicker(false);
    inputRef.current?.focus();
  };

  const handleMentionClick = (user) => {
    const words = message.split(' ');
    words[words.length - 1] = `@${user.username} `;
    setMessage(words.join(' '));
    setShowMentions(false);
    inputRef.current?.focus();
  };

  const handleReaction = (messageId, emoji) => {
    setMessages(prev => prev.map(msg => {
      if (msg.id === messageId) {
        const reactions = msg.reactions || [];
        const existingReaction = reactions.find(r => r.emoji === emoji);
        
        if (existingReaction) {
          if (existingReaction.users.includes('You')) {
            // Remove reaction
            existingReaction.count--;
            existingReaction.users = existingReaction.users.filter(u => u !== 'You');
            if (existingReaction.count === 0) {
              return { ...msg, reactions: reactions.filter(r => r.emoji !== emoji) };
            }
          } else {
            // Add reaction
            existingReaction.count++;
            existingReaction.users.push('You');
          }
        } else {
          // New reaction
          reactions.push({ emoji, count: 1, users: ['You'] });
        }
        
        return { ...msg, reactions };
      }
      return msg;
    }));
  };

  const shareCommand = (command) => {
    setMessage(command);
    inputRef.current?.focus();
  };

  const formatTimestamp = (timestamp) => {
    return timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'commanding': return 'text-primary';
      case 'building': return 'text-warning';
      case 'watching': return 'text-success';
      default: return 'text-text-tertiary';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'commanding': return 'Zap';
      case 'building': return 'Hammer';
      case 'watching': return 'Eye';
      default: return 'Circle';
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 h-[calc(100vh-280px)]">
      {/* Active Users Sidebar */}
      <div className="lg:col-span-1 order-2 lg:order-1">
        <div className="glass-morphism rounded-lg p-4 h-full">
          <h3 className="font-heading font-semibold text-text-primary mb-4 flex items-center">
            <Icon name="Users" size={18} className="mr-2" />
            Active Users ({activeUsers.length})
          </h3>
          
          <div className="space-y-3 overflow-y-auto max-h-96">
            {activeUsers.map((user) => (
              <div key={user.id} className="flex items-center space-x-3 p-2 rounded-lg hover:bg-white/5 transition-smooth">
                <div className="relative">
                  <Image
                    src={user.avatar}
                    alt={user.username}
                    className="w-8 h-8 rounded-full object-cover"
                  />
                  <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-success rounded-full border-2 border-surface" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-text-primary truncate">{user.username}</p>
                  <div className="flex items-center space-x-1">
                    <Icon name={getStatusIcon(user.status)} size={12} className={getStatusColor(user.status)} />
                    <span className={`text-xs ${getStatusColor(user.status)}`}>{user.status}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Quick Actions */}
          <div className="mt-4 pt-4 border-t border-white/10">
            <h4 className="text-sm font-medium text-text-primary mb-2">Quick Actions</h4>
            <div className="space-y-2">
              <button
                onClick={() => shareCommand('/command wave hello')}
                className="w-full text-left text-xs text-text-secondary hover:text-primary hover:bg-primary/10 p-2 rounded transition-smooth"
              >
                👋 Wave Hello
              </button>
              <button
                onClick={() => shareCommand('/command dance party')}
                className="w-full text-left text-xs text-text-secondary hover:text-primary hover:bg-primary/10 p-2 rounded transition-smooth"
              >
                💃 Start Dance Party
              </button>
              <button
                onClick={() => shareCommand('/command explore rooftop')}
                className="w-full text-left text-xs text-text-secondary hover:text-primary hover:bg-primary/10 p-2 rounded transition-smooth"
              >
                🏢 Explore Rooftop
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Chat Messages */}
      <div className="lg:col-span-3 order-1 lg:order-2 flex flex-col">
        <div className="glass-morphism rounded-lg flex-1 flex flex-col">
          {/* Messages Container */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex space-x-3 ${msg.user === 'You' ? 'flex-row-reverse space-x-reverse' : ''}`}>
                {msg.avatar && (
                  <Image
                    src={msg.avatar}
                    alt={msg.user}
                    className="w-8 h-8 rounded-full object-cover flex-shrink-0"
                  />
                )}
                {msg.type === 'system' && (
                  <div className="w-8 h-8 bg-primary/20 rounded-full flex items-center justify-center flex-shrink-0">
                    <Icon name="Bot" size={16} className="text-primary" />
                  </div>
                )}
                
                <div className={`flex-1 ${msg.user === 'You' ? 'text-right' : ''}`}>
                  <div className="flex items-center space-x-2 mb-1">
                    <span className="text-sm font-medium text-text-primary">{msg.user}</span>
                    <span className="text-xs text-text-tertiary">{formatTimestamp(msg.timestamp)}</span>
                    {msg.type === 'command' && (
                      <span className={`text-xs px-2 py-0.5 rounded-full ${
                        msg.status === 'executed' ? 'bg-success/20 text-success' :
                        msg.status === 'pending'? 'bg-warning/20 text-warning' : 'bg-error/20 text-error'
                      }`}>
                        {msg.status || 'queued'}
                      </span>
                    )}
                  </div>
                  
                  <div className={`inline-block p-3 rounded-lg max-w-xs sm:max-w-md ${
                    msg.user === 'You' ?'bg-primary text-white' 
                      : msg.type === 'system' ?'bg-surface/50 text-text-secondary'
                      : msg.type === 'command' ?'bg-warning/10 border border-warning/20 text-text-primary font-mono' :'bg-surface text-text-primary'
                  }`}>
                    <p className="text-sm break-words">{msg.message}</p>
                    
                    {/* Reactions */}
                    {msg.reactions && msg.reactions.length > 0 && (
                      <div className="flex flex-wrap gap-1 mt-2">
                        {msg.reactions.map((reaction, index) => (
                          <button
                            key={index}
                            onClick={() => handleReaction(msg.id, reaction.emoji)}
                            className={`flex items-center space-x-1 px-2 py-1 rounded-full text-xs transition-smooth ${
                              reaction.users.includes('You')
                                ? 'bg-primary/20 text-primary border border-primary/30' :'bg-white/5 text-text-secondary hover:bg-white/10'
                            }`}
                          >
                            <span>{reaction.emoji}</span>
                            <span>{reaction.count}</span>
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                  
                  {/* Quick Reaction Bar */}
                  {msg.user !== 'You' && msg.type !== 'system' && (
                    <div className="flex space-x-1 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      {['👍', '❤️', '😂', '🔥'].map((emoji) => (
                        <button
                          key={emoji}
                          onClick={() => handleReaction(msg.id, emoji)}
                          className="text-xs hover:scale-110 transition-transform"
                        >
                          {emoji}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>

          {/* Message Input */}
          <div className="border-t border-white/10 p-4">
            <form onSubmit={handleSendMessage} className="relative">
              {/* Mention Suggestions */}
              {showMentions && (
                <div className="absolute bottom-full left-0 right-0 mb-2 glass-morphism rounded-lg border border-white/10 animate-slide-up">
                  {mentionSuggestions.map((user) => (
                    <button
                      key={user.id}
                      type="button"
                      onClick={() => handleMentionClick(user)}
                      className="w-full flex items-center space-x-2 p-2 text-left hover:bg-white/5 transition-smooth first:rounded-t-lg last:rounded-b-lg"
                    >
                      <Image src={user.avatar} alt={user.username} className="w-6 h-6 rounded-full object-cover" />
                      <span className="text-sm text-text-primary">{user.username}</span>
                    </button>
                  ))}
                </div>
              )}

              {/* Emoji Picker */}
              {showEmojiPicker && (
                <div className="absolute bottom-full right-0 mb-2 glass-morphism rounded-lg p-3 animate-slide-up">
                  <div className="grid grid-cols-6 gap-2">
                    {emojis.map((emoji) => (
                      <button
                        key={emoji}
                        type="button"
                        onClick={() => handleEmojiClick(emoji)}
                        className="text-lg hover:scale-110 transition-transform p-1 rounded hover:bg-white/10"
                      >
                        {emoji}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <div className="flex items-center space-x-2">
                <div className="flex-1 relative">
                  <input
                    ref={inputRef}
                    type="text"
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="Type a message or /command..."
                    className="w-full bg-surface/50 border border-white/10 rounded-lg px-4 py-3 pr-12 text-text-primary placeholder-text-tertiary focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-smooth"
                  />
                  <button
                    type="button"
                    onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-text-tertiary hover:text-text-primary transition-smooth"
                  >
                    <Icon name="Smile" size={18} />
                  </button>
                </div>
                
                <button
                  type="submit"
                  disabled={!message.trim()}
                  className="bg-primary hover:bg-primary-600 disabled:bg-surface disabled:text-text-tertiary text-white p-3 rounded-lg transition-smooth neon-glow disabled:shadow-none"
                >
                  <Icon name="Send" size={18} />
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LiveChat;