import * as THREE from 'three';
import TWEEN from '@tweenjs/tween.js';

export class WeatherSystem {
    constructor(scene) {
        this.scene = scene;
        this.isEnabled = false;
        this.rainSystem = null;
        this.rainGeo = null;
        this.flashLight = new THREE.PointLight(0x00ffff, 0, 500, 2); // Lightning color
        this.flashLight.position.set(0, 50, 0);
        this.scene.add(this.flashLight);

        this.dropCount = 15000;
        this.rainVelocity = [];
    }

    enableRain() {
        if (this.isEnabled) return;
        this.isEnabled = true;

        // 1. Create Rain Geometry
        this.rainGeo = new THREE.BufferGeometry();
        const positions = [];

        for (let i = 0; i < this.dropCount; i++) {
            // Random pos
            positions.push(
                Math.random() * 400 - 200, // X
                Math.random() * 200,       // Y
                Math.random() * 400 - 200  // Z
            );
            // Random velocity
            this.rainVelocity.push(Math.random() * 0.5 + 1.5); // Fast falling
        }

        this.rainGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));

        // 2. Material (Streaks)
        const rainMat = new THREE.PointsMaterial({
            color: 0xaaaaaa,
            size: 0.2,
            transparent: true,
            opacity: 0.6,
            blending: THREE.AdditiveBlending
        });

        this.rainSystem = new THREE.Points(this.rainGeo, rainMat);
        this.scene.add(this.rainSystem);

        // 3. Atmosphere (Fog)
        // Tween in the fog
        const startFog = { density: 0 };
        new TWEEN.Tween(startFog)
            .to({ density: 0.02 }, 2000)
            .onUpdate(() => {
                this.scene.fog = new THREE.FogExp2(0x11111f, startFog.density);
            })
            .start();
    }

    disableRain() {
        if (!this.isEnabled) return;
        this.isEnabled = false;

        if (this.rainSystem) {
            this.scene.remove(this.rainSystem);
            this.rainGeo.dispose();
            this.rainSystem = null;
        }
        this.scene.fog = new THREE.FogExp2(0x000000, 0.002); // Reset to clear
    }

    update() {
        if (!this.isEnabled || !this.rainSystem) return;

        const positions = this.rainGeo.attributes.position.array;

        // Animate Drops
        for (let i = 1; i < this.dropCount * 3; i += 3) {
            // Subtract Y
            positions[i] -= this.rainVelocity[Math.floor(i / 3)];

            // Reset if hit ground
            if (positions[i] < -10) {
                positions[i] = 200; // Reset height
                positions[i - 1] = Math.random() * 400 - 200; // New X
                positions[i + 1] = Math.random() * 400 - 200; // New Z
            }
        }

        this.rainGeo.attributes.position.needsUpdate = true;

        // Lightning Logic (Random Flash)
        if (Math.random() > 0.995) {
            this.triggerLightning();
        }
    }

    triggerLightning() {
        this.flashLight.intensity = 5;
        this.flashLight.position.set(
            Math.random() * 100 - 50,
            100,
            Math.random() * 100 - 50
        );

        // Instant flash, slow fade
        new TWEEN.Tween(this.flashLight)
            .to({ intensity: 0 }, 150)
            .easing(TWEEN.Easing.Bounce.Out)
            .start();
    }
}
