import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const QuickActions = () => {
  const [announcement, setAnnouncement] = useState('');
  const [soulBehavior, setSoulBehavior] = useState('default');
  const [showConfirmClear, setShowConfirmClear] = useState(false);

  const behaviorOptions = [
    { value: 'default', label: 'Default Behavior', description: 'Normal AI responses and actions' },
    { value: 'energetic', label: 'Energetic Mode', description: 'More animated and expressive' },
    { value: 'calm', label: 'Calm Mode', description: 'Slower, more thoughtful responses' },
    { value: 'creative', label: 'Creative Mode', description: 'Focus on artistic activities' },
    { value: 'maintenance', label: 'Maintenance Mode', description: 'Limited functionality for updates' }
  ];

  const handleEmergencyClear = () => {
    if (showConfirmClear) {
      console.log('Emergency queue clear executed');
      setShowConfirmClear(false);
      // Mock queue clear
    } else {
      setShowConfirmClear(true);
      setTimeout(() => setShowConfirmClear(false), 5000);
    }
  };

  const handleAnnouncement = () => {
    if (announcement.trim()) {
      console.log('Broadcasting announcement:', announcement);
      setAnnouncement('');
      // Mock announcement broadcast
    }
  };

  const handleBehaviorChange = (behavior) => {
    setSoulBehavior(behavior);
    console.log('Soul behavior changed to:', behavior);
    // Mock behavior change
  };

  return (
    <div className="glass-morphism rounded-xl p-6 border border-white/20">
      <h3 className="text-lg font-heading font-semibold text-text-primary mb-6">
        Quick Actions
      </h3>

      <div className="space-y-6">
        {/* Emergency Queue Clear */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">Emergency Controls</h4>
          <button
            onClick={handleEmergencyClear}
            className={`w-full flex items-center justify-center space-x-2 px-4 py-3 font-medium rounded-lg transition-smooth ${
              showConfirmClear
                ? 'bg-error hover:bg-error-600 text-white animate-pulse' :'bg-error/20 hover:bg-error/30 text-error border border-error/30'
            }`}
          >
            <Icon name="AlertTriangle" size={18} />
            <span>{showConfirmClear ? 'Click Again to Confirm' : 'Emergency Queue Clear'}</span>
          </button>
          <p className="text-xs text-text-tertiary mt-2">
            Immediately clears all pending commands and resets the queue
          </p>
        </div>

        {/* System Announcement */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">System Announcement</h4>
          <div className="space-y-3">
            <textarea
              value={announcement}
              onChange={(e) => setAnnouncement(e.target.value)}
              placeholder="Enter announcement message..."
              className="w-full bg-surface/50 border border-white/10 rounded-lg px-3 py-2 text-text-primary placeholder-text-tertiary focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-smooth resize-none"
              rows={3}
            />
            <button
              onClick={handleAnnouncement}
              disabled={!announcement.trim()}
              className="w-full flex items-center justify-center space-x-2 px-4 py-2 bg-primary hover:bg-primary-600 disabled:bg-surface disabled:text-text-tertiary text-white font-medium rounded-lg transition-smooth"
            >
              <Icon name="Megaphone" size={16} />
              <span>Broadcast to All Users</span>
            </button>
          </div>
        </div>

        {/* Soul Behavior Override */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">Soul Behavior Override</h4>
          <div className="space-y-2">
            {behaviorOptions.map((option) => (
              <button
                key={option.value}
                onClick={() => handleBehaviorChange(option.value)}
                className={`w-full text-left p-3 rounded-lg border transition-smooth ${
                  soulBehavior === option.value
                    ? 'bg-primary/20 border-primary/30 text-primary' :'bg-surface/20 border-white/10 text-text-secondary hover:text-text-primary hover:bg-white/5'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="font-medium">{option.label}</p>
                    <p className="text-xs opacity-75">{option.description}</p>
                  </div>
                  {soulBehavior === option.value && (
                    <Icon name="Check" size={16} />
                  )}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Quick Stats */}
        <div>
          <h4 className="text-sm font-medium text-text-primary mb-3">Quick Stats</h4>
          <div className="grid grid-cols-2 gap-3">
            <div className="p-3 bg-surface/20 rounded-lg border border-white/10 text-center">
              <p className="text-lg font-bold text-primary">12</p>
              <p className="text-xs text-text-secondary">Queue Length</p>
            </div>
            <div className="p-3 bg-surface/20 rounded-lg border border-white/10 text-center">
              <p className="text-lg font-bold text-success">247</p>
              <p className="text-xs text-text-secondary">Active Users</p>
            </div>
            <div className="p-3 bg-surface/20 rounded-lg border border-white/10 text-center">
              <p className="text-lg font-bold text-warning">98.5%</p>
              <p className="text-xs text-text-secondary">Uptime</p>
            </div>
            <div className="p-3 bg-surface/20 rounded-lg border border-white/10 text-center">
              <p className="text-lg font-bold text-accent">1.2s</p>
              <p className="text-xs text-text-secondary">Avg Response</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QuickActions;