import React, { useState, useEffect, useRef, useCallback, memo } from 'react';
import Icon from 'components/AppIcon';
import WebGLViewport from './components/WebGLViewport';
import CameraPerspectiveToggle from './components/CameraPerspectiveToggle';
import AudioControls from './components/AudioControls';
import CommandQueue from './components/CommandQueue';
import AuthOverlay from '../../components/AuthOverlay';
import CommunityChat from '../../components/CommunityChat';
import { useCommandContext } from 'contexts/CommandContext';
import {
  saveWorldState,
  loadWorldState,
  saveCharacterState,
  loadCharacterState,
  saveCommandToHistory,
  getCommandHistory,
  saveCommandQueue,
  loadCommandQueue
} from '../../services/firebase';
import geminiAI from '../../services/geminiAI';

import CommandInput from './components/CommandInput';

const Main3DWorldInterface = memo(() => {
  const { registerCommandExecutor } = useCommandContext();
  const [cameraMode, setCameraMode] = useState('third-person');
  const [isAudioEnabled, setIsAudioEnabled] = useState(true);
  const [ambientVolume, setAmbientVolume] = useState(0.7);
  const [musicVolume, setMusicVolume] = useState(0.5);
  const [showCommandQueue, setShowCommandQueue] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [commandQueue, setCommandQueue] = useState([]);

  // New: Autonomous Mode State (Persistent)
  const [isAutonomous, setIsAutonomous] = useState(() => {
    return localStorage.getItem('soul_autonomous') === 'true';
  });

  useEffect(() => {
    localStorage.setItem('soul_autonomous', isAutonomous);
  }, [isAutonomous]);
  const [nextActionTimer, setNextActionTimer] = useState(null);

  const [worldState, setWorldState] = useState({
    timeOfDay: 'day',
    weather: 'clear',
    soulPosition: { x: 0, y: 0, z: 0 },
    soulActivity: 'idle'
  });
  const [aiThoughts, setAiThoughts] = useState('');

  const viewportRef = useRef(null);

  // Helper to execute a command (used by both UI and Autonomous mode)
  const executeCommandRaw = useCallback(async (commandObject) => {
    const { command, thought } = commandObject;
    await handleCommandExecution(command, thought);
  }, []); // will depend on handleCommandExecution which we define next


  const [currentProduct, setCurrentProduct] = useState(null);

  const handleCommandExecution = useCallback(async (command, explicitThought = null) => {
    // 0. Intercept Recommendation commands
    if (['suggest', 'recommend', 'resources', 'picks'].some(k => command.toLowerCase().includes(k))) {
      setAiThoughts("Accessing global database for recommendations...");
      try {
        // Extract topic if any (e.g. "recommend books")
        let topic = null;
        if (command.includes('book')) topic = 'book';
        if (command.includes('ai') || command.includes('tool')) topic = 'ai';
        if (command.includes('light') || command.includes('tech')) topic = 'tech';

        // Lazy method to allow UI update before async
        setTimeout(async () => {
          const recommendation = await geminiAI.recommendResource(topic);

          if (recommendation) {
            setAiThoughts(recommendation.thought);
            setCurrentProduct(recommendation.product);
            // Auto-hide product after 15 seconds
            setTimeout(() => setCurrentProduct(null), 15000);
          }
        }, 100);
      } catch (e) {
        console.error(e);
        setAiThoughts("My connection to the archives is fuzzy right now.");
      }
      return;
    }

    // 1. Intercept "Build" commands
    if (command.toLowerCase().startsWith('build')) {
      const description = command.substring(5).trim();
      const feedback = `Architecting: "${description}"...`;
      setAiThoughts(feedback);

      try {
        const roomData = await geminiAI.generateRoom(description);
        if (roomData && viewportRef.current) {
          // Translate generic room data to custom object(s)
          // For now, we'll create a "Custom Object" that represents the room feature
          // In a full implementation, this would procedurally generate walls/furniture

          // Example: placing a generated object at a randomish location near soul
          const offset = { x: (Math.random() - 0.5) * 5, z: (Math.random() - 0.5) * 5 };

          if (roomData.objects && roomData.objects.length > 0) {
            // Create first suggested object
            const obj = roomData.objects[0];
            viewportRef.current.createCustomObject({
              type: 'cube', // Simplified
              position: {
                x: worldState.soulPosition.x + offset.x,
                y: 1,
                z: worldState.soulPosition.z + offset.z
              },
              color: 0xaa00aa, // purple generic placeholder
              size: { x: 1, y: 1, z: 1 },
              name: obj.name
            });
            setAiThoughts(`Created ${obj.name} in response to request.`);
          } else {
            // Fallback object
            viewportRef.current.createCustomObject({
              type: 'cube',
              position: {
                x: worldState.soulPosition.x + 2,
                y: 1,
                z: worldState.soulPosition.z + 2
              },
              color: 0x00ff00,
              size: { x: 2, y: 2, z: 2 },
              name: roomData.name || "New Structure"
            });
            setAiThoughts(`Constructed ${roomData.name || "new structure"}.`);
          }
        }
      } catch (e) {
        console.error("Build failed:", e);
        setAiThoughts("I couldn't quite visualize that structure.");
      }
      return; // Stop standard execution
    }

    if (viewportRef.current && viewportRef.current.executeCommand) {
      viewportRef.current.executeCommand(command);

      // Update world state activity
      const activityMap = {
        'move forward': 'Moving forward through the apartment',
        'move backward': 'Moving backward',
        'turn left': 'Turning to look around',
        'turn right': 'Turning to look around',
        'dance': 'Dancing with joy in the apartment',
        'look around': 'Looking around the high-tech apartment',
        'wave hand': 'Waving at someone through the window',
        'make coffee': 'Making coffee at the kitchen island',
        'sit down': 'Sitting and relaxing by the coffee table',
        'stand up': 'Standing up and ready to move'
      };

      const newActivity = activityMap[command] || `Responding to: "${command}"`;
      const newWorldState = {
        ...worldState,
        soulActivity: newActivity
      };

      setWorldState(newWorldState);

      // Add command to queue and save to Firebase
      const newCommand = {
        id: Date.now(),
        command,
        status: 'executing',
        timestamp: Date.now()
      };
      const updatedQueue = [...commandQueue, newCommand];
      setCommandQueue(updatedQueue);

      // Save command queue to Firebase
      try {
        await saveCommandQueue(updatedQueue);
      } catch (error) {
        console.error('Failed to save command queue to Firebase:', error);
      }

      // Save command to Firebase history
      try {
        await saveCommandToHistory(command, {
          success: true,
          activity: newActivity,
          timestamp: Date.now()
        });
      } catch (error) {
        console.error('Failed to save command to Firebase history:', error);
      }

      // Save character state to Firebase
      const characterState = {
        lastCommand: command,
        currentActivity: newActivity,
        position: worldState.soulPosition,
        timestamp: Date.now()
      };

      try {
        await saveCharacterState(characterState);
      } catch (error) {
        console.error('Failed to save character state to Firebase:', error);
      }

      // Generate AI response or use explicit thought
      if (explicitThought) {
        setAiThoughts(explicitThought);
        worldData.soul.lastAction = `${command} - ${explicitThought}`;
      } else {
        try {
          const aiResponse = await geminiAI.generateEmotionalResponse(
            command,
            newWorldState,
            characterState
          );

          setAiThoughts(aiResponse.thought);

          // Update world data with AI insights
          worldData.soul.lastAction = `${command} - ${aiResponse.thought}`;
        } catch (error) {
          console.error('AI response generation failed:', error);
        }
      }

      // Command status will be updated by onCommandAnimationComplete callback
    }
  }, [worldState, commandQueue]);

  const handleCommandAnimationComplete = useCallback(async (command) => {
    setCommandQueue(prevQueue => {
      const updatedQueue = prevQueue.map(cmd =>
        cmd.command === command && cmd.status === 'executing'
          ? { ...cmd, status: 'completed' }
          : cmd
      );
      // Optionally, remove completed commands after a delay or based on user preference
      // For now, just mark as completed
      return updatedQueue;
    });

    try {
      await saveCommandQueue(commandQueue); // Save the updated queue state
    } catch (error) {
      console.error('Failed to update command queue in Firebase after animation complete:', error);
    }
  }, [commandQueue]);

  // Mock world data
  const worldData = {
    environment: {
      skybox: 'urban_day',
      lighting: 'natural',
      weather: 'clear',
      timeOfDay: 'afternoon'
    },
    soul: {
      name: 'The Soul',
      position: { x: 0, y: 1.8, z: 0 },
      activity: 'Making coffee in the high-tech apartment',
      mood: 'contemplative',
      lastAction: 'Observing the city skyline through floor-to-ceiling windows'
    },
    apartment: {
      style: 'high-tech modern',
      floor: 47,
      view: 'panoramic city skyline',
      features: ['Smart kitchen', 'Holographic displays', 'Ambient lighting', 'Floor-to-ceiling windows']
    },
    cityscape: {
      buildings: 50,
      npcs: 20,
      vehicles: 10,
      ambientSounds: ['traffic', 'city_hum', 'wind', 'distant_music']
    }
  };

  useEffect(() => {
    // Initialize world with Firebase data loading
    const initializeWorld = async () => {
      setIsLoading(true);

      try {
        // Load saved world state from Firebase
        const savedWorldState = await loadWorldState();
        const savedCharacterState = await loadCharacterState();
        const savedCommandQueue = await loadCommandQueue();

        if (savedWorldState) {
          console.log('Loading world state from Firebase:', savedWorldState);
          setWorldState(prev => ({ ...prev, ...savedWorldState }));
        }

        if (savedCommandQueue) {
          console.log('Loading command queue from Firebase:', savedCommandQueue);
          setCommandQueue(savedCommandQueue);
        }

        // Mock loading delay for smooth UX (Constructed appropriately faster)
        await new Promise(resolve => setTimeout(resolve, 800));

        setIsLoading(false);
        console.log('World initialization complete with Firebase integration');
      } catch (error) {
        console.error('Error initializing world with Firebase:', error);
        setIsLoading(false);
      }
    };

    initializeWorld();
  }, []);

  // Save world state periodically to Firebase
  useEffect(() => {
    const saveInterval = setInterval(async () => {
      try {
        await saveWorldState(worldState);
        console.log('World state auto-saved to Firebase');
      } catch (error) {
        console.error('Failed to auto-save world state to Firebase:', error);
      }
    }, 30000); // Save every 30 seconds

    return () => clearInterval(saveInterval);
  }, [worldState]);

  // Autonomous Decision Loop
  useEffect(() => {
    let timeoutId;

    const runAutonomousLoop = async () => {
      if (!isAutonomous) return;

      try {
        // 1. Gather context
        const history = await getCommandHistory(5);
        const currentCharacterState = {
          activity: worldState.soulActivity,
          position: worldState.soulPosition,
          nearby: worldData.apartment // Simplified for now
        };

        // 2. Ask Gemini for decision
        console.log("Soul Drive: pondering next move...");
        const decision = await geminiAI.decideNextAction(worldState, history);

        // 3. Execute
        if (decision) {
          console.log("Soul Drive: decided:", decision);

          if (decision.type === 'spawn' && decision.object_details) {
            // Handle Object Spawning
            setAiThoughts(decision.thought || "Materializing thought...");
            const spawnPos = {
              x: worldState.soulPosition.x + (Math.random() * 2 - 1) * 2,
              y: 0.5,
              z: worldState.soulPosition.z + (Math.random() * 2 - 1) * 2
            };

            if (viewportRef.current) {
              viewportRef.current.executeCommand('spawn'); // Trigger animation
              setTimeout(() => {
                viewportRef.current.createCustomObject({
                  type: 'cube', // Default to cube if unknown, or map names
                  name: decision.object_details.name,
                  color: decision.object_details.color === 'red' ? 0xff0000 : 0x00ff00, // Simple mapping
                  position: spawnPos,
                  size: { x: 0.5, y: 0.5, z: 0.5 }
                });
              }, 1000);
            }
            // Also log the action
            await handleCommandExecution(`spawn ${decision.object_details.name}`, decision.thought);

          } else {
            // Standard Motion
            await handleCommandExecution(decision.command, decision.thought);
          }

          // 4. Schedule next iteration
          // Default to 5 seconds if not specified
          const delay = (decision.duration || 5) * 1000;
          timeoutId = setTimeout(runAutonomousLoop, delay);
        } else {
          // Retry sooner if failed
          timeoutId = setTimeout(runAutonomousLoop, 3000);
        }

      } catch (error) {
        console.error('Autonomous loop error:', error);
        timeoutId = setTimeout(runAutonomousLoop, 5000); // Retry after error
      }
    };

    if (isAutonomous) {
      runAutonomousLoop();
    }

    return () => {
      if (timeoutId) clearTimeout(timeoutId);
    };
  }, [isAutonomous, worldState]); // Re-run when autonomous mode toggles

  // Legacy Suggestion (Keep for Manual Mode hints if needed, or disable if autonomous is on)
  useEffect(() => {
    if (isAutonomous) return; // Don't run suggestions if autonomous

    const generateAISuggestions = async () => {
      try {
        const commandHistory = await getCommandHistory(10);
        const characterState = {
          activity: worldState.soulActivity,
          position: worldState.soulPosition
        };

        const aiSuggestions = await geminiAI.suggestCommands(worldState, characterState);

        if (aiSuggestions.suggestion) {
          setAiThoughts(aiSuggestions.suggestion);
        }
      } catch (error) {
        console.error('Failed to generate AI suggestions:', error);
      }
    };

    const aiInterval = setInterval(generateAISuggestions, 45000);
    // setTimeout(generateAISuggestions, 5000); // Remove initial call to avoid double firing on load

    return () => clearInterval(aiInterval);
  }, [worldState, isAutonomous]);

  useEffect(() => {
    // Register command executor after component mounts
    if (registerCommandExecutor) {
      registerCommandExecutor(handleCommandExecution);
    }
  }, [registerCommandExecutor, handleCommandExecution]);

  useEffect(() => {
    // Update world state based on time
    const updateWorldState = () => {
      const hour = new Date().getHours();
      const newTimeOfDay = hour >= 6 && hour < 18 ? 'day' : 'night';

      setWorldState(prev => ({
        ...prev,
        timeOfDay: newTimeOfDay
      }));
    };

    updateWorldState();
    const interval = setInterval(updateWorldState, 60000); // Update every minute

    return () => clearInterval(interval);
  }, []);

  const handleCameraChange = (mode) => {
    setCameraMode(mode);
    // Trigger camera transition in WebGL viewport
    if (viewportRef.current) {
      viewportRef.current.setCameraMode(mode);
    }
  };

  const handleAudioToggle = () => {
    setIsAudioEnabled(!isAudioEnabled);
  };

  const handleVolumeChange = (type, value) => {
    if (type === 'ambient') {
      setAmbientVolume(value);
    } else if (type === 'music') {
      setMusicVolume(value);
    }
  };

  if (isLoading) {
    return (
      <div className="fixed inset-0 bg-background flex items-center justify-center z-1300">
        <div className="text-center">
          <div className="w-16 h-16 bg-gradient-to-br from-primary to-primary-600 rounded-full flex items-center justify-center mx-auto mb-6 animate-pulse neon-glow">
            <Icon name="Zap" size={32} color="white" />
          </div>
          <h2 className="text-xl font-heading font-semibold text-text-primary mb-2">
            Initializing SoulDriver
          </h2>
          <p className="text-text-secondary mb-4">
            Connectng to neural network...
          </p>
          <div className="w-64 bg-surface rounded-full h-2 mx-auto">
            <div className="bg-primary h-2 rounded-full animate-pulse" style={{ width: '70%' }} />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-background">
      {/* WebGL 3D Viewport */}
      <WebGLViewport
        ref={viewportRef}
        cameraMode={cameraMode}
        worldData={worldData}
        worldState={worldState}
        isAudioEnabled={isAudioEnabled}
        ambientVolume={ambientVolume}
        musicVolume={musicVolume}
        onCommandExecution={handleCommandExecution}
        onCommandAnimationComplete={handleCommandAnimationComplete} // New prop
      />

      {/* Particle Effects Overlay */}
      {/* Particle Effects removed for performance and clarity */}

      {/* Camera Perspective Toggle - Top Right */}
      <div className="fixed top-20 right-4 z-1100">
        <CameraPerspectiveToggle
          currentMode={cameraMode}
          onModeChange={handleCameraChange}
        />
      </div>

      {/* Audio Controls - Bottom Left */}
      <div className="fixed bottom-24 left-4 z-1100">
        <AudioControls
          isEnabled={isAudioEnabled}
          ambientVolume={ambientVolume}
          musicVolume={musicVolume}
          onToggle={handleAudioToggle}
          onVolumeChange={handleVolumeChange}
        />
      </div>

      {/* Main Command Input - Bottom Center */}
      <div className="fixed bottom-8 left-1/2 transform -translate-x-1/2 w-full max-w-xl z-1150 flex flex-col items-center gap-2">
        <CommandInput onCommand={executeCommandRaw} />

        {/* Quick Actions */}
        <div className="flex gap-2 opacity-70 hover:opacity-100 transition-opacity">
          {['Dance', 'Explore', 'Spawn Coffee'].map(cmd => (
            <button
              key={cmd}
              onClick={() => executeCommandRaw({ command: cmd.toLowerCase(), thought: "User suggested I " + cmd })}
              className="px-3 py-1 bg-surface/50 rounded-full text-xs hover:bg-primary hover:text-white transition-colors border border-white/10"
            >
              {cmd}
            </button>
          ))}
        </div>
      </div>

      {/* Command Queue - Right Edge */}
      <CommandQueue
        isVisible={showCommandQueue}
        onToggle={() => setShowCommandQueue(!showCommandQueue)}
      />

      {/* World Status Indicator - Top Left */}
      <div className="fixed top-20 left-4 z-1100">
        <div className="glass-morphism rounded-lg p-3 min-w-[200px]">
          <div className="flex items-center justify-between mb-2">
            <span className="text-sm font-medium text-text-primary">World Status</span>
            <div className="w-2 h-2 bg-success rounded-full animate-pulse" />
          </div>
          <div className="space-y-1 text-xs text-text-secondary">
            <div className="flex justify-between">
              <span>Time:</span>
              <span className="text-text-primary capitalize">{worldState.timeOfDay}</span>
            </div>
            <div className="flex justify-between">
              <span>Weather:</span>
              <span className="text-text-primary capitalize">{worldState.weather}</span>
            </div>
            <div className="flex justify-between">
              <span>Soul Activity:</span>
              <span className="text-text-primary">{worldData.soul.activity}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Soul Thought Bubble - Center Top */}
      <div className="fixed top-20 left-1/2 transform -translate-x-1/2 z-1100 max-w-md w-full flex flex-col items-center gap-2">
        {/* Autonomous Toggle */}
        <button
          onClick={() => setIsAutonomous(!isAutonomous)}
          className={`
                px-4 py-2 rounded-full backdrop-blur-md border transition-all duration-300 flex items-center gap-2
                ${isAutonomous
              ? 'bg-primary/20 border-primary text-primary shadow-[0_0_15px_rgba(var(--primary-rgb),0.5)]'
              : 'bg-surface/50 border-white/10 text-text-secondary hover:bg-surface/80'}
            `}
        >
          <Icon name={isAutonomous ? "Cpu" : "User"} size={16} />
          <span className="text-sm font-medium">
            {isAutonomous ? "AUTONOMOUS MODE ACTIVE" : "Manual Control"}
          </span>
          {isAutonomous && <span className="flex h-2 w-2 rounded-full bg-primary animate-ping" />}
        </button>

        <div className="glass-morphism rounded-xl p-4 text-center animate-fade-in w-full">
          <div className="flex items-center justify-center space-x-2 mb-2">
            <Icon name="Brain" size={16} className="text-primary" />
            <span className="text-sm font-medium text-text-primary">Soul's Thoughts</span>
            <div className="w-2 h-2 bg-primary rounded-full animate-pulse" title="AI Enhanced" />
          </div>
          <p className="text-sm text-text-secondary italic">
            "{aiThoughts || worldData.soul.lastAction}... The city never sleeps, and neither do the dreams within these walls."
          </p>
        </div>
      </div>

      {/* Product Recommendation Overlay */}
      {currentProduct && (
        <div className="fixed bottom-32 left-1/2 transform -translate-x-1/2 z-1150 max-w-sm w-full animate-slide-up">
          <div className="glass-morphism rounded-xl p-4 border border-accent/30 shadow-[0_0_30px_rgba(var(--accent-rgb),0.2)]">
            <div className="flex justify-between items-start mb-2">
              <span className="text-xs font-bold text-accent uppercase tracking-wider">Soul's Pick</span>
              <button onClick={() => setCurrentProduct(null)} className="text-text-tertiary hover:text-text-primary"><Icon name="X" size={14} /></button>
            </div>
            <h3 className="text-lg font-bold text-text-primary mb-1">{currentProduct.name}</h3>
            <p className="text-sm text-text-secondary mb-3">{currentProduct.description}</p>
            <a
              href={currentProduct.link}
              target="_blank"
              rel="noopener noreferrer"
              className="block w-full text-center bg-accent hover:bg-accent-600 text-white font-bold py-2 rounded-lg transition-colors"
            >
              View Recommendation <Icon name="ExternalLink" size={12} className="inline ml-1" />
            </a>
          </div>
        </div>
      )}

      {/* Performance Indicator - Bottom Right */}
      <div className="fixed bottom-24 right-4 z-1100">
        <div className="glass-morphism rounded-lg p-2 flex items-center space-x-2">
          <div className="w-2 h-2 bg-success rounded-full animate-pulse" />
          <span className="text-xs text-text-secondary">60 FPS</span>
        </div>
      </div>

      {/* Emergency Reset Button - Hidden until needed */}
      <button
        className="fixed top-1/2 left-4 transform -translate-y-1/2 z-1200 opacity-0 hover:opacity-100 transition-opacity duration-300 bg-error hover:bg-error-600 text-white p-2 rounded-lg"
        onClick={() => window.location.reload()}
        title="Emergency Reset"
      >
        <Icon name="RotateCcw" size={16} />
      </button>

      {/* Platform Overlays */}
      <AuthOverlay />
      <CommunityChat />
    </div>
  );
});

const MemoizedMain3DWorldInterface = memo(Main3DWorldInterface);
MemoizedMain3DWorldInterface.displayName = 'Main3DWorldInterface';

export default MemoizedMain3DWorldInterface;