import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const GlobalNavigation = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();

  const navigationItems = [
    {
      label: 'World',
      path: '/main-3d-world-interface',
      icon: 'Globe',
      tooltip: 'Enter the immersive 3D world'
    },
    {
      label: 'Create',
      path: '/creative-tools-hub',
      icon: 'Wrench',
      tooltip: 'Access creative tools and customization'
    },
    {
      label: 'Community',
      path: '/community-social-features',
      icon: 'Users',
      tooltip: 'Connect with other users and share experiences'
    },
    {
      label: 'Account',
      path: '/payment-action-upgrade',
      icon: 'CreditCard',
      tooltip: 'Manage your account and upgrades'
    }
  ];

  const adminItems = [
    {
      label: 'Admin',
      path: '/admin-control-panel',
      icon: 'Settings',
      tooltip: 'Administrative controls'
    }
  ];

  const isActive = (path) => location.pathname === path;

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
  };

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 768) {
        setIsMobileMenuOpen(false);
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }

    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isMobileMenuOpen]);

  return (
    <>
      <nav className="fixed top-0 left-0 right-0 z-1000 glass-morphism border-b border-white/10">
        <div className="px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            {/* Logo */}
            <Link 
              to="/main-3d-world-interface" 
              className="flex items-center space-x-2 transition-smooth hover:opacity-80"
            >
              <div className="w-8 h-8 bg-gradient-to-br from-primary to-primary-600 rounded-lg flex items-center justify-center">
                <Icon name="Zap" size={20} color="white" />
              </div>
              <span className="font-heading font-bold text-xl text-text-primary">
                Soul Drive
              </span>
            </Link>

            {/* Desktop Navigation */}
            <div className="hidden md:flex items-center space-x-1">
              {navigationItems.map((item) => (
                <Link
                  key={item.path}
                  to={item.path}
                  className={`group relative px-4 py-2 rounded-lg transition-smooth flex items-center space-x-2 ${
                    isActive(item.path)
                      ? 'bg-primary/20 text-primary border border-primary/30' :'text-text-secondary hover:text-text-primary hover:bg-white/5'
                  }`}
                  title={item.tooltip}
                >
                  <Icon name={item.icon} size={18} />
                  <span className="font-medium">{item.label}</span>
                  {isActive(item.path) && (
                    <div className="absolute inset-0 rounded-lg neon-glow opacity-30" />
                  )}
                </Link>
              ))}
              
              {/* Admin Access */}
              {adminItems.map((item) => (
                <Link
                  key={item.path}
                  to={item.path}
                  className={`group relative px-4 py-2 rounded-lg transition-smooth flex items-center space-x-2 ml-4 ${
                    isActive(item.path)
                      ? 'bg-accent/20 text-accent border border-accent/30' :'text-text-tertiary hover:text-accent hover:bg-accent/5'
                  }`}
                  title={item.tooltip}
                >
                  <Icon name={item.icon} size={18} />
                  <span className="font-medium">{item.label}</span>
                </Link>
              ))}
            </div>

            {/* Mobile Menu Button */}
            <button
              onClick={toggleMobileMenu}
              className="md:hidden p-2 rounded-lg text-text-secondary hover:text-text-primary hover:bg-white/5 transition-smooth"
              aria-label="Toggle mobile menu"
            >
              <Icon name={isMobileMenuOpen ? 'X' : 'Menu'} size={24} />
            </button>
          </div>
        </div>

        {/* Mobile Menu Overlay */}
        {isMobileMenuOpen && (
          <div className="md:hidden fixed inset-0 top-16 z-1100">
            <div 
              className="absolute inset-0 bg-background/80 backdrop-blur-md"
              onClick={closeMobileMenu}
            />
            <div className="relative bg-surface/95 backdrop-blur-sm border-r border-white/10 w-80 h-full animate-slide-down">
              <div className="p-6 space-y-4">
                {navigationItems.map((item) => (
                  <Link
                    key={item.path}
                    to={item.path}
                    onClick={closeMobileMenu}
                    className={`group flex items-center space-x-3 p-4 rounded-lg transition-smooth ${
                      isActive(item.path)
                        ? 'bg-primary/20 text-primary border border-primary/30' :'text-text-secondary hover:text-text-primary hover:bg-white/5'
                    }`}
                  >
                    <Icon name={item.icon} size={20} />
                    <div>
                      <div className="font-medium">{item.label}</div>
                      <div className="text-sm text-text-tertiary">{item.tooltip}</div>
                    </div>
                  </Link>
                ))}
                
                <div className="border-t border-white/10 pt-4">
                  {adminItems.map((item) => (
                    <Link
                      key={item.path}
                      to={item.path}
                      onClick={closeMobileMenu}
                      className={`group flex items-center space-x-3 p-4 rounded-lg transition-smooth ${
                        isActive(item.path)
                          ? 'bg-accent/20 text-accent border border-accent/30' :'text-text-tertiary hover:text-accent hover:bg-accent/5'
                      }`}
                    >
                      <Icon name={item.icon} size={20} />
                      <div>
                        <div className="font-medium">{item.label}</div>
                        <div className="text-sm text-text-quaternary">{item.tooltip}</div>
                      </div>
                    </Link>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </nav>

      {/* Spacer to prevent content overlap */}
      <div className="h-16" />
    </>
  );
};

export default GlobalNavigation;