import React from 'react';
import Icon from 'components/AppIcon';

const PaymentCard = ({ tier, formatPrice, isProcessing, onPayment, error }) => {
  if (!tier) return null;

  return (
    <div className="glass-morphism rounded-xl p-6 border-2 border-primary/30">
      <div className="text-center mb-6">
        <h3 className="text-2xl font-heading font-bold text-text-primary mb-2">
          {tier.name}
        </h3>
        <div className="text-4xl font-bold text-primary mb-2">
          {formatPrice(tier.price)}
        </div>
        <p className="text-text-secondary text-sm">{tier.description}</p>
        {tier.savings && (
          <div className="inline-block bg-success/20 text-success text-xs font-medium px-2 py-1 rounded-full mt-2">
            {tier.savings}
          </div>
        )}
      </div>

      <div className="space-y-4 mb-6">
        <div className="flex items-center justify-between p-3 bg-surface/30 rounded-lg">
          <span className="text-text-secondary">Actions Included:</span>
          <div className="flex items-center space-x-2">
            <Icon name="Zap" size={16} className="text-primary" />
            <span className="font-data font-semibold text-text-primary">{tier.actions}</span>
          </div>
        </div>
        
        <div className="flex items-center justify-between p-3 bg-surface/30 rounded-lg">
          <span className="text-text-secondary">Estimated Playtime:</span>
          <span className="font-medium text-text-primary">{tier.estimatedTime}</span>
        </div>

        <div className="flex items-center justify-between p-3 bg-surface/30 rounded-lg">
          <span className="text-text-secondary">Expires:</span>
          <span className="font-medium text-text-primary">Never</span>
        </div>
      </div>

      {error && (
        <div className="mb-4 p-3 bg-error/10 border border-error/20 rounded-lg">
          <div className="flex items-center space-x-2">
            <Icon name="AlertCircle" size={16} className="text-error" />
            <span className="text-error text-sm">{error}</span>
          </div>
        </div>
      )}

      <button
        onClick={() => onPayment(tier)}
        disabled={isProcessing}
        className="w-full bg-primary hover:bg-primary-600 disabled:bg-surface disabled:text-text-tertiary text-white font-semibold py-4 px-6 rounded-lg transition-smooth flex items-center justify-center space-x-2 neon-glow disabled:shadow-none"
      >
        {isProcessing ? (
          <>
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
            <span>Processing Payment...</span>
          </>
        ) : (
          <>
            <Icon name="CreditCard" size={20} />
            <span>Pay with PayPal</span>
          </>
        )}
      </button>

      <div className="text-center mt-4">
        <p className="text-xs text-text-tertiary">
          Secure payment powered by PayPal
        </p>
      </div>
    </div>
  );
};

export default PaymentCard;